// GENERATED by tools/literary/compile.mjs. Do not edit this file.
export const literarySeason = {"schemaVersion":1,"edition":"literary-draft-01-10","episodes":10,"sceneOrder":{"1":[1,2,65,3,4],"2":[5,6,7,8,66],"3":[9,10,11,12],"4":[13,14,15,16],"5":[17,18,19,20,21,61],"6":[22,23,24,25,58,26],"7":[27,59,28,49,29,52,30,55,31,62],"8":[32,50,33,53,34,56,35,63],"9":[36,37,51,38,54,39,57,40,64,60],"10":[41,42,43,44,45,46,47,48]},"scenes":[{"id":"S01","title":"Кефлавик, день 1. Красный чемодан","episode":1,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["Красный чемодан Алисы появился на ленте последним и сразу попытался уехать обратно в служебный проём.","— Даже багаж понял, что это сомнительная идея, — сказала она в телефон.","Марина, её редактор, в голосовом сообщении отвечать не могла. Алиса прижала чемодан коленом, ухватила за боковую ручку и услышала за спиной:","— Помочь или это важная часть личного знакомства с Исландией?","Мужчина держал картонную табличку с расплывшейся надписью «АЛИСА, ЖУРНАЛИСТ». Дождь превратил последние буквы в серое облако. На шее у него висела камера, но объектив смотрел в пол.","— Если поможешь, я не смогу написать, что победила чемодан сама.","— Напиши, что использовала местного специалиста.","— Ты не местный.","— Уже провалил первое собеседование.","Он протянул руку, но не коснулся ручки.","— Ник. Можно?","Алиса кивнула. Чемодан легко сошёл с ленты, словно всё это время ждал человека с правильным уровнем самоуверенности.","— Ты снимаешь встречу? — спросила она.","— Нет. Эрик сказал, что после перелёта люди похожи на собственные неудачные фотографии в паспорте. Я решил не разрушать отношения в первые тридцать секунд.","— Разумный Эрик.","— Не спеши. Он ещё заставит тебя пересчитать носки.","За стеклянными дверями аэропорта дождь летел почти горизонтально. Возле выхода стоял высокий мужчина в тёмной куртке, без таблички и камеры. Он разговаривал с сотрудником проката и одновременно следил за тем, как ветер толкал пустую багажную тележку к дороге. Поймал её одной рукой, вернул под навес и только тогда посмотрел на Алису.","— Эрик. Добро пожаловать. Машина в десяти минутах, если Ник не поведёт вас короткой дорогой.","— Там была дверь, — возразил Ник.","— На склад.","— Всё равно короче.","Улыбка у Эрика появилась не на губах, а в глазах — быстро и будто без разрешения. Алиса успела заметить её прежде, чем он принял у Ника чемодан и поставил рядом с остальными сумками.","— Вас четверо? — спросила она.","— Нас, — поправил Ник. — Ты уже внутри бедствия.","Четвёртый участник стоял у автомата с кофе. Алиса узнала его раньше, чем он повернулся. По тому, как он держал бумажный стакан — большим пальцем у самого края, будто тот мог внезапно выскользнуть. По серому шарфу, который она когда-то подарила ему на день рождения и который совершенно точно не собиралась узнавать через два года.","Дамир увидел её и замер ровно на один вдох.","— Привет, — сказал он.","Ник перевёл взгляд с него на Алису и безошибочно понял, что камера сейчас особенно не нужна.","— Вы знакомы? — спросил Эрик.","— Были, — ответила Алиса.","Дамир поставил кофе на подоконник.","— Я не знал, что журналистка — ты.","— А я не знала, что врач — ты. Отлично составленные анкеты.","— В списке от организатора было только название издания. Без твоего имени.","— А мне — только «врач на встречу с клиникой».","Ник тихо поднял табличку и посмотрел на размокшее имя, словно пытался найти там инструкцию для чрезвычайной ситуации.","Эрик не стал спрашивать, насколько плохо они расстались и не нужно ли срочно менять состав группы. Он взглянул на часы.","— До Рейкьявика около пятидесяти километров. По дороге есть остановка. Можем выпить кофе там или сначала уехать отсюда.","Алиса посмотрела на Дамира. Тот не делал шаг навстречу, и за это она была ему почти благодарна."]},{"level":4,"title":"Выбор S01-C1 — где провести первый час дороги","paragraphs":["Выбирается один фрагмент. Посадка не фиксирует романтический маршрут."]},{"level":5,"title":"A. Сесть впереди рядом с Эриком","paragraphs":["— Можно вперёд? — спросила Алиса.","— Конечно. Куртку лучше снять: печка со стороны пассажира работает слишком усердно.","Она устроилась рядом с картой. Эрик показал ей ручку двери, которую надо было чуть приподнять, чтобы закрыть, и молча дождался, пока Алиса сама справится.","— Ты можешь говорить, если я смотрю не туда, — сказала она.","— Сейчас смотришь туда. Выезд справа.","Алиса улыбнулась и открыла на телефоне карту. Из заднего ряда Ник спросил, считается ли место спереди служебным повышением. Эрик ответил лишь после того, как влился в поток:","— Там лучше видно дорогу.","Алиса заметила, что он дал ей короткий честный ответ, не пытаясь разрядить встречу с Дамиром."]},{"level":5,"title":"B. Сесть с Ником","paragraphs":["Ник отвёл для неё место у окна в последнем ряду и, когда она села, положил табличку между ними надписью вниз.","— Я могу просто помолчать, — сказал он.","— Не уверена, что тебе это по силам.","— Проверим до первого съезда.","Он действительно молчал. Потом заметил, что ремень её чемодана оказался под сиденьем, и подтянул сумку ногой, не касаясь Алисы.","— Спасибо, — сказала она.","— Пожалуйста.","Это оказалось приятнее его первых шуток."]},{"level":5,"title":"C. Сесть рядом с Дамиром","paragraphs":["Алиса сама открыла заднюю дверь. Дамир убрал с соседнего сиденья свой рюкзак.","— Ты уверена? — спросил он.","— В том, что могу выбрать место, да.","Он кивнул и больше не спрашивал. Когда машина тронулась, его чашка с кофе качнулась в подстаканнике; Алиса придержала её, как делала прежде, и тут же отпустила.","— Я могу пересесть на остановке, — сказал Дамир.","— Пока не надо.","Он повернулся к окну. Их плечи не соприкасались, но поездка уже не могла притворяться встречей незнакомых людей."]},{"level":5,"title":"Общее продолжение","paragraphs":["За окном тянулись чёрные поля лавы и низкое небо; океан то появлялся, то исчезал за стеной дождя. Ник перевернул табличку с её именем и написал на обороте: «ГРУППА, КОТОРАЯ ЕЩЁ НЕ ПЕРЕДУМАЛА». Затем убрал её под сиденье. Алиса впервые за утро смогла смотреть не на пассажиров, а на дорогу."]}]},{"id":"S02","title":"Дорога в Рейкьявик. Четыре версии одного маршрута","episode":1,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["Когда разговор о местах и багаже иссяк, какое-то время они слушали только дворники.","Ник попытался подключить телефон к машине, случайно включил исландское радио и оставил его, заявив, что неизвестность полезна для монтажа. Женский голос пел что-то медленное и сердитое.","— Она поёт о любви? — спросила Алиса.","— О налоговой декларации, — ответил Эрик.","Ник повернулся к нему:","— Ты серьёзно?","— Нет.","На этот раз улыбка дошла до губ. Алиса отметила про себя: шутит редко, но не случайно.","Эрик положил на приборную панель распечатанный маршрут. На листе были отмечены ночёвки и запасные дороги.","— Маршрут собрала «Северная дорога», маленькое местное бюро, — сказал он. — Марина купила у них место для тебя. Ник снимает их дорожный фильм. Я веду машину и прогулки.","— А Дамир? — спросила Алиса, не оборачиваясь.","— Забронировал свободное место сам, — ответил Дамир. — Через клинику узнал, что эта группа будет в Акюрейри к моей встрече. Я не видел список участников.","Алиса посмотрела на шапку маршрута. Фамилий там не было — только номера комнат и четыре места в машине. Совпадение не стало приятнее от объяснения, но перестало выглядеть чьей-то хитростью.","— Три недели, — сказал Эрик. — Южный берег, восточные фьорды, север, потом запад. В октябре из-за погоды остановки иногда меняются местами.","Алиса свернула карту так, чтобы видеть день встречи в Акюрейри. Дамир действительно должен был быть там на шестнадцатый день дороги, а не шестнадцатого числа.","Ник наклонился между сиденьями:","— У меня просьба. Если мы меняем маршрут, говори заранее. Мне нужен свет.","— Свету всё равно, предупредил я тебя или нет.","— Но мне не всё равно.","— Поэтому у тебя будет прогноз утром и решение перед выездом.","Дамир листал письмо на телефоне.","— Встреча в Акюрейри остаётся на шестнадцатый день поездки?","— Если дорога открыта — да, — сказал Эрик. — Если нет, клиника умеет пользоваться видеосвязью.","— Они просили очно.","— Если дорогу закроют, предупредим их в тот же день.","В другой день Алиса решила бы, что Эрик отвечает слишком коротко. Сейчас ей понравилось, что он не обещает невозможного ради спокойствия незнакомых людей.","— А моя работа где помещается? — спросила она.","— Везде, где она не задерживает остальных на опасной дороге.","— Поняла, — сказала Алиса. — Лучше заранее скажи, когда нельзя останавливаться для заметок.","— Покажу на карте после кофе.","Дамир неожиданно рассмеялся. Алиса повернулась. Это был знакомый звук, но немного изменившийся — ниже и свободнее. Раньше он смеялся так только дома, когда никто не мог позвонить из больницы. Теперь, похоже, умел и в машине с незнакомыми людьми.","Эрик остановился у придорожного кафе. Ветер бил в двери так, что выходить пришлось по одному. Внутри пахло кофе, мокрой шерстью и корицей. Пока остальные выбирали булочки, Алиса перезвонила Марине.","— Три портрета и один текст от тебя, — напомнила редактор. — Не рекламный отчёт для бюро. Ты едешь за счёт издания, поэтому можешь написать, что маршрут не понравился. Первый абзац пришли вечером четвёртого дня, остальное — к возвращению.","— Ник снимает для бюро, — сказала Алиса.","— Его фильм не твой материал. Договоритесь только о том, кого и когда можно снимать.","Алиса обещала прислать абзац и вернулась к столу. Теперь ей было понятно, какие вопросы она задаёт как журналистка, а какие — просто потому, что ей хочется знать ответ.","За столом Алиса открыла блокнот.","— Давайте быстро. Мне нужны не биографии, а причины, по которым вы согласились провести три недели в одной машине.","— Ты первая, — сказал Ник. — Почему согласилась?","— Я задаю вопросы.","— Это не причина. Это способ не отвечать.","Эрик размешивал сахар в кофе и смотрел на неё с почти незаметным интересом. Дамир изучал меню так сосредоточенно, будто там могла быть подсказка.","— Хорошо, — сказала Алиса. — Мне надоело писать тексты, после которых хочется только купить билет. Я хочу написать тот, после которого хочется что-то решить.","Ник опустил локти со стола.","— Уже лучше анкеты.","— Теперь ты.","— «Северная дорога» наняла меня снять фильм о поездке. Я уговорил их оставить в кадре людей, а не только красивые места. После прошлого фильма мне не хочется ещё одного каталога видов.","— О тебе?","— Я надеялся, что до этого вопроса у нас будет хотя бы десерт.","Эрик сказал:","— Я уже водил группы для этого бюро. Нужен был человек, который знает октябрьскую дорогу.","— Это официальная версия, — заметила Алиса.","— Другой пока нет.","Дамир закрыл меню.","— Встреча в клинике приходится на северную часть маршрута. У меня три недели отпуска между контрактами; место я оплатил сам. Если соглашусь на год в Акюрейри, хочу знать не только больницу и квартиру.","Алиса подняла глаза.","— До того, как отвечать. Новая привычка?","Воздух за столом стал плотнее. Дамир не отвёл взгляд.","— Да.","Ник взял булочку и повернул её разрезом к себе, демонстративно изучая изюм. Эрик сделал глоток кофе.","— Через десять минут выезжаем, — сказал Эрик. — Если нужно дольше, скажи сейчас.","Алиса сказала, что готова ехать. Разговор с Дамиром подождёт."]},{"level":4,"title":"Выбор S02-C1 — первый подход к материалу","paragraphs":["Выбирается один фрагмент; пометки о состоянии — для дальнейшего авторского учёта, не часть реплик."]},{"level":5,"title":"A. Сначала наблюдать (`careerThesis=people`)","paragraphs":["Алиса не задала второго вопроса. Ник перестал изображать интерес к изюму и наконец откусил булочку. Дамир отложил закрытое меню. Эрик посмотрел на часы, но не поторопил её.","Она записала: «После ответа Дамира каждый дал ему помолчать по-своему». Неровная заметка, зато о людях, а не о дороге. Ник увидел её краем глаза, но не стал просить показать."]},{"level":5,"title":"B. Начать с места (`careerThesis=place`)","paragraphs":["— Как называется этот городок? — спросила Алиса Эрика. — И почему вы остановились здесь, а не у заправки дальше?","— Вогар, — сказал Эрик и показал поворот на карте. — Сюда можно свернуть с дороги и спокойно выйти из машины, не подставляя дверь ветру.","— Вот об этом я и хочу писать, — сказала Алиса. — Не о виде из окна, а о том, как дорога меняет наши решения.","Она записала название городка и то, как Ник придержал дверь незнакомой пожилой паре."]},{"level":5,"title":"C. Спросить о решении (`careerThesis=own-choice`, `damirDirect=true`)","paragraphs":["— Дамир, ты уже знаешь, что ответишь клинике? — спросила Алиса.","Он убрал телефон экраном вниз.","— Нет. Поэтому и приехал раньше встречи.","— Для материала мне важно понять, что человек проверяет в дороге, кроме списка мест. Но если не хочешь об этом говорить, не надо.","— Как мне жить в этом месте. Но об этом я пока не готов говорить для статьи.","— Хорошо. Тогда не для статьи, — сказала Алиса и закрыла блокнот.","Она не получила интервью. Взамен узнала, что он способен отказать ей как журналистке, не уходя от неё как от человека."]},{"level":5,"title":"Общее продолжение","paragraphs":["На обратном пути к машине Ник отдал Алисе половину булочки: она так и не заказала еду. Эрик подождал у двери, пока все застегнули куртки. Дамир выбросил пустые стаканы и не попытался остаться с ней наедине."]}]},{"id":"S65","title":"Рейкьявик, вечер. Ужин без ключа","episode":1,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["Гостевой дом оказался старым трёхэтажным зданием с узкими лестницами, скрипучими дверями и общей кухней в полуподвале. Эрик раздал ключи от комнат, показал аварийный выход и обнаружил, что ключа от кухни нет.","— Организатор сказал, он на синем брелоке, — произнёс Ник.","— Это зелёный.","— При таком освещении все решения спорные.","Эрик проверил связку ещё раз.","— Хозяйка будет через час.","— Через час я съем камеру, — сказал Ник.","— Начни с объектива, там меньше пластика, — посоветовал Дамир.","Алиса посмотрела на него. Раньше Дамир шутил редко и только после десяти вечера. Часы показывали семь. Возможно, другая страна действительно меняла часовые пояса личности.","— В двух кварталах магазин, — сказал Эрик. — Купим то, что не требует кухни.","— Это звучит как личный вызов, — ответила Алиса. — Я умею готовить ужин без кухни.","— Умеешь открывать упаковки?","— Уже начинаю жалеть, что заметила твоё чувство юмора.","В магазин пошли все: Ник настоял, что голодный человек выбирает продукты честнее. У входа Эрик взял корзину. Алиса забрала вторую.","— Список? — спросил он.","— Импровизация.","— Тогда я возьму хлеб и сыр, чтобы у нас был план эвакуации.","Ник вернулся с банкой маринованной свёклы, шоколадным молоком и пачкой вафель.","— Это не ужин, — сказал Дамир.","— Это три акта. Сначала непонимание, потом риск, потом сладкий финал.","Дамир положил в корзину помидоры, йогурт и копчёную рыбу.","— А это медицинская конференция? — спросил Ник.","— Это еда.","Алиса нашла упаковку готовых лепёшек и банку оливок. Эрик добавил яблоки, потом, убедившись, что никто не смотрит, — коричные булочки.","— Вот, значит, где твоя слабость, — сказала Алиса.","— Это запас на случай плохой погоды.","— В помещении?","— Кухню мы уже потеряли. Булочки оставлю на завтра.","Она улыбнулась: он не стал придумывать оправдание. Эрик посмотрел на неё чуть дольше необходимого и первым отвернулся к полке.","Они устроились в коридоре у закрытой кухни. Ник разложил продукты на перевёрнутом чемодане, как ведущий дешёвого кулинарного шоу.","— У каждого две минуты и один продукт. Задача — доказать, что он был необходим.","— Я отказываюсь доказывать необходимость хлеба, — сказал Эрик.","— Сильная позиция традиционалиста.","Дамир взял нож из дорожного набора и нарезал помидоры прямо на крышке контейнера. Алиса заметила тонкий белый шрам на его запястье. Раньше его не было.","— Откуда? — спросила она и тут же пожалела: вопрос прозвучал так, будто у неё всё ещё есть право знать.","Дамир посмотрел на шрам.","— Велосипед. В Брюсселе. Дождь, трамвайные рельсы и уверенность, что я лучше понимаю сцепление колёс, чем физика.","— Проиграл физике?","— Убедительно.","Ник протянул ему вафлю.","— За честность.","Разговор перескочил на худшие дорожные травмы. Ник рассказал, как однажды упал с пирса в Стамбуле, спас камеру и потерял оба ботинка. Эрик признался, что в двенадцать лет примерз языком к металлическим перилам и потом месяц утверждал, что проверял школьный учебник. Алиса рассказала о шраме на колене после попытки перепрыгнуть фонтан на выпускном.","— Ты говорила, что упала с велосипеда, — сказал Дамир.","— Родителям. Ты получил взрослую версию позже.","— Значит, у меня была привилегия.","— Была.","Слово легло между ними без удара. Дамир кивнул и передал ей тарелку с помидорами.","Хозяйка пришла через сорок минут, открыла кухню запасным ключом и обнаружила их ключ в замке с внутренней стороны. Ник объявил это первым исландским чудом. Эрик заметил, что чудо оставило им грязную посуду. Вместе они убрали кухню, хотя почти не пользовались ею.","Перед тем как разойтись, Алиса увидела на подоконнике бумажную табличку из аэропорта. Ник дописал под «ГРУППОЙ, КОТОРАЯ ЕЩЁ НЕ ПЕРЕДУМАЛА»: «ДЕНЬ ПЕРВЫЙ. ПОТЕРИ: ОДИН КЛЮЧ. НАЙДЕН: ТАМ ЖЕ».","Она сфотографировала табличку на телефон.","— Можно? — спросил Ник, заметив.","— Для себя — да.","— Я тоже для себя.","Он не поднял камеру. Вместо этого встал рядом, чтобы посмотреть на снимок на её экране.","Ночью Алиса долго не могла уснуть. Дом отвечал на ветер деревянными вздохами; где-то над ней прокатывался чемодан, в соседней комнате кто-то дважды уронил зарядку. В половине первого она сдалась, надела свитер и спустилась за водой.","На кухне горел свет. Эрик сидел у окна и ел одну из тех самых «аварийных» булочек. Перед ним лежал прогноз, но телефон был перевёрнут экраном вниз.","— Плохая погода? — спросила Алиса.","— Хорошая булочка.","— Ты всегда отвечаешь только на удобную половину вопроса?","— Нет. Иногда вообще молчу.","Он отломил половину и протянул ей. Алиса села напротив.","— Завтра будет дождь, — сказал Эрик. — Но не тот, который меняет план.","— А ты умеешь проводить день, ничего не планируя?","— Конечно.","— Когда последний раз?","Эрик посмотрел в окно, где отражалась только кухня.","— Не помню.","— Значит, не умеешь.","— Возможно, я просто давно не практиковался.","Он сказал это без грусти и без приглашения жалеть. Алиса поймала себя на желании узнать, что заставляет человека так тщательно оставлять себе запасной выход.","В коридоре послышались шаги. Ник вошёл босиком, с камерой в одной руке и носком в другой.","— Не спрашивайте.","— Я не собирался, — сказал Эрик.","— Поэтому ты мой любимый человек в этой поездке.","— Мы знакомы семь часов.","— Не обесценивай интенсивность.","Ник открыл холодильник, увидел только йогурт и закрыл.","— Кто съел вафли?","— Ты, — сказала Алиса.","— Тогда я хотя бы знаю преступника.","Он сел рядом с ней и положил камеру на стол. На экране застыл случайный кадр из магазина: Эрик держит корзину, Дамир читает этикетку, Алиса смеётся чему-то за границей изображения.","— Ты снимал? — спросила она.","— Проверял свет. Кадр случайный. Удалить?","Алиса посмотрела на себя. Она не помнила момента, не знала, над чем смеялась, и именно поэтому фотография нравилась ей больше постановочной.","— Оставь пока. Но не для фильма.","— Пока и не для фильма, — повторил Ник.","Дамир появился последним — уже в футболке, без шарфа, с сонным лицом. Увидел их за столом и остановился.","— Это собрание людей с нарушенным режимом?","— Вступительный взнос — еда, — сказал Ник.","Дамир молча достал из рюкзака пачку орехов.","— Принят единогласно.","Они сидели почти час. Говорили о худших гостиницах, где им доводилось ночевать. Ник однажды жил в комнате без окна, зато с чужим попугаем. Эрик — в домике, дверь которого открывалась только изнутри, и каждое утро хозяин выпускал гостей как домашний скот. Дамир провёл ночь в ординаторской под столом, потому что диван занял хирург с температурой.","— А ты? — спросил Ник Алису.","— Однажды редакция поселила меня в свадебном номере. Там была круглая кровать, зеркало на потолке и полотенца в форме лебедей.","— Одна?","— С фотографом шестидесяти трёх лет. Он отказался заходить, пока лебедей не унесли.","— Разумный человек, — сказал Эрик.","— Ты боишься лебедей?","— Нет. Я бы тоже попросил их убрать.","Алиса рассмеялась и увидела, что он тоже смеётся — открыто, без своей короткой внутренней паузы. Это изменило его лицо сильнее, чем она ожидала.","Когда они разошлись, Дамир задержался у двери.","— Я рад, что ты смеёшься, — сказал он тихо.","В прежней жизни такая фраза могла бы звучать как право на её настроение. Сейчас он произнёс её и ушёл, не ожидая ответа.","Алиса вернулась в комнату и записала: «Ночью люди говорят правду не потому, что становятся смелее. Просто устают поддерживать дневную версию себя».","Потом зачеркнула. Слишком похоже на цитату человека, которого никто не приглашал на кухню.","Вместо этого написала: «Эрик попросил бы убрать лебедей из номера»."]}]},{"id":"S03","title":"Рейкьявик, день 2. Задание","episode":1,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["Утром дождь превратился в мелкую взвесь. Алиса проснулась раньше будильника и нашла гостиную пустой. На столе лежала карта с запиской Эрика: «Прогноз изменился. Þingvellir после десяти. Завтрак до девяти. Кофе слева».","Справа стояла банка растворимого кофе.","Алиса улыбнулась и позвонила редактору.","— Доехали? — спросила Марина вместо приветствия.","— Да. Я поговорила с тремя участниками. Об одном нужно сказать сразу.","Алиса провела пальцем по краю карты.","— Он мой бывший.","Марина помолчала.","— Это помогает материалу?","— Пока мешает мне спать.","— Значит, в текст не идёт. Бывший — не жанр. Мне нужны люди, а не совпадение для обложки.","Алиса почувствовала облегчение и раздражение одновременно.","— Ты можешь взять другого героя вместо него, — сказала Марина. — Для меня важнее честный текст.","— Пока оставлю его. Если не смогу держать интервью отдельно от личного, скажу.","— Договорились. Первый абзац жду вечером четвёртого дня, как говорили вчера. Не весь текст.","Алиса открыла вчерашние записи. Заголовок у неё ещё не сложился, зато был первый вопрос, с которым можно идти дальше."]},{"level":5,"title":"Если в S02-C1 выбрано A — люди","paragraphs":["Она обвела вчерашнюю строку о том, как каждый выдержал паузу после ответа Дамира. Марине пока не нужен был вывод; Алисе хотелось увидеть, сохранится ли это на дороге, где все устанут."]},{"level":5,"title":"Если в S02-C1 выбрано B — место","paragraphs":["Она проверила название придорожного кафе и расстояние до следующего. Марина просила портреты людей, но Алиса хотела показать их через места, где им приходилось менять привычки."]},{"level":5,"title":"Если в S02-C1 выбрано C — собственный выбор","paragraphs":["Она записала ответ Дамира дословно и отделила его чертой от текста для редакции. Он не разрешал использовать это как интервью. Пока важнее было выполнить обещание, чем получить удачную цитату."]},{"level":5,"title":"Общее продолжение","paragraphs":["Дамир вошёл в гостиную с двумя чашками.","— Не ожидал встретить тебя с утра, — сказал Дамир.","— Я тоже. Кухня у нас одна.","Он поставил одну чашку на дальний край стола, не придвигая к ней.","— Это мне?","— Если захочешь. Чёрный, немного молока отдельно.","Он всё ещё помнил. Алиса могла бы рассердиться на память, но память не спрашивала её разрешения ни у кого из них.","— У тебя отпуск на все три недели? — спросила Алиса.","— До конца месяца. После прошлого контракта. Если подпишу следующий, такого времени больше не будет. Я решил посмотреть, где мне предлагают жить, а не только работать.","— Понятно.","Он сел в кресло у окна. Не рядом.","— Я не собирался создавать тебе трудности на работе, — сказал он.","— Уже создал. Но не специально.","Дамир принял ответ, хотя по тому, как он держал чашку, Алиса видела: ему хотелось возразить."]},{"level":5,"title":"Если в S01-C1 Алиса села рядом с Дамиром","paragraphs":["— В машине вчера было проще, — сказал он.","— Там можно было смотреть в окно. Здесь уже нужно решать, о чём говорить.","Он кивнул и отодвинул вторую чашку ближе к ней. Алиса взяла её сама."]},{"level":5,"title":"Если в S01-C1 Алиса сидела с Эриком или Ником","paragraphs":["— Вчера я не стал звать тебя поговорить наедине, — сказал Дамир.","— Я заметила.","Он хотел что-то добавить, но в коридоре хлопнула дверь. Алиса взяла чашку и не попросила продолжать."]},{"level":5,"title":"Общее продолжение","paragraphs":["Дамир улыбнулся. Алиса тоже, совсем немного. Неловкость не исчезла, но перестала занимать всю комнату.","После завтрака у них оставалось сорок минут до выезда. Ник ушёл искать переходник, Эрик проверял машину, а Дамир поднялся за курткой. Алиса решила пройти один квартал до гавани и обнаружила, что Дамир идёт следом — не за ней, а к аптеке на углу.","— Я не преследую тебя, — сказал он.","— Хорошо, что уточнил.","— Плохое совпадение маршрутов.","— У нас впереди три недели плохих совпадений маршрутов.","У светофора они остановились рядом. Улица была почти пустой, дождь висел в воздухе и не падал.","— Ты рассказала редактору? — спросил Дамир.","— Что ты здесь? Да.","— И?","— Она сказала, что бывший — не жанр.","— Мне нравится твой редактор.","— Не спеши. Она ещё может попросить твою медицинскую карту для врезки.","Дамир улыбнулся, потом стал серьёзнее.","— Если ты не хочешь писать обо мне, я пойму.","— Я должна написать о трёх участниках.","— Тогда могу отвечать только письменно.","— Это будет выглядеть трусливо.","— Зато аккуратно.","— Ты всегда выбирал аккуратно.","Фраза вышла острее, чем она хотела. Загорелся зелёный. Они перешли дорогу, не продолжая.","У воды чайки дрались из-за бумажного пакета. Алиса остановилась посмотреть. Дамир тоже.","— Я выбрал работу не потому, что она была важнее тебя, — сказал он. — Я выбрал решение, в котором не нужно было рисковать отказом.","— Это очень удобная разница.","— Да.","Он не защищался. От этого злиться было сложнее.","— Я не хочу разбирать это сейчас, — сказала Алиса.","— Не будем.","— И не жди, что поездка всё исправит.","— Не жду.","Чайка вырвала пакет и взлетела. Вторая осталась на тротуаре, возмущённо крича ей вслед.","— Вот она ждёт, — сказал Дамир.","Алиса фыркнула.","— Не смей разряжать разговор чайкой.","— Поздно. Она очень убедительна.","Они дошли до аптеки. Дамир купил пластыри и средство от укачивания для группы, хотя никто не просил.","— Вот это всё ещё старая привычка, — сказала Алиса.","— Какая?","— Решать, что всем понадобится.","Он посмотрел на покупки.","— Вернуть?","Она ожидала объяснения, почему пластыри объективно полезны. Вместо этого Дамир действительно повернулся к кассе.","— Не надо. Просто спроси потом, брать ли их в общий рюкзак.","— Спрошу.","На улице он протянул ей чек.","— Зачем?","— Ты журналист. Вдруг понадобится доказательство моего развития.","— Пока это доказательство покупки пластырей.","— Маленькие шаги.","Они вернулись к гостевому дому отдельно: Дамир задержался у кофейни, Алиса пошла дальше. Это было почти бессмысленно, но ей понравилось, что он понял необходимость этих двадцати метров."]},{"level":4,"title":"Выбор S03-C1 — Как Алиса закончит разговор с Дамиром после аптеки?","paragraphs":[]},{"level":5,"title":"A. Написать ему короткое сообщение","paragraphs":["У входа Алиса написала Дамиру: «Спасибо, что не стал продолжать разговор у воды». Ответ пришёл, когда она снимала мокрые ботинки: «И тебе. Увидимся за завтраком». Она не стала придумывать, что это должно означать."]},{"level":5,"title":"B. Оставить эту прогулку без продолжения","paragraphs":["Алиса убрала телефон в карман. Ей хотелось отдельно запомнить прогулку и отдельно — всё остальное. Когда Дамир пришёл к общему ужину, она поздоровалась с ним как с другим участником группы, и это не выглядело притворством."]}]},{"id":"S04","title":"Þingvellir, день 2. Перед объективом","episode":1,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["На смотровой площадке ветер старался вывернуть двери машины. Эрик вышел первым, обошёл её и придержал дверь Алисы.","— Я справлюсь, — сказала она.","— Верю. Я держу дверь, не тебя.","Он отпустил её сразу, как только Алиса поставила обе ноги на землю.","Дорога шла между тёмных скал. Ник снимал общий план, иногда опуская камеру и просто глядя. Дамир натянул шапку слишком низко, и Алиса вспомнила, как когда-то смеялась над тем, что у него зимой исчезали брови.","— Что? — спросил он.","— Ничего.","— Это было лицо «ничего из прошлого».","— У тебя опять нет бровей.","Дамир поправил шапку.","— Лучше?","— Хуже. Теперь одна.","Ник услышал и повернул камеру, но остановился прежде, чем нажать запись.","— Можно снять? Это первый момент, когда вы похожи не на людей, ожидающих нотариуса.","Алиса посмотрела на Дамира. Он пожал плечами: решай ты."]},{"level":4,"title":"Выбор S04-C1","paragraphs":[]},{"level":5,"title":"A. Разрешить короткий общий кадр (`consent.camera=accepted`)","paragraphs":["— Снимай. Только покажи потом.","Ник снял несколько секунд: ветер заглушил слова Дамира, Алиса засмеялась и отвернулась от объектива. Он остановил запись и протянул ей экран. Она оставила начало и попросила убрать момент, когда прикрывала лицо рукой. Ник обрезал его при ней.","— Так можно?","— Так можно."]},{"level":5,"title":"B. Попросить убрать камеру (`consent.camera=declined_respected`)","paragraphs":["— Давай без записи сейчас.","Ник опустил камеру. Алиса ждала привычного «я же только для себя», но он лишь застегнул чехол.","— Ладно. Мне тоже иногда хочется просто запомнить.","Он пошёл рядом и спросил, как Дамир сумел рассмешить её одним словом. Алиса не ответила; зато перестала следить, не поднялась ли снова камера."]},{"level":5,"title":"C. Предложить снимок всей группы (`consent.camera=negotiated`)","paragraphs":["— Если уж кадр, то все четверо. И не для фильма, пока мы не посмотрим.","Ник поставил камеру на ограждение, включил таймер и окликнул Эрика. Тот успел подбежать в последнюю секунду и неловко нагнулся, чтобы войти в кадр.","На экране они выглядели ещё чужими, но уже стояли теснее, чем накануне в аэропорту. Эрик попросил отправить снимок ему. Ник обещал сначала разослать каждому и никому не показывать без их согласия."]},{"level":5,"title":"Общее продолжение","paragraphs":["Они пошли дальше. Эрик рассказал короткую историю о том, как в детстве пытался перескочить ручей и потерял сапог. Ник стал искать место этого подвига. Дамир спросил Алису, не замёрзли ли у неё руки, и принял ответ «нет» без повторной проверки.","На краю площадки Алиса отстала на несколько шагов. Между двумя каменными стенами лежала мокрая тропа. Эрик уже ждал впереди; ей хотелось догнать его, пока он не решил, что она снова задержалась ради заметки.","Ник боролся с капюшоном на ветру. Дамир держался сбоку, не приближаясь без приглашения.","Алиса убрала блокнот в карман. До возвращения к машине она решила ничего не записывать.","У следующей развилки Эрик предложил короткий путь к воде. Дорога была ровной, но ветер там чувствовался сильнее. Они дошли до берега небольшого озера и обнаружили деревянную площадку, на которой кто-то оставил одну красную детскую варежку.","— У Исландии появился сюжет, — сказал Ник. — Потерянная варежка ищет хозяина.","— Не снимай крупно, — сказала Алиса. — Иначе зритель будет ждать, что хозяина найдут.","— А мы найдём.","— Каким образом?","Ник поднял варежку двумя пальцами.","— Социальные сети, местная полиция, международное сотрудничество.","— Оставь на месте, — сказал Эрик. — Люди возвращаются за потерянными вещами.","— Это слишком спокойное решение.","— Иногда история заканчивается тем, что вещь ждёт там, где её забыли.","Алиса посмотрела на него.","— А люди?","Эрик поймал вопрос и не стал делать вид, что речь всё ещё о варежке.","— Люди обычно уходят дальше.","Дамир стоял у воды. Ветер прижимал куртку к его спине. Алиса знала, что он слышал. Он не обернулся.","Ник положил варежку на столбик у входа и снял общий план без приближения.","— Так честнее?","— Так хотя бы не обещает развязку, — сказала Алиса.","Они пошли вдоль воды. Тропа была достаточно широкой, чтобы идти парами, и достаточно неровной, чтобы пары постоянно менялись.","Сначала рядом оказался Ник.","— Ты всегда проверяешь, что история обещает? — спросил он.","— Работа такая.","— А в жизни?","— В жизни обещания обычно написаны мелким шрифтом.","— Это звучит как опыт.","— Это звучит как человек, который читает договоры.","Ник улыбнулся, но не стал вытягивать признание. Вместо этого показал ей кадр: красная варежка, серое озеро, две размытые фигуры далеко впереди.","— Красиво, — сказала Алиса.","— Это Эрик и Дамир там впереди? — спросила Алиса.","— Да. Я хотел снять варежку, а они случайно вошли в кадр.","— Не узнала их. Далеко ушли.","Ник увеличил изображение, но лица так и остались размытыми. Алиса не попросила удалить кадр: его интересовала оставленная вещь, а не она.","Потом Ник ускорился, чтобы снять Эрика, и рядом оказался Дамир.","— Я не собирался подслушивать, — сказал он.","— Мы говорили на ветру в десяти метрах от тебя.","— Всё равно.","— И?","— Ничего. Просто не хочу, чтобы каждая фраза становилась разговором о нас.","— Хороший план.","Они прошли несколько шагов.","— Хотя варежку я бы забрал, — сказал Дамир. — Оставил бы записку и отнёс в кафе.","— Конечно. Ты не умеешь оставлять проблему на столбике.","— А ты?","Алиса посмотрела на красную точку позади.","— Учусь.","В конце тропы стояла скамейка. Эрик достал из рюкзака маленькую плитку шоколада и разделил на четыре неровных кусочка. Нику достался самый маленький.","— За что? — спросил тот.","— За международное сотрудничество.","Ник поменялся кусочком с Алисой, не спрашивая, но тут же замер:","— Стоп. Ты любишь молочный?","— Уже поменял.","— Могу вернуть.","— Оставь. Я люблю.","— Отлично. Согласие получено задним числом, юристы плачут.","— В следующий раз спроси до дипломатической операции.","— Записал.","Обратно в Рейкьявик ехали другой дорогой. Ник задремал, прижав камеру к груди. Дамир читал письмо клиники. Эрик включил отопление сильнее, не спрашивая, кто замёрз; через минуту сам опустил окно на сантиметр и признался, что перестарался.","— Ты всегда исправляешь всё сразу? — спросила Алиса.","— Если вижу.","— А если не видишь?","— Тогда надеюсь, что мне скажут.","Она подумала о Дамире. Два года назад она не сказала достаточно рано, насколько сильно её пугает его решение. Он не спросил достаточно прямо. Каждый считал молчание другого ответом.","— Сложная система, — сказала Алиса.","— Какая?","— Люди должны говорить.","Эрик бросил на неё быстрый взгляд.","— Ужасно непрактично.","Ник открыл глаза.","— Я проснулся на философии?","— Нет, — сказала Алиса. — Мы обсуждали отопление.","— Ещё хуже.","У гостевого дома они обнаружили, что парковочное место занято маленьким синим автомобилем. Эрик вышел, осмотрел знак и вернулся.","— Пять минут подождём. Потом разгрузимся отсюда.","Ник посмотрел на узкую улицу.","— Я могу снять, как мы героически переносим чемоданы двадцать метров.","— Только если возьмёшь мой, — сказала Алиса.","— Искусство не носит реквизит.","Дамир уже доставал сумки.","— Искусство сегодня носит два чемодана.","— Я возьму, — сказал Ник и подхватил чемодан Алисы за ручку.","Синий автомобиль уехал через минуту. Эрик не позвал всех обратно: они уже дошли до двери. Это почему-то понравилось Алисе — умение не превращать мелкую неудачу в новую операцию.","В гостиной Ник открыл ноутбук и показал первый материал. Не фильм — несколько коротких кадров: дождь на стекле, руки Эрика на карте, чашка Дамира на подоконнике, ботинки на тропе, размокшая табличка.","— Людей почти нет, — сказала Алиса.","— Пока я не знаю, как их снимать.","— Ты снимал сотни людей.","— Не этих.","Он переключил на кадр, где Алиса смеётся в магазине.","— Этот оставил отдельно.","— Я помню.","— Уже жалеешь?","— Пока нет.","Эрик стоял за диваном и смотрел на свои руки в кадре.","— Ты сделал их старше.","— Это свет.","— Удобная профессия. Всё можно объяснить светом.","— В твоей всё можно объяснить погодой.","Дамир присел на подлокотник. На экране появилась его чашка, но не лицо.","— Спасибо, — сказал он.","Ник понял без уточнения.","— Если захочешь быть в кадре, скажешь.","Алиса наблюдала за ними и вдруг почувствовала, что поездка действительно началась. Не в аэропорту, не на дороге и не между скалами. Сейчас, когда они впервые увидели себя глазами другого и не стали спорить, что версия неверна.","Позже она осталась в гостиной одна. На телефоне мигало сообщение Марины: «Как идёт начало? Срок прежний — после четвёртого дня». Алиса написала: «Мы приехали в страну, где погода меняет планы быстрее людей» — и удалила.","Потом: «Четыре человека едут через Исландию, потому что каждому нужно принять решение» — и тоже удалила.","Наконец оставила пустой документ. Первые два дня ещё не заслужили вывода."]},{"level":4,"title":"Если `S03-C1=A`","paragraphs":["У тропы Дамир поднял телефон, будто хотел что-то спросить, но увидел её вчерашнее сообщение и просто улыбнулся. Алиса узнала эту улыбку и не отвернулась."]},{"level":4,"title":"Если `S03-C1=B`","paragraphs":["Когда Дамир догнал группу, Алиса встретила его взгляд без необходимости возвращаться к вчерашнему разговору. Ей понравилось, что он понял её молчание."]}]},{"id":"S05","title":"Дорога в Hveragerði, день 3. Красная полоса","episode":2,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["На третье утро они выехали из рейкьявикского гостевого дома с вещами: следующие две ночи были забронированы в Hveragerði. Красная полоса предупреждения появилась на телефоне Эрика за завтраком. Он прочитал сообщение дважды и положил экран рядом с тарелкой.","— Длинный подъём отменяем. Порывы к полудню усилятся.","Ник, намазывавший джем на хлеб, замер.","— У меня там съёмка.","— Теперь нет.","— Можно подняться раньше.","— Можно. И можно встретить ветер на открытом участке раньше.","— Насколько это опасно?","— Достаточно, чтобы я не повёл группу.","Ник отложил нож. В его лице исчезла привычная игра.","— Я понял. Просто мне нужен был этот кадр.","— Придумаешь другой.","— Ты говоришь так, будто кадры растут вдоль дороги.","— В твоей камере — возможно.","Алиса ожидала, что спор продолжится, но Ник выдохнул и спросил:","— Что вместо?","Эрик развернул карту. Сегодня — короткая долина и геотермальная тропа, потом заселение в Hveragerði. Завтра, если дождь не прекратится, теплица вместо открытой прогулки. На пятый день — южная дорога к Skógafoss.","— Там безопаснее. Красивого обещать не буду.","— Отлично, — сказала Алиса. — Красивое обычно мешает смотреть.","Эрик поднял на неё глаза.","— Это фраза для статьи?","— Нет, я тоже умею воровать у дедов.","Дамир принёс термосы из кухни.","— Если выезжаем раньше, я готов.","— Ты всегда готов, — сказала Алиса.","Он услышал старую колкость, но ответил без защиты:","— Не всегда. Просто теперь стараюсь проверять до того, как говорю.","В машине Ник молчал минут двадцать. Потом попросил остановиться у небольшого поля, где ветер гнал по траве волны. Снимать с дороги было безопасно. Он поставил камеру низко и поймал в кадр не гору, а четыре пары ботинок, проходящих мимо.","— Другой кадр? — спросил Эрик.","— Не привыкай быть правым.","— Поздно."]},{"level":4,"title":"Выбор S05-C1","paragraphs":[]},{"level":5,"title":"A. Помочь Нику (`weatherChoice=nick`)","paragraphs":["— Если пейзаж сегодня не выйдет, сними, как мы переодеваемся под дождём, — сказала Алиса. — Руки, мокрые куртки, дверь машины. Без лиц, если кто-то не захочет.","Ник посмотрел на серую полосу неба, потом на свои промокшие рукава.","— Сниму сначала себя. Если получится смешно, уговорю остальных.","Он достал чехол для камеры; Алиса придержала дверь, пока он убирал аппарат от дождя. Спор о потерянном виде закончился сам собой."]},{"level":5,"title":"B. Попросить Эрика объяснить перемену (`weatherChoice=erik`)","paragraphs":["— Эрик, скажи нам, что именно отменяется. Я уже перепутала два поворота и один водопад.","Он показал на телефоне участок тропы и направление ветра. Открытый подъём они пропускали; короткая защищённая дорожка оставалась возможной, если дождь ослабнет. На вопрос Ника, уверен ли он, Эрик ответил:","— Нет. Решим у начала тропы. Если там так же, возвращаемся.","Алиса перестала строить в голове несостоявшийся день: теперь у него хотя бы были две понятные версии."]},{"level":5,"title":"C. Сесть рядом с Дамиром (`weatherChoice=damir`)","paragraphs":["Алиса пересела на свободное место у окна. Дамир подвинул свой рюкзак к ногам, освобождая ей пространство.","— Ты тоже не хочешь спорить с прогнозом? — спросил он.","— Мне хватило ветра с утра.","Некоторое время они смотрели, как дождь размывает стекло. Дамир не стал предлагать ей кофе, разговор или старую привычную шутку. Когда машина остановилась, он спросил только, достать ли её куртку с заднего сиденья. Алиса взяла её сама; он придержал дверь от ветра."]},{"level":5,"title":"Общее продолжение","paragraphs":["Перед короткой тропой они остановились в маленькой пекарне. Из-за изменённого плана заведение оказалось единственным открытым местом поблизости, и внутри уже собралась половина людей, которых ветер выгнал с маршрутов.","Свободным был один стол на четверых и стул у окна. Ник поставил камеру на стул, а сам остался стоять.","— Камера не ест, — сказал Дамир.","— Зато дороже меня.","Алиса сняла камеру со стула и поставила рядом со своей сумкой.","— Сегодня она сидит на полу.","— Ты быстро устанавливаешь иерархию.","— Она хотя бы не жалуется.","— Ты плохо её знаешь.","Эрик вернулся с номерком заказа и четырьмя стаканами воды.","— Булочки будут через десять минут.","— Какие? — спросил Ник.","— Я выбрал.","— Это нарушение демократических принципов группы.","— Ты позавчера купил свёклу и шоколадное молоко.","— Народ сделал ошибки, но это не повод отменять выборы.","Эрик сел напротив Алисы.","— Там четыре разных. Выберете по очереди.","— А кто последний?","— Я.","— Потому что благородный?","— Потому что знаю, какую никто не возьмёт.","Принесли тарелку: корица, кардамон, шоколад и странная зелёная глазурь.","— Фисташка? — предположила Алиса.","— Морские водоросли, — сказал Эрик.","Ник немедленно взял зелёную.","— Я не позволю тебе победить систему.","— Я не соревновался.","— Это то, что говорят люди, которые выигрывают молча.","Алиса выбрала кардамон. Дамир — корицу. Эрику досталась шоколадная.","— Ты соврал, — сказала Алиса.","— О чём?","— Ты хотел шоколадную.","— Я надеялся.","— И поставил её так, чтобы никто не взял первой.","Эрик отломил кусочек.","— Ты наблюдательная.","— Я журналистка.","— Это профессия, не оправдание.","Она потянулась и отломила от его булочки маленький край.","— Налог за манипуляцию.","Эрик посмотрел на её пальцы, потом на недостающий кусок.","— А если я возражаю?","— Возражаешь?","Он отломил кусочек её кардамонной булочки.","— Теперь нет.","Ник наблюдал за ними поверх зелёной глазури.","— Я хотел сказать что-то остроумное, но морские водоросли лишили меня будущего.","Дамир подвинул к нему воду.","— Не спеши. Возможно, временно.","За соседним столом ребёнок уронил варежку — синюю, не красную. Ник посмотрел на Алису. Она тоже заметила.","— Не начинай, — сказала она.","— Вторую варежку мы точно не повезём с собой, — сказал Ник.","— Эту ребёнок уже поднял, — ответила Алиса.","Дамир услышал их и спросил:","— А ту, красную, так и оставили у озера?","— На столбике у входа, — ответила Алиса. — Надеюсь, хозяин вернулся за ней.","Официантка назвала номер их заказа на хлеб с собой. Эрик поднялся к стойке; остальные допили воду за столом. Ник посмотрел на Алису, будто хотел задать вопрос о Дамире, но вместо этого спросил, хватит ли булочек на всех.","— Если ты не съешь две по дороге, — сказала она.","Когда Эрик принёс пакет, они надели куртки и вышли к машине. Дамир придержал дверь для Алисы; она прошла первой, не пытаясь истолковать этот жест."]}]},{"id":"S06","title":"Короткая тропа. Эрик без инструкции","episode":2,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["Долина встретила их паром, мокрой землёй и запахом серы. Короткая тропа была почти пустой. Эрик шёл впереди, но через несколько минут остановился у развилки.","— Куда? — спросил он Алису.","— Ты гид.","— На обеих тропах безопасно. Одна короче, другая идёт ближе к ручью.","— Ты проверяешь, читала ли я карту?","— Проверяю, хочешь ли ты выбирать.","Алиса указала на длинную.","— Ближе к ручью.","— Тогда веди."]},{"level":5,"title":"Если в S05-C1 Алиса попросила Эрика объяснить перемену","paragraphs":["Прежде чем идти, он снова показал ей экран с прогнозом.","— Ветер стих. Длинная дорожка открыта, но вернуться можем в любой момент.","— Тогда идём, — сказала Алиса. Она увидела, что он помнил утренний вопрос."]},{"level":5,"title":"Если в S05-C1 Алиса выбрала Ника или Дамира","paragraphs":["Эрик кивнул, принимая её выбор, и пропустил её вперёд."]},{"level":5,"title":"Общее продолжение","paragraphs":["Ник и Дамир остались позади: Ник снимал пар над землёй, Дамир завязывал бахилу. Алиса пошла первой. Через сто метров тропа разделилась ещё раз, и она замедлилась."]},{"level":5,"title":"Если в S01-C1 Алиса ехала с Эриком","paragraphs":["Эрик остановился рядом, но не стал сразу показывать направление. Она вспомнила, как в машине просила его подсказывать только по делу, и сама сверилась с указателем."]},{"level":5,"title":"Если в S01-C1 Алиса ехала с Ником или Дамиром","paragraphs":["Эрик подождал, пока она изучит указатель, и только потом подошёл ближе."]},{"level":5,"title":"Общее продолжение","paragraphs":["— Направо, — сказал Эрик.","— Ты не выдержал.","— Там короткий выход к ручью. Дальше тропа не идёт.","— А если я хотела посмотреть, что там?","Эрик задумался и кивнул.","— Если хочешь, идём направо.","Тупик оказался площадкой над ручьём. Не выдающейся: деревянные перила, мокрый камень, клочья пара. Алиса оперлась локтями о перила.","— Стоило?","— Да.","— Почему?","— Ты ошибся.","— Это нравится тебе в мужчинах?","Вопрос прозвучал так неожиданно, что Алиса повернулась. Эрик смотрел на ручей, но уголок его рта дрогнул.","— Иногда, — сказала она. — Особенно если они способны пережить это без презентации.","— У меня была презентация. Я оставил её в машине.","Они засмеялись. Ветер бросил Алисе прядь волос в лицо. Она попыталась убрать её перчаткой и только сильнее размазала по щеке дождевую воду. Эрик протянул руку, остановил её в нескольких сантиметрах и спросил:","— Можно?","Алиса кивнула. Он убрал прядь быстро, почти деловито, но пальцы на мгновение коснулись виска. Тепло осталось дольше прикосновения.","Снизу донёсся голос Ника:","— Если вы там нашли секретный водопад, я увольняюсь!","— Нашли тупик, — крикнула Алиса.","— Ещё лучше! У него честный сюжет.","На обратном пути Эрик рассказал, как однажды привёл группу к закрытому мосту, потому что слишком доверял старой карте. История была короткой и смешной, без вывода о лидерстве.","— И что ты сделал? — спросила Алиса.","— Сказал, что это специальная остановка для обеда.","— То есть соврал.","— Им понравился обед.","— Ужасный человек.","— Я надеялся произвести лучшее впечатление.","— Поздно. Теперь придётся стараться следующие три недели.","Он посмотрел на неё прямо.","— Хорошо.","У начала тропы их догнала пожилая пара. Женщина спросила Эрика по-английски, далеко ли до горячей реки. Эрик объяснил, что сегодня верхняя часть маршрута закрыта из-за ветра, показал короткий безопасный круг и дождался, пока они найдут его на карте.","— Ты мог просто сказать «не ходите», — заметила Алиса, когда пара ушла.","— Мог. Тогда они решили бы, что я перестраховываюсь, и пошли бы проверить.","— А когда даёшь другой вариант, они сами выбирают разумное?","— Иногда.","— Манипуляция.","— Гостеприимство.","— Тонкая граница.","— Поэтому я не пишу статьи.","Ник закончил снимать пар и присоединился к ним.","— Я всё слышал. В фильме ты будешь коварным исландским проводником.","— Тогда найди актёра красивее.","— Сам предложил, — сказал Ник и повернулся к Алисе. — Свидетель есть.","Эрик снял перчатку и вытер каплю с брови.","— Я сказал «красивее», а не «красивого».","Ник замолчал на секунду, затем расхохотался.","— План умеет защищаться.","У начала тропы они достали термосы. Дамир разлил чай и случайно отдал Алисе кружку без сахара — так, как она пила раньше. Она попробовала и поморщилась.","— Теперь с сахаром.","— Серьёзно?","— Уже год.","Он протянул пакетики.","— Один или два?","— Один.","Дамир кивнул. Не сказал, что она всегда ненавидела сладкий чай. Не спросил, кто приучил. Просто обновил знание.","Ник пил прямо из крышки термоса.","— Предлагаю дорожную реформу. Каждый день узнаём одну бесполезную вещь друг о друге.","— Почему бесполезную? — спросил Дамир.","— Полезные превращаются в обязанности. Бесполезные — в симпатию.","— Это подозрительно осмысленно, — сказала Алиса.","— Иногда у меня заканчиваются шутки.","— Моя бесполезная вещь, — сказал Эрик. — Я не умею свистеть.","Ник немедленно потребовал доказательство. Эрик попытался; получился тихий звук, похожий на уставший чайник.","Алиса смеялась, спрятав лицо в рукав. Эрик смотрел на неё без обиды, а потом попробовал снова — хуже.","— Теперь ты, — сказал он.","— Я боюсь рыб, если не вижу дна.","— В Исландии это может стать полезным.","— Не разрушай концепцию.","Ник признался, что не умеет спать без какого-нибудь голоса — подкаста, радио, чужого фильма. Дамир долго думал и сказал, что любит запах бензина.","— Врач, — укоризненно произнёс Ник.","— Я не пью его.","— Пока рано судить поездку.","На дорожке к стоянке Алиса шла рядом с Дамиром.","— Ты правда любишь запах бензина?","— С детства. Отец чинил машину во дворе.","— Ты мне никогда не говорил.","— Наверное, потому что это было бесполезно.","Они посмотрели друг на друга. Разговор мог повернуть к тому, сколько ещё они не знали, прожив вместе три года. Алиса не хотела этого сегодня.","— Значит, теория Ника работает, — сказала она.","— Боюсь, он станет невыносим, если узнает.","Они договорились не говорить."]},{"level":4,"title":"Выбор S06-C2 — Что Алиса предложит Эрику, пока остальные ещё не подошли?","paragraphs":[]},{"level":5,"title":"A. Попросить показать его любимое место на тропе","paragraphs":["— Только не самое знаменитое, — сказала Алиса. Эрик показал ей низкий выступ, с которого открывалась другая сторона долины. Они стояли рядом и считали птиц, пока сзади не послышались голоса группы."]},{"level":5,"title":"B. Предложить ему выбрать музыку для обратной дороги","paragraphs":["— Только без навигатора в голосе певца, — предупредила Алиса. Эрик коротко рассмеялся и назвал песню, которую сестра включала каждое лето. Алиса пообещала послушать её в машине."]}]},{"id":"S07","title":"Общая кухня. Ник и катастрофа с макаронами","episode":2,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["После тропы они доехали до гостевого дома в Hveragerði и занесли вещи. Эрик подтвердил, что обе следующие ночи остаются здесь. Вечером Ник объявил, что готовит пасту. Эрик спросил, умеет ли он. Ник ответил, что однажды получилось."]},{"level":5,"title":"Если в S05-C1 Алиса помогла Нику с новым кадром","paragraphs":["Перед кухней Ник показал ей несколько секунд снятых утром мокрых рукавов. Лиц там не было; на последнем кадре он сам никак не мог застегнуть чехол промёрзшими пальцами.","— Это оставлю, — сказал он. — Если ты не против.","— Ты в кадре. Спроси себя.","Он оставил запись и убрал телефон."]},{"level":5,"title":"Если в S01-C1 Алиса ехала с Ником","paragraphs":["На кухне Ник сначала молча освобождал ей место у плиты. Алиса вспомнила час дороги, когда он впервые перестал играть на публику, и не стала подталкивать его к новой шутке."]},{"level":5,"title":"Общее продолжение","paragraphs":["Через десять минут вода убежала на плиту, соус оказался слишком острым, а дуршлаг — декоративной миской с отверстиями размером с монету.","— Не трогай, — сказал Ник Алисе, когда она потянулась к кастрюле. — У блюда есть замысел.","— У него есть уголовное дело.","— Не мешай искусству совершить ошибку.","Алиса забрала у него деревянную ложку.","— Искусство может совершать ошибку. Ужин — нет.","— Вот поэтому я снимаю, а не женюсь.","Фраза вылетела легко, но после неё Ник на секунду замолчал. Алиса приподняла бровь.","— Это приглашение обсудить твою биографию?","— Это попытка вернуть ложку.","— Неудачная.","Он встал рядом и заглянул в кастрюлю. Плечо коснулось её плеча. Ник не отступил сразу, но и не надавил, оставляя ей возможность решить. Алиса продолжила мешать соус.","— Добавь йогурт, — сказала она.","— В пасту?","— Ты уже положил туда исландский острый соус и мёд. Сейчас поздно защищать Италию.","Они попробовали. Стало съедобно.","— Ты спасла мой дебют, — сказал Ник.","— Я спасла Эрика от необходимости искать новую группу.","— А себя?","— Я могла съесть хлеб.","— Жестоко.","Ник включил музыку на телефоне и начал двигаться между столом и плитой с преувеличенной грацией официанта. Подал Алисе тарелку на согнутой руке.","— Ваш столик с видом на сушилку для курток.","— Я бронировала у окна.","— Окно занято ветром.","Она приняла тарелку. Ник подал следующую Дамиру, который вернулся после звонка, и не стал спрашивать, о чём тот говорил. Эрику досталась самая большая порция.","— Подкуп? — спросил тот.","— Компенсация за утренний спор.","— Ты признал, что я был прав?","— Нет, я признал, что ты можешь испортить мне завтрак, если останешься голодным.","За ужином Ник спросил, что каждый отказался бы снимать или описывать. Эрик сказал, что не повёл бы людей на закрытую тропу ради красивого кадра. Дамир не хотел рассказывать истории пациентов. Алиса вспомнила интервью, которое однажды не включила в материал: собеседник говорил, не понимая, что запись ещё идёт.","— А ты? — спросила она Ника.","Он покрутил вилку.","— Человека, который попросил выключить камеру.","— Сразу?","— Сразу.","— Даже если кадр лучший в жизни?","— Особенно тогда. Иначе он лучший не потому, что я хорошо снял.","На секунду Ник стал совсем серьёзным. Потом попробовал пасту и закашлялся от перца.","— Видишь, — сказала Алиса. — Вселенная не любит красивые заявления.","— Запиши: умер за этику.","— Запишу: не рассчитал соус.","После ужина дождь усилился. Вода барабанила по жестяному подоконнику, и разговор постепенно утонул в этом ровном шуме. Ник убрал тарелки, включил на телефоне таймер и объявил:","— У нас двадцать минут до того, как Эрик отправит всех спать по технике безопасности.","— Я никого не отправляю спать, — сказал Эрик.","— Ещё страшнее. Ты позволяешь нам самим почувствовать последствия.","Дамир вытирал стол.","— Что ты предлагаешь?","— Карточную игру. Без вопросов о детстве, травмах и смысле жизни. Только нормальные вещи.","— У тебя есть нормальные вещи? — спросила Алиса.","Ник достал потрёпанную колоду.","— Красная карта — выбираешь человеку песню на завтра. Чёрная — поручаешь маленькую задачу. Туз — можешь отказаться.","— Отказаться можно только по тузу? — спросил Эрик.","— Отказаться можно всегда. По тузу — драматично.","Первой вытянула Алиса. Красная восьмёрка.","— Выбирай, кому, — сказал Ник.","Она посмотрела на троих. Дамир знал почти всю её старую музыку. Нику подошло бы что-нибудь невыносимо медленное. Эрик весь день управлял дорогой и, вероятно, ожидал тишины.","— Эрику, — решила она. — Завтра включишь песню, под которую невозможно составлять маршрут.","— Таких нет.","— Тогда это проверка.","Эрик вытянул чёрную даму.","— Задача Алисе: десять минут утром не записывать ничего.","— Это наказание профессией.","— Это маленькая задача.","— А если произойдёт что-то гениальное?","— Придётся прожить.","Ник издал одобрительный звук.","— План сегодня опасен.","Дамиру выпала красная карта. Он выбрал Ника.","— Песня без слов.","— Это дискриминация моего вокала.","— Я слышал тебя в душе.","— Во-первых, это была акустическая репетиция. Во-вторых, ты жил через две комнаты.","— Именно.","Ник вытянул чёрного короля и поручил Дамиру утром выбрать худшую булочку в пекарне, не спрашивая состав.","— Это медицински безответственно.","— У тебя нет аллергии?","— Нет.","— Тогда терапевтически спонтанно.","Во втором круге Алисе выпал туз. Она положила его на стол.","— Драматичный отказ, — сказала она.","— Но тебе ещё ничего не предложили, — заметил Ник.","— Я заранее.","— Человек с опытом.","Дамир посмотрел на карту, но не на Алису. Эрик перетасовал оставшуюся колоду.","— Туз можно сохранить, — сказал он. — На случай, когда понадобится.","— Так играют?","— Теперь да.","Алиса убрала карту в карман рубашки. Это был пустяк, но ей понравилась мысль о видимом праве отказаться, которое не нужно объяснять.","Следующая карта отправила Эрика выбирать Нику шапку на завтра. Ник потребовал «что-нибудь, что не убивает харизму». Эрик принёс из прихожей ярко-жёлтую вязаную шапку хозяйки дома, забытую на крючке.","— Это преступление, — сказал Ник.","— Она заметная. Безопасность.","— Я похож на дорожный знак.","— Именно."]},{"level":5,"title":"Если в S04-C1 Алиса разрешила короткую запись","paragraphs":["Ник напомнил, что кадр со смотровой площадки хранится только у него, и спросил, можно ли показать его остальным за столом. Алиса согласилась, предварительно ещё раз посмотрев обрезанную запись."]},{"level":5,"title":"Если в S04-C1 Алиса отказалась от съёмки","paragraphs":["Ник не достал свою камеру. Когда Алиса сама подняла телефон, он удивлённо посмотрел на неё.","— Это другое, — сказала она. — Я хочу именно этот снимок."]},{"level":5,"title":"Если в S04-C1 Алиса предложила групповое фото","paragraphs":["Ник уже разослал всем четырём снимок со смотровой площадки. Алиса нашла его в телефоне и показала Эрику, как неловко он нагнулся, чтобы успеть к таймеру. Эрик попросил не удалять."]},{"level":5,"title":"Общее продолжение","paragraphs":["Алиса сфотографировала Ника на телефон. Он встал в позу, потом показал на камеру:","— Это только в личный архив.","— Согласна.","— И без подписи «режиссёрская версия».","— Ничего не обещаю.","Он шагнул ближе, чтобы посмотреть снимок. Их головы почти соприкоснулись. На экране Ник выглядел нелепо и счастливо.","— Оставь, — сказал он тише.","Эрик наблюдал за ними через стол, не скрывая любопытства, но когда Алиса подняла глаза, занялся картами. Дамир аккуратно сложил полотенце и вышел за ещё одним, хотя стол уже был сухим.","Игра закончилась не по таймеру, а когда хозяйка попросила говорить тише. В коридоре Ник вернул жёлтую шапку на крючок.","— Завтра наденешь? — спросила Алиса.","— Если Эрик сам принесёт её к машине.","Утром шапка лежала на пассажирском сиденье с запиской: «Сигнальное оборудование»."]},{"level":4,"title":"Выбор S07-C1 — что Алиса оставит в общем архиве","paragraphs":[]},{"level":5,"title":"A. Снимок Ника у стола (`kitchenArchive=nick`)","paragraphs":["Алиса отправила снимок только Нику и добавила: «Проверка согласия — ты решаешь, оставлять ли его». Ник ответил, что оставляет, но просит не подписывать его именем. Позже он вернул ей фотографию с жёлтой шапкой — уже с её разрешения."]},{"level":5,"title":"B. Групповой кадр с таймером (`kitchenArchive=group`)","paragraphs":["Алиса предложила поставить телефон на полку и снять всех четверых. Эрик проверил, что в кадре нет чужих вещей, Дамир спросил хозяйку, а Ник поставил таймер. Снимок вышел кривым, зато никто не оказался незаметным фоном."]},{"level":5,"title":"C. Ничего не сохранять (`kitchenArchive=private`)","paragraphs":["Алиса убрала телефон. Ник кивнул без шутки: «Иногда хороший момент не обязан становиться файлом». В блокноте она записала только одну строку — для себя, не для статьи."]},{"level":5,"title":"Общее продолжение","paragraphs":["На следующий день Ник вспомнил её решение и спросил разрешение до того, как поднял камеру. Маленькое правило оказалось полезнее любой подписи: теперь Алиса знала, что может изменить формат близости, не исчезая из разговора."]},{"level":4,"title":"Если `S06-C2=A`","paragraphs":["Когда Эрик подошёл к кухне, он спросил Алису, заметила ли она ещё что-нибудь интересное на той тихой стороне тропы. Ник потребовал объяснить, какой секретный вид они нашли без него."]},{"level":4,"title":"Если `S06-C2=B`","paragraphs":["На кухне Эрик тихо напомнил Алисе название песни. Ник хотел поставить её прямо сейчас, но Алиса предложила сначала закончить ужин."]}]},{"id":"S08","title":"Гостевой дом. Лямка","episode":2,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["Утром четвёртого дня Алиса оставила блокнот в комнате на десять минут, как обещала за картами. За это время Эрик включил в машине песню по её заданию, а Дамир вернулся из пекарни с самой сухой булочкой, какую сумел найти, — оба выполнили карточные задания. Когда Алиса вернулась к блокноту, записала не всё подряд, а только жёлтую шапку Ника и то, как Эрик, выключив музыку, ещё тихо напевал припев."]},{"level":5,"title":"Если в S05-C1 Алиса села рядом с Дамиром","paragraphs":["На лестнице Дамир спросил, отдохнула ли она после вчерашней дороги. Он не упомянул их молчание в машине; Алиса всё равно поняла, о каком часе он спрашивает.","— Да. Спасибо, что тогда просто посидел рядом."]},{"level":5,"title":"Общее продолжение","paragraphs":["Лямка на рюкзаке Алисы оторвалась в коридоре. Бутылка воды покатилась вниз по лестнице и остановилась у ног Дамира.","Он поднял её.","— У меня есть игла для швов.","— Медицинская?","— Для снаряжения. Медицинской я бы не предлагал чинить рюкзак.","— Хорошее начало.","Дамир сел на ступеньку, но не взял рюкзак.","— Хочешь, починю?","Алиса могла бы отказаться просто потому, что два года назад он часто делал полезные вещи до того, как она успевала решить, нужны ли они. Но сейчас он ждал.","— Покажи сначала, что будешь делать.","Он разложил маленький набор: толстая игла, нить, кусок тесьмы.","— Усилю с двух сторон. Красиво не будет.","— Меня пугает, как часто вы с Эриком предупреждаете, что красиво не будет.","— Возможно, это национальная программа.","— Ты не исландец.","— Я быстро адаптируюсь.","Она передала ему рюкзак. Дамир шил медленно, кусая губу, когда проталкивал иглу через плотную ткань. Алиса вспомнила, как он пришивал пуговицу к своей рубашке перед их первым совместным Новым годом. Тогда он тоже был сосредоточен так, будто от результата зависела чья-то жизнь.","— Ты всё ещё делаешь это лицо, — сказала она.","— Какое?","— Будто рюкзак может не пережить операцию.","— Прогноз осторожный.","— Родственникам сообщили?","— Бутылка воды ждёт в коридоре.","Они рассмеялись. Смех пришёл слишком легко, и Алиса почувствовала, как вслед за ним поднимается страх: если им всё ещё легко, значит ли это, что два года ничего не изменили?","Дамир закончил шов и потянул за лямку.","— Проверь сама.","Она надела рюкзак. Лямка держалась.","— Спасибо.","— Пожалуйста.","Он собрал набор.","— В Брюсселе я начал ездить на велосипеде, — сказал он. — Поэтому шрам. И поэтому набор всегда со мной.","— Ты мог рассказать об этом ещё в первый вечер.","— Мог. Но ты не обязана была слушать целую историю из-за одного вопроса.","Это было новое. Старый Дамир объяснил бы всё — маршрут, дождь, скорость, отделение неотложной помощи — и только потом заметил бы, что разговор занял двадцать минут.","— А встреча в Акюрейри? — спросила Алиса.","— Они предлагают годовую программу. Я ещё не ответил.","— Потому что сначала смотришь место?","— И потому что больше не хочу принимать решения только на основании того, что они выглядят разумно на бумаге.","Он не добавил «после нас». Алиса была благодарна и немного разочарована, что он не добавил.","Когда Алиса уже собиралась уходить, в коридор вышел Ник и остановился у двери.","— Вы видели второй?","— На тебе? — спросил Дамир.","Ник посмотрел вниз. На левой ноге был ботинок, на правой — носок.","— Этот я считаю первым.","— Второй у батареи, — сказала Алиса. — Ты поставил сушиться после тропы.","— Почему ты знаешь о моей обуви больше меня?","— Профессиональная деформация.","Ник ушёл, но через секунду вернулся.","— Кстати, через пятнадцать минут хочу снять короткое знакомство каждого с дорогой. Без личных вопросов. Вы оба можете отказаться.","Дамир спросил:","— Что значит знакомство с дорогой?","— Один предмет, который вы всегда берёте, и почему.","— Это личный вопрос, — заметила Алиса.","— Хорошо. Тогда предмет и ложная причина.","— Так интереснее, — сказал Дамир.","Через пятнадцать минут они собрались у машины. Эрик принёс старый металлический термос с вмятиной на боку.","— Причина? — спросил Ник из-за камеры.","— Им удобно забивать колышки.","— Ложная?","— Возможно.","Алиса показала тонкий блокнот.","— Использую как подставку под неровные столы.","Ник навёл камеру на Дамира. Тот держал набор для ремонта.","— Помогает не пользоваться гостиничными наборами для шитья.","— Слишком правдоподобно.","— Тогда: отбиваюсь от журналистов.","Алиса стояла рядом с камерой.","— Покажи технику.","— После съёмки.","Ник поставил камеру на штатив и вошёл в кадр сам. В руках у него ничего не было.","— Я всегда беру запасную футболку.","— Где она? — спросил Эрик.","— В чемодане.","— Это знакомство с машиной, а не с дорогой.","Ник вышел из кадра, нашёл в кармане маленький игрушечный волчок и показал его.","— Тогда это.","— Зачем? — спросила Алиса.","— Проверяю, ровная ли поверхность.","Он раскрутил волчок на капоте. Тот покрутился и упал к Эрику.","— Машина припаркована под уклоном, — сказал Эрик.","— Видите? Незаменимый инструмент.","Ник остановил запись и сразу показал материал. В кадре они выглядели не как герои будущей истории, а как люди, которые ещё не придумали, кем будут рядом друг с другом.","— Оставь мой ответ, — сказала Алиса.","— Даже про столы?","— Особенно про столы.","Дамир попросил убрать последнюю секунду, где он смотрит на неё после шутки. Ник перемотал, уточнил границу и обрезал прямо при них.","— Так нормально?","— Да.","Алиса заметила, что Дамир впервые за поездку сам попросил изменить то, что его касается, вместо того чтобы терпеть ради удобства остальных. Возможно, новую жизнь составляли именно такие мелкие просьбы, которые слишком невыразительны для больших признаний.","Ник с Эриком остались у машины убрать камеру и проверить багаж. Алиса и Дамир вернулись в гостевой дом за куртками и термосом. В прихожей они снова оказались вдвоём."]},{"level":4,"title":"Выбор S08-C1","paragraphs":[]},{"level":5,"title":"A. Предложить кофе (`damir-care=warm`)","paragraphs":["— Я собиралась сделать кофе. Тебе налить?","Дамир посмотрел на неё с осторожной радостью, которую не успел скрыть.","— Если ты всё равно идёшь на кухню. Чёрный.","Они постояли у окна с горячими кружками. Он рассказал, что вчера пытался найти в магазине привычный сорт яблок и купил груши, потому что стеснялся третий раз спросить продавца. Алиса смеялась над ним, не над их прошлым. Допив кофе, она первой сказала, что ей пора надеть куртку перед прогулкой. Дамир кивнул и остался мыть обе кружки."]},{"level":5,"title":"B. Поблагодарить и уйти (`damir-care=neutral`)","paragraphs":["— Спасибо за рюкзак. Я пойду за курткой.","— Конечно.","Дамир отступил, давая ей пройти. На лестнице Алиса оглянулась: он не смотрел ей вслед, а пытался застегнуть свой переполненный рюкзак. Она помогать не стала. До выхода к машине оставалось несколько минут, и обоим хватило сказанного."]},{"level":5,"title":"C. Спросить о Брюсселе (`damir-care=personal`)","paragraphs":["— А в Брюсселе тебе было хорошо? Не на работе. Вообще.","Дамир опустил взгляд на ручку её рюкзака.","— Иногда. У меня там есть друзья. По воскресеньям мы ездили за город на велосипедах, хотя я хуже всех держусь на мокрой дороге.","— Эту часть я помню.","Он улыбнулся, но не стал возвращаться к старой истории.","— Первую зиму было трудно. Потом появился дом, в который хотелось возвращаться. К концу я понял, что могу уехать и не потерять всё, что там было.","Алиса не знала, рада ли этому ответу. Она попросила показать ей однажды фотографию тех воскресений — если ему захочется. Дамир сказал: «Хорошо», и не полез сразу за телефоном."]}]},{"id":"S66","title":"Hveragerði, день 4. Ряды под стеклом","episode":2,"source":"content/season-1-vertical-slice-episodes-01-02.md","chunks":[{"level":0,"title":"","paragraphs":["На четвёртый день они остались в Hveragerði. К полудню дождь стал плотнее, и Эрик заменил прогулку по открытому участку на теплицу-кафе. Внутри было жарко, стёкла запотели, а между рядами томатов висели лампы, от которых лица казались чуть нереальными. Экскурсия заканчивалась практическим занятием: желающие могли пересадить рассаду для завтрашней школьной группы.","— Наконец-то место, где моя куртка не пытается меня убить, — сказал Ник.","Он снял её и обнаружил, что футболка под ней вывернута наизнанку. Алиса заметила это, но промолчала: Ник выглядел уставшим после дороги.","Молодая сотрудница объясняла, как горячая вода из-под земли согревает растения, а шмели опыляют томаты. Ник слушал без камеры — влажный воздух оседал на объективе. Алиса первой сняла пальто и попросила показать, как вынуть рассаду, не повредив корни.","— Ты нервничаешь без неё? — спросила Алиса.","— Немного, — признался Ник. — С ней хотя бы ясно, куда деть руки.","Сотрудница протянула им пустые бирки для рассады. Алиса вложила одну ему в ладонь.","— Теперь есть работа.","Он улыбнулся и взял маркер.","Сотрудница показала им стол с рассадой и бирками. Эрик перенёс поддоны к свободному ряду, Ник подписывал сорта, Дамир придерживал горшки, пока Алиса распределяла землю. Когда Ник перепутал две стопки бирок, они втроём разобрали их по образцу, а Эрик принёс новый пустой поддон. На час они перестали быть людьми, ожидающими следующей туристической остановки: у них было небольшое общее дело.","Когда последний поддон встал на место, сотрудница предложила каждому попробовать по маленькому помидору. Ник первым потянулся, но остановился и попросил разрешения взять ещё один. Эрик, проходя мимо Алисы, вложил ей в ладонь свой — она не успела взять с подноса.","— Ты свой не хочешь?","— Возьму после тебя.","Дамир рассматривал трубы отопления. Раньше после тяжёлых дежурств он мог увлечься устройством любой вещи, которая работала без его помощи. Сейчас он объяснил Алисе, как, по его догадке, вода проходит под рядами, и попросил сотрудницу проверить его версию. Оказалось, он ошибся; Алиса увидела, что его это скорее развеселило, чем смутило.","Ник надписал последнюю бирку и протянул Алисе маркер. На пальцах у него оставалась земля, а камера по-прежнему лежала в сумке. Она удержала его запястье, чтобы прочитать название сорта на кривой надписи. Он не пошутил, только тихо спросил:","— Разберёшь?","— С трудом. Но разберу.","Она отпустила его руку; он ещё секунду стоял рядом, прежде чем вернуться к столу.","В кафе они задержались ненадолго: выпили горячего и вернулись к столу с рассадой, чтобы проверить, все ли бирки стоят правильно. Одного сорта не хватало. Ник уже потянулся придумать название, но Алиса нашла выпавший листок заказа под поддоном.","— Повезло, — сказал он и протянул ей маркер. — Напишешь? У тебя почерк разборчивее.","— Это первая хорошая причина взять журналистку в поездку.","Эрик пересчитал готовые горшки вместе с сотрудницей. Дамир отнёс оставшуюся землю обратно. Ник не снимал: его руки были в земле, и Алисе нравилось видеть его занятым без привычного оправдания камерой.","Когда они вышли из теплицы, дождь почти закончился. Сотрудница открыла боковую дверь на короткую дорожку вдоль ряда горячих труб. Оттуда было видно, как за стеклом горят лампы и двигаются ещё несколько работников. Алиса предложила пройти до конца дорожки, прежде чем возвращаться в машину. Ник пошёл первым, Эрик задержался у двери, чтобы убедиться, что она не захлопнется, Дамир догнал Алису с её забытым шарфом.","— Ты опять оставила его на спинке стула, — сказал он.","— Зато рюкзак на месте.","Дамир улыбнулся. В прошлой жизни он сам бы намотал шарф ей на шею. Сейчас просто отдал его в руки.","У машины Алиса обнаружила на пальце полоску земли. Эрик молча протянул ей влажную салфетку, а потом, встретив её взгляд, сказал:","— Я взял две. Не хочу выглядеть слишком предусмотрительным.","Она засмеялась и оставила вторую ему.","На обратном пути они спорили о дорожной музыке. Ник требовал каждому выбрать песню, за которую ему будет стыдно. Эрик признался в любви к старой поп-группе, но отказался назвать её. Дамир выбрал песню, которую Алиса не знала. Это задело сильнее, чем должно было: у него появилась музыка, при которой её не было.","А потом он включил трек, и она поняла, что он прекрасен.","За окном машины сменялись мокрая дорога, низкие дома и полоса светлеющего неба. Ник постукивал пальцами по колену. Эрик вёл машину и тихо подпевал припеву; когда Алиса повернулась к нему, замолчал. Дамир смотрел в окно.","Алиса не открывала блокнот.","Вечером они вернулись в гостевой дом. Алиса разложила на столе блокнот и написала первые строки для Марины — о том, как люди с разной историей на час занялись одним делом, не распределяя заранее роли.","За стеной Ник искал зарядку и просил всех не двигать его сумку; Дамир нашёл её под стулом. Эрик сверял время завтрашнего выезда с прогнозом. Алиса отложила ручку и вышла на маленькую террасу. Дождь закончился, но перила были мокрыми, а воздух пах землёй и дымом из соседнего дома. За стеклом кухни Ник и Дамир спорили, кому мыть термосы. Эрик стоял в коридоре с телефоном у уха и говорил по-исландски — быстро, совсем не тем размеренным голосом, которым объяснял планы группе.","Он закончил звонок и заметил Алису.","— Холодно.","— Наблюдение или приказ вернуться?","— Наблюдение. Приказ был бы длиннее.","Эрик вышел на террасу, оставив дверь приоткрытой.","— Всё в порядке? — спросила Алиса.","— Хозяйка следующего дома предупреждает о ремонте дороги. Ничего серьёзного.","— Ты всегда говоришь «ничего серьёзного» таким лицом?","— Каким?","— Будто уже придумал четыре запасных маршрута и недоволен пятым.","Эрик опёрся ладонями о перила.","— Три.","— Маршрута?","— И пятый мне действительно не нравится.","Алиса рассмеялась.","— Ты сегодня выполнил задание с песней.","— Ты не записывала десять минут?","— Одиннадцать. Пропустила, как Ник уронил ложку.","— Трагическая потеря для литературы.","— Пришлось запомнить.","— И как?","Она посмотрела через стекло. Ник доказывал что-то, размахивая полотенцем. Дамир смеялся и держал оба термоса, не отдавая ему.","— Странно, — сказала Алиса. — Когда не записываешь, кажется, что момент исчезнет. А он становится подробнее.","— Возможно, потому что не думаешь, как объяснить его другим.","Фраза могла стать началом философского разговора, и Алиса почти приготовилась защищаться. Но Эрик вдруг добавил:","— Или потому что Ник с полотенцем трудно забывается.","— Спасибо. Ты спас нас обоих.","— От чего?","— От важного вывода.","Он повернулся к ней. Между ними оставалось меньше шага. Алиса чувствовала тепло из открытой двери и холод от перил за спиной.","— Ты не любишь выводы? — спросил Эрик.","— Люблю. Поэтому стараюсь не делать их на четвёртый день.","— Разумно.","— Не говори это так разочарованно.","— Я рассчитывал узнать, кем стану в статье.","— Пока ты человек, который крадёт шоколадные булочки и притворяется, что это стратегия.","— Неплохое начало.","— Завтра хочешь сесть впереди? — спросил Эрик. — Первый час дороги.","— Посмотрю утром, — ответила Алиса. Ей нравилось, что он спросил, а не оставил место молча.","Из кухни вышел Ник.","— Я не мешаю? — спросил он с выражением человека, который очень надеялся мешать.","— Да, — одновременно ответили Алиса и Эрик.","Ник приложил руку к сердцу.","— Наконец-то группа научилась говорить прямо.","Он протянул Алисе кружку.","— Чай. Дамир сказал, что ты теперь с сахаром. Я ему не поверил и положил пакетик отдельно.","Алиса взяла кружку. Дамир остался на кухне, не выглядывая проверить, какой выбор она сделает.","— Спасибо.","— Завтра я отвечаю за музыку первые сорок минут, — сказал Ник. — План согласовал.","Эрик кивнул.","— При условии, что жёлтая шапка тоже едет.","— Это шантаж.","— Договорились, — сказал Эрик.","Ник вынул из кармана жёлтую шапку. Алиса заметила, что Эрик уже не смотрит в телефон. Она пока не дала ответа на его приглашение, но и не отвела глаза.","Алиса отпила чай. Сахар лежал рядом, не добавленный заранее. Она разорвала пакетик и высыпала половину."]},{"level":5,"title":"Если в S08-C1 Алиса предложила Дамиру кофе","paragraphs":["На кухне она заметила, что Дамир поставил две чистые кружки рядом — те самые, из которых они утром пили кофе. Он поймал её взгляд; они улыбнулись друг другу без продолжения разговора."]},{"level":5,"title":"Если в S08-C1 Алиса сохранила дистанцию","paragraphs":["Она оставила остаток сахара рядом с кружкой и не пошла на кухню, где остался Дамир. Он не вышел проверить, что она решила. Алисе было спокойно от этой простой возможности не продолжать утренний разговор."]},{"level":5,"title":"Если в S08-C1 Алиса спросила о Брюсселе","paragraphs":["Дамир вышел на минуту из кухни и показал ей одну фотографию: три велосипеда и трое его друзей у мокрого кирпичного дома. Алиса вспомнила, что попросила об этом утром, и задержала взгляд на людях, которых прежде не знала. Он не стал рассказывать за каждого; она спросила только, кто из них научил его ездить под дождём."]},{"level":5,"title":"Общее продолжение","paragraphs":["В комнате Алиса положила сохранённого туза между страницами блокнота. Рядом с заметками о теплице дописала три наблюдения, не пытаясь превратить их в выводы о людях.","Телефон завибрировал. Марина прислала единственный вопрос: «Есть первый абзац?»"]},{"level":5,"title":"Если в S02-C1 Алиса выбрала людей","paragraphs":["Алиса перечитала абзац: «В теплице мы пересаживали рассаду для группы, которую не увидим. Ник перепутал бирки; Эрик молча принёс новый поддон, а Дамир придержал горшок, пока я искала нужное название. Я запомнила не лица, а то, кто продолжил работать, когда стало ясно, что никто нас не снимает»."]},{"level":5,"title":"Если в S02-C1 Алиса выбрала место","paragraphs":["Алиса перечитала абзац: «В Hveragerði дождь загнал нас под стекло теплицы. Тёплая вода шла под рядами томатов; над ними горели лампы, хотя снаружи ещё был день. Мы пришли переждать непогоду, а остались помогать с рассадой для завтрашней экскурсии»."]},{"level":5,"title":"Если в S02-C1 Алиса выбрала личное решение","paragraphs":["Алиса перечитала абзац: «Мы могли переждать дождь за столом, но остались пересаживать рассаду для детей, которые придут завтра. Ник оставил камеру в сумке, я отложила блокнот. На час ни у кого не было причины выглядеть интереснее, чем он есть»."]},{"level":5,"title":"Общее продолжение","paragraphs":["Она отправила абзац Марине. Та ответила почти сразу: «Оставим. Что будет завтра у водопада?» Алиса пока не знала, но впервые хотела узнать не только ради статьи.","В коридоре тихо закрылась дверь. По шагам Алиса не смогла определить, кто прошёл мимо: Эрик двигался почти бесшумно, Дамир всегда наступал сначала на пятку, Ник мог внезапно решить красться ради шутки. Через секунду под дверью появился сложенный листок.","На нём Ник нарисовал жёлтую шапку, Эрик — вероятно Эрик — дописал рядом время выезда. Ниже Дамир оставил короткое: «Шарф не забудь».","Алиса прикрепила листок к странице блокнота.","В коридоре послышались голоса. Ник предложил завтра у водопада искать не лучший кадр, а самое неожиданное место, откуда его видно. Эрик ответил, что покажет им тропу, если погода позволит. Дамир спросил, можно ли сначала просто дойти и осмотреться. Алиса открыла дверь.","— Я иду с вами, — сказала она. — А место выберем вместе.","Алиса не закрыла дверь: разговор о завтрашнем месте продолжился уже при ней."]}]},{"id":"S09","title":"Skógafoss, день 5, утро. Не открытка","episode":3,"source":"content/season-1-literary-episode-03.md","chunks":[{"level":0,"title":"","paragraphs":["Ник вынес из гостевого дома три сумки и жёлтую шапку, которую уже перестал считать шуткой. Эрик проверил давление в шинах; Дамир вернулся за забытым термосом. Алиса задержалась у двери, перечитывая сообщение Марины: «Если найдёшь у водопада не очередную открытку, пришли две строки».","— Я обещала найти неожиданное место, — сказала она, садясь в машину. — Но не обещала, что оно будет красивым.","— Обещала искать вместе, — напомнил Ник.","Эрик взглянул в зеркало заднего вида.","— Сначала дойдём. Если дождь усилится, останемся внизу.","— Вот поэтому с нами взрослый, — сказал Ник.","— Мне тридцать четыре, — ответил Эрик.","— Ты не обязан подтверждать мою теорию числами.","У Skógafoss стояли автобусы. Люди выходили, фотографировались у ограждения и возвращались к тёплым сиденьям, поправляя мокрые капюшоны. Ник потянулся к камере, потом посмотрел на Алису — не в поисках разрешения снять её, а будто проверяя, будут ли они исполнять вчерашнюю договорённость.","— Если найдём только вид спереди, — сказал он, — я официально провалил задание.","— Тогда придётся написать о провале, — ответила Алиса.","Они прошли вдоль разрешённой дорожки, не спускаясь к мокрым камням у воды. С привычного места водопад выглядел таким большим, что Алиса не находила в нём ничего своего. Эрик показал на тропу к смотровой площадке, но не повёл группу сразу наверх: над ступенями ветер разворачивал дождь обратно. Они укрылись за невысокой постройкой у стоянки. Оттуда водопада почти не было видно. Зато слышалось, как он заглушает разговор, если отойти от двери всего на несколько шагов.","Дамир снял крышку с термоса.","— Неужели наше особое место — возле туалета? — спросил он.","— Пока лучшее из доступных, — сказал Эрик.","Ник попытался записать звук и обнаружил, что ветер бьёт в микрофон. Он спрятал камеру под куртку и впервые просто слушал. По дорожке мимо них торопилась женщина с ребёнком. У ребёнка развязался шнурок; женщина присела на корточки, удерживая капюшон подбородком. Они не посмотрели на водопад, пока она завязывала узел. Потом мальчик поднял голову и засмеялся: брызги долетели даже сюда.","— Подождём пять минут? — предложила Алиса. — Может, ветер отойдёт.","Ник бросил взгляд на часы, но не возразил. За пять минут автобус уехал, площадка опустела. Эрик первым проверил ступени, спустился и вернулся.","— Наверх сейчас можно. Только не бегом. А можно остаться здесь.","Алиса выбрала идти. На середине подъёма она остановилась отдышаться и увидела внизу не водопад, а их машину, маленькую и нелепо домашнюю рядом с автобусами. Дамир уже поднялся выше; он не крикнул ей поторопиться. Ник отстал, помогая чужой паре сделать снимок. Эрик ждал на следующей площадке, опираясь на перила, и смотрел не на часы, а на дорогу, которую они прошли.","Наверху вода падала с таким шумом, что говорить приходилось близко. Алиса заметила узкую полосу сухой земли за перилами, где посетители оставляли на минуту перчатки, чтобы вытереть объектив. Там лежала чужая детская варежка. Ник поднял её двумя пальцами.","— Наша вторая потерянная, — сказал он. — Это уже система.","— Положи на видное место, — попросила Алиса. — Вдруг вернутся.","Они закрепили варежку на поручне, так чтобы её не сдуло. Через минуту мальчик в синей куртке прибежал за ней. Его мать поблагодарила их, почти перекрикивая воду. Мальчик помахал каждому отдельно, а Дамиру — почему-то дважды.","Алиса сделала одну запись в блокноте. Ни радуги, ни превосходной степени. «Мы пришли искать новый вид на водопад и сначала нашли место, где его не видно». Когда она подняла глаза, все трое смотрели в разные стороны: Ник за мальчиком, Эрик на облака, Дамир вниз, на крошечную машину."]},{"level":3,"title":"Выбор S09-C1","paragraphs":[]},{"level":4,"title":"A. Попросить Эрика показать место, которое он сам запомнил","paragraphs":["Алиса подошла к нему.","— Ты здесь бывал. Покажи место, на которое не водишь группы.","— Это нечестное задание для гида.","— Я сейчас спрашиваю тебя, не гида.","Он помедлил, затем показал на тёмный участок дороги далеко внизу.","— Там я однажды ждал сестру после её первого самостоятельного похода. Она опоздала на час. Я смотрел на водопад, пока совсем не перестал его видеть.","— Что ты ей сказал, когда она приехала?","— Что у неё развязаны шнурки. Потом мы поехали домой.","Алиса не записала имя сестры. Эрик увидел это и слегка кивнул. На обратном пути он подал ей сухую салфетку для блокнота, хотя дождь уже кончался."]},{"level":4,"title":"B. Попросить Ника назвать то, что камера пропустила","paragraphs":["— Дай мне один кадр, которого у тебя нет, — сказала Алиса.","Ник повернул камеру экраном к ладони.","— Мальчик два раза помахал Дамиру. Я в этот момент менял батарею.","— Почему ему?","— Не знаю. Может, Дамир единственный помахал в ответ нормально, а не в объектив.","Дамир услышал своё имя, но вода отняла у него остальную часть фразы. Ник повысил голос:","— Я говорю, тебе оказывают предпочтение случайные исландские дети!","Дамир посмотрел на Алису: «Это он серьёзно?» Она засмеялась и покачала головой. Ник опустил камеру, не пытаясь восстановить упущенную секунду."]},{"level":4,"title":"C. Попросить Дамира вспомнить момент подъёма","paragraphs":["— Что ты увидел отсюда? — спросила Алиса Дамира.","— Машину. Нашу, кажется. С такого расстояния не проверишь.","— Очень смелое предположение.","Он протянул ей крышку от термоса. Чай ещё был тёплым.","— Я подумал, что сегодня впервые не считаю, сколько нам осталось до следующего места. Обычно в поездках я это делаю. Даже когда у меня выходной.","Алиса отпила и вернула крышку.","— А что делаешь вместо этого?","— Смотрю, не улетит ли Ник вместе со своей шапкой.","Ник стоял спиной к ветру, придерживая её обеими руками. Алиса записала наблюдение без имени Дамира; он не просил о таком, но заметил и ничего не сказал."]},{"level":4,"title":"Общее продолжение S09","paragraphs":["На стоянке они нашли мальчика в синей куртке ещё раз. Теперь он показывал варежку отцу как вещь, пережившую приключение. Ник не стал его снимать. В машине Алиса открыла черновик сообщения Марине."]},{"level":5,"title":"Если `careerThesis=people`","paragraphs":["Она написала: «У Skógafoss мы договорились поискать необычный вид, но сначала стояли у стены, за которой водопада почти не было видно. Потом мальчик потерял варежку, Ник выключил камеру, Эрик дождался, пока все поднимутся, а Дамир первым помахал ребёнку. Я хочу писать о людях, которые задержались в одном месте и всё же увезли из него разные дни»."]},{"level":5,"title":"Если `careerThesis=place`","paragraphs":["Она написала: «Чтобы увидеть Skógafoss, мы сначала постояли там, откуда его почти не видно. Потом ветер ослаб, и мы поднялись по мокрой лестнице. Сверху остались не только вода и чёрный склон: внизу уместились стоянка, дорога и наша машина. Это место меняет масштаб раньше, чем даёт красивый кадр»."]},{"level":5,"title":"Если `careerThesis=own-choice`","paragraphs":["Она написала: «Мы могли сделать обычный снимок и ехать дальше. Вместо этого переждали ветер, поднялись вместе и нашли чужую потерянную варежку. Наш необычный взгляд на Skógafoss начался с решения задержаться; ни один кадр не заставил бы нас это сделать»."]},{"level":5,"title":"Общее продолжение","paragraphs":["Марина ответила: «Вот это оставь. Но не делай вид, что вы все увидели одно и то же». Алиса убрала телефон. За окном водопад исчез раньше, чем она ожидала; дорога повела их к Vík."]}]},{"id":"S10","title":"Дорога к Vík, день 5, после полудня. Песня на полчаса","episode":3,"source":"content/season-1-literary-episode-03.md","chunks":[{"level":0,"title":"","paragraphs":["На заправке Ник купил два вида жевательного мармелада и попросил Дамира определить, какой из них съедобный. Пока они спорили у кассы, Алиса догнала Эрика у машины. Он вытирал с бокового стекла солёные разводы.","— Ты выбираешь музыку или Ник всё ещё шантажирует нас шапкой?","— У него кончились сорок минут вчера. Сегодня моя очередь.","— Значит, я вовремя.","Эрик открыл пассажирскую дверь спереди. Алиса села, чтобы помочь ему с навигацией после остановки, а он включил запись — старую, с лёгким шипением в начале. Женщина пела по-исландски негромко, почти разговаривая. Алиса не понимала ни слова, но не попросила перевести сразу.","— Это твоё? — спросила она, когда машина выехала с заправки.","— Пластинка моей сестры. Я перенёс её в телефон.","— У вас одна на двоих?","— У неё настоящая. У меня незаконная копия.","Эрик сказал это таким ровным голосом, что Алиса не сразу заметила шутку. За ними Ник шуршал упаковкой; Дамир предложил ему воду, чтобы прекратить экспертную оценку кислых мармеладок.","— Она знает о преступлении? — спросила Алиса.","— Каждый год грозит забрать у меня кабель.","Они проехали несколько километров молча. Эрик не объяснял каждую гору, возникавшую из дождя. Однажды песня закончилась, и следующий трек оказался быстрым, с совершенно несоразмерным первому весельем. Эрик поспешно снизил громкость.","— Не убирай, — попросила Алиса.","— Это была ошибка при записи.","— Я не про музыку. У тебя лицо меняется.","— Нет.","— Сейчас споришь со мной, не отрывая взгляда от дороги. Значит, меняется.","Он всё-таки прибавил звук. Алиса заметила, что пальцы на руле дважды отбили ритм, прежде чем он опомнился.","На следующей остановке он рассказал, как в шестнадцать лет на семейном празднике вызвался поставить музыку и перепутал две похожие кассеты. Вместо торжественного танца для родителей включилась эта нелепая быстрая песня. Отец не стал выключать её и вытащил мать танцевать между столами; сестра до сих пор утверждала, что это был лучший вечер.","— А ты? — спросила Алиса.","— Я стоял возле проигрывателя и ждал, когда меня выставят из дома.","— Тебя выставили?","— На улицу за дополнительным хлебом. Полезный исход.","Он улыбнулся, глядя на дорогу. Алиса представила шестнадцатилетнего Эрика у проигрывателя — без карты, радиостанции и ответственности за чужой день.","Когда они остановились у небольшого магазина перед Vík, Ник увёл Дамира искать батарейки для камеры. Алиса заметила на прилавке одноразовые дождевики и дешёвые открытки. На открытке с водопадом кто-то уже написал карандашом «пробная печать»; её оставили в коробке среди безупречных видов. Она показала Эрику.","— Для твоей сестры, — предложила Алиса. — Расскажешь, что кассета всё ещё ездит по стране.","— Она скажет, что я украл её дважды.","— Тогда подпиши от её имени и отправь себе.","Эрик взял карточку и попытался стереть надпись, но карандаш оставил серую тень. Он положил открытку обратно.","— Не сегодня. У меня есть другая, которую давно надо дописать.","Алиса не стала спрашивать, кому. Вместо этого взяла два маленьких пакетика с орехами. Один протянула ему.","— Я покупаю тебе закуску к твоей песне. Если она снова включится, ответственность теперь общая.","Он проверил состав и выбрал пакет без соли.","— Не думал, что ты умеешь принимать такие серьёзные обязательства.","— Только на ближайший час.","В машине Алиса впервые поставила собственную песню между его записями — не для соревнования, а чтобы узнать, будет ли ему интересно слушать что-то её. Эрик не спросил, почему именно эта. На светофоре он попросил название и сохранил его в телефоне, когда машина остановилась на стоянке. Ник, проснувшись, заявил, что пропустил заседание музыкального совета. Алиса показала ему пакет орехов; он взял горсть и не стал требовать пересмотра решения."]},{"level":5,"title":"Если в S01-C1 Алиса провела первый час дороги с Эриком","paragraphs":["— В Кефлавике ты сказал, что не умеешь выбирать музыку для незнакомых людей, — напомнила она.","— Я тогда не знал, выдержишь ли ты вторую песню.","— А теперь?","— Всё ещё проверяю."]},{"level":5,"title":"Если в S01-C1 Алиса сидела с Ником или Дамиром","paragraphs":["— Так вот что ты включаешь, когда не обсуждаешь погоду, — сказала Алиса.","— Я иногда обсуждаю погоду под музыку. Могу совместить, если тебе не хватает.","— Нет. Пока не надо."]},{"level":3,"title":"Выбор S10-C1","paragraphs":[]},{"level":4,"title":"A. Подхватить игру","paragraphs":["Алиса протянула руку к панели, не касаясь кнопки.","— Можно ещё раз ту неправильную песню?","— Сейчас Ник проснётся.","— Он всё равно проснётся, когда мармелад победит.","Эрик включил её сначала. На припеве Алиса отбила ритм ладонью по колену. Он не стал смотреть на неё, пока вёл, но позже, на стоянке у гостевого дома, тихо насвистел последние две ноты. Она ответила тем же."]},{"level":4,"title":"B. Оставить момент тихим","paragraphs":["— Давай первую песню, — попросила Алиса. — Я не дослушала её.","Эрик пролистал список. Она подперла щёку ладонью и смотрела в окно. После нескольких минут он сказал название песни и имя певицы, не предлагая перевода. Этого оказалось достаточно. Когда они приехали в Vík, Алиса не сразу вышла из машины; Эрик дождался конца последней строки."]},{"level":4,"title":"Общее продолжение S10","paragraphs":["В Vík они поселились в небольшом гостевом доме на ночь. Ник получил верхнюю койку в мужской комнате и объявил, что будет вести переговоры о переселении. Дамир ответил: «Завтра, если переживёшь». Алиса осталась в комнате через коридор. На доске у входа висело предупреждение для посетителей Reynisfjara о непредсказуемых волнах. Эрик попросил всех взглянуть на него перед завтрашним выездом. Ник посмотрел первым и убрал телефон."]}]},{"id":"S11","title":"Reynisfjara, день 6, позднее утро. Кадр, которого не будет","episode":3,"source":"content/season-1-literary-episode-03.md","chunks":[{"level":0,"title":"","paragraphs":["У входа на Reynisfjara Эрик остановил группу у информационного щита. Он не устраивал лекцию: показал им отмеченную безопасную часть пляжа и сказал, что к воде никто не подходит ради фотографии, даже когда море кажется спокойным. Алиса огляделась. Чёрный песок был почти сухим дальше от прибоя, а у кромки волны вели себя так, будто не имели общего расписания.","Ник проверил свет. Его интересовал не прибой, а следы на песке: их собственные и те, что уже уходили к скалам. Дамир придержал шарф Алисы, когда ветер сдёрнул его с плеча. Она взяла шарф обратно и заметила, что он не стал завязывать его за неё, как делал когда-то."]},{"level":5,"title":"Если в S04-C1 Алиса разрешила запись","paragraphs":["Ник поднял камеру не сразу.","— В Þingvellir ты согласилась на короткий общий план. Это другое место. Здесь тебя можно снять со спины, издалека, если захочешь.","— Я ещё не решила, — ответила Алиса.","— Тогда сначала посмотрим без камеры."]},{"level":5,"title":"Если в S04-C1 Алиса отказалась от записи","paragraphs":["Ник застегнул кофр.","— Ты тогда сказала «без съёмки». Я помню. Сегодня тоже могу оставить тебя вне кадра.","— Спасибо. Я посмотрю, что именно ты снимаешь.","— Договорились. Пока — только песок."]},{"level":5,"title":"Если в S04-C1 Алиса предложила групповое фото","paragraphs":["— Снова общая фотография? — спросил Ник, показывая ей экран с пустым кадром.","— Возможно. Но не у воды.","— Согласен. И сначала проверим, кто вообще хочет попадать в кадр."]},{"level":5,"title":"Общее продолжение","paragraphs":["Сначала они просто шли вдоль внутренней части пляжа. Песок приставал к ботинкам и делал шаги неожиданно тяжёлыми. Алиса хотела найти место, где видны одновременно берег и деревня, но дома скрылись за склоном. Ник выбрал участок сухого песка подальше от воды и предложил попробовать кадр с их следами. Он поставил камеру на устойчивую поверхность и уточнил, что в кадре будут только ботинки, не лица и не голоса. Алиса согласилась только на это. Остальные тоже согласились; лишь тогда Ник нажал запись.","Получилось плохо: Дамир остановился поправить шнурок, Эрик оглянулся на людей у знака, Алиса свернула раньше остальных, потому что увидела выброшенную морем ветку. Ник показал им запись. На ней четверо не шли вместе ни секунды.","— Можно оставить, — сказала Алиса. — По крайней мере, никто не притворяется, будто мы умеем маршировать.","— Для фильма об этом путешествии — слишком честное начало, — ответил Ник, но не стёр кадр.","Он попросил вторую попытку. Дамир предложил идти медленнее, чтобы попасть в одну линию. Эрик согласился, если они останутся на сухом участке. На этот раз Алиса сама не захотела повторять движение ради камеры. Она отошла к дорожке и посмотрела, как остальные трое расходятся на разное расстояние, едва перестав следить за Ником. Её больше заинтересовали моменты между дублями: Ник переставлял камеру, Дамир пытался вытряхнуть песок из ботинка, Эрик что-то сказал пожилой паре у щита и показал им безопасный путь назад.","За поворотом люди столпились вокруг скал. Ник увидел отражение облака в тонкой полосе воды и присел, чтобы поймать его без людей. До линии, которую Эрик указал как допустимую, оставалось несколько метров. Эрик подошёл и коснулся его плеча.","— Не здесь. Вода подойдёт дальше, чем кажется.","— Я не у прибоя, — ответил Ник, не отрываясь от экрана.","— Сейчас — нет.","Ник поднял голову. В его голосе впервые за поездку не было улыбки.","— Я вижу, где стою.","Эрик не стал спорить о зрении. Он показал след на песке выше их ботинок — свежий, оставленный волной минутой раньше. Ник выключил запись, но остался на корточках, недовольный тем, что ему пришлось сделать это при всех.","Алиса подошла. Ей нравился придуманный им кадр; ей не нравилось, что она сама заметила след только сейчас. Дамир стоял дальше, не вмешиваясь, но держал её шарф, который ветер сорвал с плеча."]},{"level":3,"title":"Выбор S11-C1","paragraphs":[]},{"level":4,"title":"A. Предложить безопасную точку для того же замысла","paragraphs":["— Ник, покажи, что тебе нужно внизу кадра, — сказала Алиса.","Он развернул экран. На нём облако лежало в чёрном песке почти как второй остров.","— Отражение. Оно будет только отсюда.","— Тогда не будет именно этого отражения, — ответила Алиса. — Можно снять, как оно исчезает, когда мы отходим. Это тоже часть того, что здесь происходит.","Ник посмотрел на след волны, потом встал. Они отошли к более высокой полосе песка, которую указал Эрик. Ник снял несколько секунд — не Алису, не туристов, а отпечатки их ботинок, которые ветер уже начинал сглаживать. Он дал ей посмотреть материал.","— Мои ботинки не публикуй без договора, — сказала она.","Он коротко рассмеялся, больше от облегчения, чем от шутки.","— Сделаю список согласий для обуви.","— Для меня серьёзно: лицо и голос — только после отдельного вопроса.","— Да. Сегодня в них нет необходимости.","Эрик пошёл дальше первым, не празднуя победу. Ник сам убрал камеру перед следующим поворотом."]},{"level":4,"title":"B. Попросить всех уйти от воды, не обсуждая кадр сейчас","paragraphs":["— Мы отойдём, — сказала Алиса. — Кадр подождёт.","Ник убрал камеру резче, чем нужно, но пошёл вместе с ними. На дорожке он задержался у урны и выкинул разорванную обёртку, принесённую ветром. Когда Эрик отошёл к машине, Ник сказал Алисе:","— Я разозлился не на тебя. Я почти закончил съёмку и не хотел потерять её.","— Я знаю. Но ты действительно не видел след.","— Теперь вижу.","Он открыл отснятые секунды и сам удалил последние, где камера ещё стояла слишком низко. Алиса не просила доказательства и не хвалила его за очевидное. Они несколько минут прошли молча."]},{"level":4,"title":"C. Предложить сначала разобраться с правилами, затем решить вопрос о съёмке","paragraphs":["— Я тоже не заметила, куда дошла вода, — сказала Алиса. — Давайте вернёмся к щиту. Ник, покажешь нам потом идею? Я хочу понять её, но не отсюда.","Он медленно выпрямился.","— Хорошо.","На дорожке Эрик ещё раз показал им отметку на схеме. Ник слушал без камеры в руках. Дамир вернул Алисе шарф; она завязала его плотнее. Когда они отошли достаточно далеко, Ник показал на экране короткий фрагмент отражения. В нём не было человека, но движение воды приблизилось к объективу быстрее, чем казалось вживую.","— Не хочу это оставлять, — сказал Ник и удалил файл. — Я попробую снять с дорожки, если вы подождёте.","— Я в кадр не войду, — сказала Алиса.","— Понял. Тогда сниму только место.","С дорожки вышел другой кадр: не идеальная зеркальная полоска, а люди, которые остановились у щита и спорили, идти ли дальше. Ник опустил камеру прежде, чем можно было различить лица."]},{"level":4,"title":"Общее продолжение S11","paragraphs":["Они не уехали сразу. От дорожки, куда вернулась группа, открывался совсем другой вид: полосы песка, невысокая трава и ряд людей, которые останавливались у предупреждающего щита. Ник попросил пять минут — не для кадра у воды, а чтобы записать звук шагов на сухой дорожке. Эрик посмотрел на время, кивнул и пошёл позвонить в гостевой дом. Дамир остался с ним. Алиса и Ник прошли короткий участок туда и обратно, пока он держал микрофон ниже лица. В наушниках шаги оказались громче моря. Ник дал ей один наушник; второй оставил себе. Несколько секунд они слышали шаги одинаково, хотя вживую он шёл впереди неё.","— В фильме будет слышно, что мы не дошли до кромки? — спросила Алиса.","— Будет слышно, что мы идём обратно, — сказал Ник. — Остальное не возьмусь обещать.","У стоянки они заметили пожилую женщину, державшую карту обеими руками. Она искала остановку автобуса, хотя указатель был на другой стороне дороги. Ник убрал микрофон и показал ей дорожку. Алиса проверила надпись на знаке; Дамир подхватил её разговор, когда выяснилось, что женщина едет в Vík. Несколько минут они шли вместе до остановки. Женщина оказалась не растерянной туристкой: она приехала к племяннице и уже три раза ходила по этой дороге. Просто сегодня автобус перенесли на другую сторону из-за работ у парковки. Алисе пришлось вычеркнуть из головы готовую историю о помощи беспомощному человеку. Женщина рассказала, что племянница печёт хлеб для одного из местных кафе. Алиса спросила, как её зовут, но женщина засмеялась: «Если зайдёте, сами познакомитесь». Алиса не стала записывать имя, которого ей не дали.","Женщина спросила, почему Ник не снимает такой красивый пляж. Он ответил просто:","— Сегодня мне хватило.","Эрик услышал это, но не обернулся с победным видом. Уже у машины он предложил Нику переднее сиденье: оттуда было удобно вместе смотреть на безопасные остановки дальше по дороге. Ник согласился, всё ещё немного сердясь, но спросил Эрика, где с дороги виден холм за Vík. Алиса не пыталась мирить их за них. Она написала в блокноте: «На пляже мы не сделали кадр, ради которого вышли из машины. Зато проводили женщину до автобуса». Ей ещё предстояло решить, попадёт ли это в статью и не превратит ли живую женщину в удобное доказательство её собственной мысли."]}]},{"id":"S12","title":"Vík, день 6, после обеда. Два разных города","episode":3,"source":"content/season-1-literary-episode-03.md","chunks":[{"level":0,"title":"","paragraphs":["В кафе Vík Алиса заказала горячий суп и не стала доставать блокнот, пока не доела. Дамир стоял у окна с двумя бумажными стаканами. Он не подходил, пока она сама не подняла руку.","— Садись, если не торопишься.","— Эрик дал нам сорок минут. Ник остался выгружать материал.","— И ты решил провести их здесь?","— Я хотел кофе. Второй взял на случай, если ты тоже захочешь. Неудачный расчёт — у тебя суп.","Он поставил второй стакан на середину стола, не придвигая к ней. Алиса заметила, что он больше не угадывает её заказ по памяти."]},{"level":5,"title":"Если `damir-care=warm` — в S08 Алиса предложила ему кофе","paragraphs":["— Сегодня моя очередь решить, пить ли твой кофе, — сказала она.","— Честно. Я уже выпил тот, что ты принесла утром.","— И не упомянул, что он был ужасный?","— Он был горячий. Это спасло.","Она взяла второй стакан, проверила температуру и оставила рядом с тарелкой."]},{"level":5,"title":"Если `damir-care=neutral` — в S08 Алиса сохранила дистанцию","paragraphs":["— Я не просила второй, — сказала Алиса.","— Да. Я могу взять его с собой.","Он уже протянул руку, но она остановила его.","— Оставь. Если захочу, выпью. Только не считай это продолжением того разговора.","— Не буду.","Он сел не напротив неё, а сбоку от окна, сохранив между ними стол."]},{"level":5,"title":"Если `damir-care=personal` — в S08 Алиса спросила о Брюсселе","paragraphs":["— У тебя там каждый день был такой дождь? — спросила она, кивая на окно.","— В Брюсселе он хотя бы притворяется, что скоро закончится. Здесь честнее.","— На фотографии у вас были велосипеды. Ты так и ездишь на работу?","— Ездил, пока не сломал крыло. Потом начал ходить пешком. Могу показать улицу, которую проходил, но это не особенно красивое место.","— Покажешь после супа. Не как экскурсию.","Дамир кивнул и не полез сразу за телефоном."]},{"level":5,"title":"Общее продолжение","paragraphs":["За соседним столом девушка объясняла пожилой паре, что автобус задержится из-за погоды. Алиса поймала себя на желании узнать, куда они едут. Дамир тем временем снимал с рукава песчинки, застрявшие после пляжа. На правой руке у него был новый след от ремня часов; она не знала, когда он начал носить часы так туго.","— Ты вчера сказал, что редко никуда не спешишь, — заметила она."]},{"level":5,"title":"Если `skogafossVoice=damir`","paragraphs":["— Я спросила у водопада, что ты делаешь вместо подсчёта остановок. Ты ответил про шапку Ника. Это был обходной путь.","— Был, — признал он. — Я ещё не знал нормального ответа."]},{"level":5,"title":"Если `skogafossVoice=eric` или `skogafossVoice=nick`","paragraphs":["— На лестнице у водопада ты впервые не ждал нас у машины, — сказала Алиса. — Я заметила.","— Сам удивился. Обычно я иду впереди, даже когда не знаю, куда нам всем надо."]},{"level":5,"title":"Общее продолжение","paragraphs":["— Что изменилось? — спросила она.","— В Брюсселе я съехал из квартиры поближе к больнице. Снял комнату дальше, у знакомого. Стал ужинать не за компьютером. Звучит как достижение человека, который не умел выключать свет в кабинете.","— Ты и дома оставлял его гореть.","— Помню. Ты говорила, что наши счета оплачивают мои дежурства.","Алиса улыбнулась: это было точное воспоминание, не попытка сделать прошлое лучше. За окном девушка помогла пожилой паре сложить карту. Дамир подождал, пока Алиса вернёт взгляд к столу.","— У меня там есть друзья, — сказал он. — Я научился проводить выходные без плана больницы. Но иногда всё равно соглашаюсь на лишнюю смену, если кто-то просит. Я не стал совсем другим человеком.","— Я и не искала другого.","Они оба услышали в её фразе больше, чем она собиралась сказать. Дамир не поспешил исправить неловкость."]},{"level":3,"title":"Выбор S12-C1","paragraphs":[]},{"level":4,"title":"A. Спросить о людях, которые теперь рядом с ним","paragraphs":["— Кто этот знакомый, у которого ты жил? — спросила Алиса.","— Матье. Мы познакомились в приёмном отделении, когда он привёз туда своего отца. Потом пересеклись в веломастерской. У него дочь, она заставила меня выучить названия птиц на французском.","— Получилось?","— Первые три. Четвёртая каждый раз оказывается другой.","Дамир показал фотографию: на столе раскрытая детская книжка, а рядом три велосипедных шлема. Людей в кадре не было. Алиса смотрела на книжку и впервые представляла его жизнь в отсутствие себя без острого желания сравнить, какой она могла бы быть рядом с ним.","— Хочу познакомиться с ними, если когда-нибудь окажусь там, — сказала она и тут же добавила: — Это не план поездки.","— Я понял."]},{"level":4,"title":"B. Попросить оставить разговор на сегодня","paragraphs":["— Дамир, давай остановимся, — сказала Алиса. — Я хотела услышать, как ты живёшь, и услышала. Сейчас мне нужно посидеть без продолжения.","Он посмотрел на её недопитый суп, затем на неё.","— Хорошо. Я пойду за счётом.","— Не надо оплачивать мой.","— Я собирался оплатить только свой.","Это прозвучало чуть резче, чем он хотел. Вернувшись, он положил чек возле собственного стакана и сказал:","— Прости. Я защищался от того, чего ты не сказала.","— Я тоже. Давай просто выйдем.","Они вместе дошли до двери. Снаружи ветер сорвал с Алисы капюшон; Дамир не стал поправлять его, только придержал дверь, пока она застегнула куртку."]},{"level":4,"title":"Общее продолжение S12","paragraphs":["На улице Алиса открыла телефон. Марина прислала пометку к вчерашнему абзацу: «Хорошо, что не превращаешь каждого в символ. Продолжай». Дамир не заглядывал в экран. Он остановился у окна маленького магазина, где между дождевиками и открытками стояла коробка с карандашами.","— Ты утром жаловалась, что последний сломался, — сказал он. — Хочешь зайти?","— Я не жаловалась. Он сломался у тебя в руках, когда ты просил записать время.","— Именно поэтому я запомнил.","Внутри Алиса выбрала два простых карандаша; Дамир купил себе маленький блокнот без разлиновки. Раньше он носил с собой только телефон и листы с расписанием. Она спросила, что он собирается туда писать.","— Не знаю. Вчера нарисовал нашу машину сверху. Получилось похоже на утюг.","— Покажешь?","Он открыл первую страницу. Нарисованная машина и правда имела тяжёлый острый нос; рядом стояли четыре человечка разного роста. Ник оказался выше Эрика, Эрик — шире машины, а Алиса держала предмет, похожий на лопату.","— Это блокнот, — объяснил Дамир.","— Я надеялась, что щит.","Она взяла карандаш и добавила к своей фигуре второй ботинок. Дамир не стал исправлять рисунок, хотя новый ботинок нарушил всю его перспективу. У двери магазина ветер прижал к стеклу рекламный листок. Они постояли рядом, пока продавец помогал другому покупателю вынести коробку, и вышли без спешки. Алисе нравилось, что у Дамира нашёлся плохой рисунок, который он не обязан превращать в полезный навык.","На ходу она снова открыла сообщение Марины. Ей захотелось показать Дамиру строку про пляж — и она поняла, что это не просьба о редакторском совете. Ей было интересно, как он прочтёт её наблюдение."]},{"level":3,"title":"Выбор S12-C2","paragraphs":[]},{"level":4,"title":"A. Показать две строки","paragraphs":["— Можно мнение не врача и не бывшего? — спросила Алиса.","— Не обещаю перестать быть вторым по команде.","Она дала ему телефон с двумя строками о неснятом кадре. Дамир прочёл и вернул экран сразу, не листая дальше.","— Там сказано «мы», — заметил он. — Ты тоже решила не снимать.","— Я не снимаю.","— Ты могла сделать из этого историю о Нике и Эрике. Ты оставила себя внутри.","Алиса посмотрела на строку снова. Он не сказал, хорошо она написана или плохо, но указал именно на место, где она боялась спрятаться.","— Спасибо, — сказала она."]},{"level":4,"title":"B. Оставить черновик у себя","paragraphs":["Алиса погасила экран.","— Нет, пока не покажу. Я ещё не решила, что там моё, а что чужое.","— Тогда не показывай.","Она ожидала вопроса «почему», но Дамир вместо этого указал на автобусную остановку: там собрались их вчерашние соседи по гостевому дому, спорившие с расписанием. Алиса достала блокнот и записала номер маршрута. Это было обычное журналистское действие, не оправдание перед ним."]},{"level":4,"title":"Общее продолжение S12","paragraphs":["Ник написал в общий чат, что выгрузил материал. Эрик ответил временем завтрашнего выезда на восток. Алиса и Дамир вернулись в гостевой дом разными дорожками вокруг стоянки: он задержался у машины, она зашла купить карандаш. В коридоре они встретились у общей раковины, уступили друг другу место и оба слегка улыбнулись. Ни у кого не было готовой роли для другого, и это позволило просто пройти в общую комнату.","Там Ник пытался уложить карты в коробку, которую кто-то из прежних гостей явно собирал мокрыми руками. Половина колоды вздулась по краям. Он предложил игру: вытянуть карту, назвать одну вещь, которую завтра каждый сделает для поездки, или вместо ответа сложить три полотенца, оставленные хозяйкой на диване. Первым вытянул он сам, посмотрел на карту и взял полотенца.","— Несправедливо. Ты знаешь, что нам тоже интересно, — сказала Алиса.","— Я так и рассчитывал. Помогите с углами.","Дамир придержал стопку, пока Ник складывал первое полотенце. Со вторым пришлось начинать заново: Ник сделал из него длинную полосу. Эрик показал, как хозяйка складывала их утром — сначала пополам, затем втрое. Ник исправил, не называя инструкцию посягательством на творческую свободу.","Эрик вытянул карту и сказал, что утром проверит открытые участки дороги до выезда. Дамир обещал достать еду из общего холодильника, чтобы никто не вспомнил о ней уже в машине. Алиса хотела сказать «напишу статью», но это было слишком широко для завтрашнего утра.","— Я покажу вам, что собираюсь написать о пляже, — сказала она. — Не всю статью. Каждый увидит свои слова до того, как их получит Марина.","Ник перестал сворачивать полотенце.","— Моих слов там пока мало, — сказал он.","— Тогда увидишь то, что есть. И сможешь сказать, где я ошиблась.","— Я тоже? — спросил Эрик.","— Особенно ты. Я не знаю, как описать минуту, когда ты остановил съёмку, не сделав из вас обоих карикатуры.","Дамир оставил своё полотенце на стопке.","— Я тебе там нужен?","— Пока нет. Может, позже спрошу отдельно.","Он кивнул. Она не обещала сделать из их разговора материал только ради того, чтобы он не почувствовал себя исключённым.","Ник поставил сложенную стопку на полку у двери. Хозяйка, проходившая мимо с ключами, поблагодарила их и удивилась, что полотенца теперь умещаются. Ник посмотрел на Эрика с выражением человека, которого только что похвалили за чужую технологию. Эрик пожал плечами: за вечер это стало почти дружеским жестом.","Когда все разошлись, Алиса осталась дописать в блокноте обещанное действие — «показать узнаваемые строки, спросить отдельно про личное». Затем поставила будильник. Завтра начиналась длинная дорога к Skaftafell; теперь у неё была конкретная причина открыть блокнот перед остальными, а не только самой себе."]},{"level":4,"title":"Выбор S12-C3 — Что Алиса сделает на обратном пути после разговора с Дамиром?","paragraphs":[]},{"level":5,"title":"A. Позвать его зайти за горячим шоколадом","paragraphs":["— На десять минут, — сказала она. Они зашли в кофейню, и Дамир впервые за день спросил не о прошлом, а о её любимом месте в Исландии. Алиса ответила, что пока не выбрала. Он предложил не спешить."]},{"level":5,"title":"B. Вернуться к группе одной","paragraphs":["— Увидимся дома, — сказала Алиса, имея в виду гостевой дом, и сама удивилась слову. Дамир кивнул и пошёл за продуктами. Пока она возвращалась, ей было приятно ни с кем не объяснять своё настроение."]}]},{"id":"S13","title":"День 7. Скафтафетль. Четыре человека и один блокнот","episode":4,"source":"content/season-1-literary-episode-04.md","chunks":[{"level":0,"title":"","paragraphs":["Утром в Вике Дамир постучал в дверь Алисы только затем, чтобы сказать: чайник в общей кухне наконец работает. Вчера они говорили о его нынешней жизни ровно столько, сколько Алиса захотела услышать. За завтраком он обсуждал с Ником дорожные бутерброды. Алиса могла смотреть на него, не продолжая вчерашнего разговора.","Перед выездом Ник положил камеру в чехол и спросил Эрика, нужна ли она сегодня на тропе.","— Для ходьбы — нет, — ответил Эрик. — Для твоей работы решишь сам после того, как поймёшь, куда можно идти.","Ник вздохнул.","— Это самый вежливый способ напомнить мне о пляже.","— Ты сам напомнил, — сказал Эрик.","Алиса вспомнила вчерашний спор на Рейнисфьяре. Они ушли с берега вместе, а весь оставшийся материал ещё не разобрали. В машине чехол стоял между пакетом с хлебом и её блокнотом.","К парковке у Скафтафетля они приехали до полудня. У входа в информационный центр люди складывали мокрые капюшоны, разглядывали схему троп и сравнивали собственные ботинки с чужими. Эрик сверил на стенде открытые участки и прогноз на ближайшие часы. Он выбрал обозначенную прогулочную тропу с возвращением тем же путём, показал группе место разворота и время, к которому они должны быть у машины.","— Я не поведу вас на ледник, — сказал он, увидев, куда Ник смотрит на карте. — Для этого нужны отдельный маршрут и снаряжение. Сегодня мы идём рядом, смотрим издалека.","— Я смотрел на значок туалета, — возразил Ник.","— Он в другой стороне.","— Тогда хорошо, что мы обсудили карту.","После вчерашнего кафе Алисе хотелось работать с чем-то, у чего есть ясные края. Она достала блокнот. В нём рядом с заметками о пляже сохранилась фраза Дамира, которую она ещё не решила, имеет ли право использовать. Она перевернула страницу.","— Мне нужна сегодняшняя заметка без четырёх одинаковых впечатлений о красивом льде, — сказала она. — Давайте сделаем каждый что-то своё. Я соберу текст. Эрик, ты покажешь, как выбираешь предел прогулки. Ник, если согласен, запишешь звуки и общий план без лиц, пока не спросишь каждого отдельно. Дамир, поможешь мне заметить то, что я пропускаю, когда пишу на ходу. Можно отказаться или предложить другое.","Дамир потянулся к рюкзаку, но остановился: Алиса ещё не передала ему блокнот.","— Мне подходит, — сказал Дамир. — Но я не буду читать твой блокнот через плечо.","— Даже если там твоя биография?","— Особенно тогда.","Ник поднял ладони.","— Звук без лиц. А если мне захочется лица?","— Спросишь, — ответила Алиса. — Пока камера ещё закрыта.","— Справедливо.","Эрик посмотрел на часы, затем на неё.","— У тебя есть время на эту работу до поворота. Когда скажу возвращаться, возвращаемся все.","— Договорились. Я не буду превращать карту в художественную рекомендацию.","У скамьи семья пыталась затянуть на ребёнке дождевик. Малыш смотрел на Алису так строго, будто она и была причиной погоды. Она подняла упавшую варежку; когда он забрал её, ручка осталась под обложкой.","Дамир заметил это, но ничего не сказал. От молчания стало легче.","На подъёме Алиса вытащила страницу со старой заметкой о Скоугафоссе. Там оставалось место для одного голоса, который она сама тогда попросила. От ветра лист прилип к мокрой манжете; она разгладила его на обложке и понесла открытым, пока они шли."]},{"level":5,"title":"Если `skogafossVoice=eric`","paragraphs":["Эрик увидел нарисованную у полей узкую полосу дороги.","— Ты запомнила именно её?","— Ты мне её показал. Про ожидание сестры я ничего не написала.","Он провёл пальцем над рисунком, не касаясь страницы.","— Дорога здесь похожа на шов. Когда-нибудь покажу тебе, как она выглядит без водопада.","Алиса оставила рисунок и закрыла блокнот прежде, чем он успел увидеть незаполненную строку рядом."]},{"level":5,"title":"Если `skogafossVoice=nick`","paragraphs":["На странице была её короткая помета: «Два взмаха рукой, которых нет в записи». Ник узнал собственные слова и перестал проверять, держится ли крышка объектива.","— Ребёнок правда махал дважды, — сказал он. — Я думал, ты запомнишь только мою шутку про Дамира.","— Шутка у тебя была громче. Но это я просила показать пропущенное.","Он посмотрел на ребёнка у скамьи и на секунду поднял руку в ответ на его серьёзный взгляд. Камера осталась на ремне."]},{"level":5,"title":"Если `skogafossVoice=damir`","paragraphs":["На странице Алиса сохранила вид машины с лестницы и две маленькие фигуры на ветру. Дамир разглядел пометку о шапке Ника.","— Выглядит так, будто мы в тот день ездили спасать её, — сказал он.","— Ты сам выбрал смотреть на неё вместо часов.","Он поправил сбившийся край карты у неё в руках. В кафе они уже говорили о том вопросе; здесь он не стал повторять ответ и просто пошёл рядом до следующего указателя."]},{"level":5,"title":"Общее продолжение","paragraphs":["На первых сотнях метров тропа потребовала от группы простого согласования: кто идёт впереди, кто ждёт у развилки, кто несёт запасную воду. Ник хотел остановиться и записать хруст гравия. Эрик показал расширение тропы, где тот никому не мешал. Дамир перенёс бутылки из Алисиных боковых карманов в общий рюкзак, предварительно спросив. Алиса поймала себя на том, что следит за всеми сразу и уже мысленно собирает готовую сцену: заботливый гид, легкомысленный оператор, безупречный врач.","Живые люди тут же испортили её удобную схему. Эрик забыл, куда сунул собственные перчатки; Ник без шуток нашёл их под ремнём рюкзака. Дамир признался, что забыл зарядить телефон. Алиса забрала у него бумажную карту с улыбкой человека, которому наконец понадобилось не исправлять чью-то жизнь, а просто держать лист от ветра.","На расширении Ник положил микрофон на перила и попросил Алису пройти несколько шагов по гравию. В наушнике она услышала прежде всего собственное дыхание. Ник пожал плечами: «Так тоже бывает». Они поменялись местами. Теперь в записи хрустели его ботинки, а рядом звенела пряжка чужого рюкзака. Алиса захотела переснять проход, убрать случайный звук. Ник придержал провод и сказал, что сперва дослушает. Ей было удобнее думать о нём как о человеке, который всё время тянется к лишнему дублю. Он тем временем остановил запись и посмотрел, не идёт ли кто-то сзади. Приближалась пара с палками; они уступили дорогу, не прося людей идти «потише» ради материала.","У карты был надорван угол. Дамир придержал его двумя пальцами, пока Алиса разворачивала лист. На Скоугафоссе они делили тёплую крышку термоса; сейчас между их руками был только мокрый сгиб бумаги. Она спросила, что он хотел сохранить от сегодняшней дороги, если не получится записать ни слова. Дамир посмотрел на склон и сказал: «Как Ник искал перчатки Эрика, хотя ещё вчера они едва не поссорились из-за камеры». Алиса приподняла бровь: «Ты всё-таки умеешь говорить о других». Он ответил: «Иногда это проще». Она не записала фразу сразу. Дамир отпустил карту, когда ветер стих, и не проверил, попала ли она в блокнот.","На широкой площадке ей пришло сообщение от Марины: «Как движется материал? Хочу понять, что у нас вместо открыток».","Алиса набрала «Люди учатся ехать вместе», стёрла. Набрала «Погода заставляет уступать», тоже стёрла. Третья версия была честнее: «Сегодня попробую написать о том, кто решает, что останется за кадром». Отправлять пока не стала. Дальше по тропе виднелась низкая серая линия льда. Прежде чем дать кому-то роль в тексте, она должна была услышать, хочет ли он её."]},{"level":4,"title":"Выбор S13-C1 — как Алиса распорядится работой","paragraphs":["Выбирается один фрагмент. Речь о роли Алисы в заметке, не о доступе к мужчинам."]},{"level":5,"title":"A. Вести заметку самой и отвечать за согласие каждого","paragraphs":["— Беру на себя и запись, и право вычеркнуть, — сказала Алиса, догнав остальных. — Если кто-то передумает насчёт цитаты или звука, скажите прямо мне. Я не хочу прятаться за тем, что у нас есть готовый материал.","Ник повернул к ней камеру закрытой крышкой объектива.","— Вот моё официальное «понял». Если я забудусь, напомни ещё раз.","— Напомню.","Эрик остановился, чтобы все сошлись у указателя.","— Тебе самой кто напомнит остановиться? — спросил он.","Алиса посмотрела на тонкую красную черту своего времени в заметках.","— Ты. О времени и тропе. О тексте я решу сама.","— Согласен.","Дамир отдал ей карту, когда ветер ослаб.","— Тогда скажи, если захочешь, чтобы кто-то просто подержал страницу.","Она попросила его об этом через пять минут. Страница перестала хлопать, и неожиданно выяснилось, что делегировать маленькую работу не значит отдать ему весь текст."]},{"level":5,"title":"B. Отказаться от роли распорядителя и договориться о равном сборе материала","paragraphs":["Алиса остановилась, когда все подошли к указателю.","— Я слишком быстро выдала каждому задание, — сказала она. — Вы не моя редакция. Предлагаю другой способ: каждый выберет одну вещь, которую хочет сохранить от этого дня, а вечером спросит у остальных, можно ли её включать. Мне не нужно руководить вашими впечатлениями.","— Моё впечатление уже выбрано, — сказал Ник. — Эрик ищет перчатки в собственной куртке.","— Его ты в фильм без разрешения не получишь, — заметил Дамир.","Эрик снял перчатку и поднял её, словно на голосовании.","— История об этом допустима. Моё расписание маршрута — тоже, если не выдавать его за приказ природы.","— Записала, — сказала Алиса. — А ты, Дамир?","— Пока не знаю. Может, ничего.","Ей захотелось вытянуть из него ответ, заполнить пустую клетку. Она закрыла блокнот.","— «Ничего» тоже можно принести к вечеру.","Он кивнул с заметным облегчением. На этот раз она не была ведущей, но договорённость возникла по её инициативе."]},{"level":5,"title":"Общее продолжение","paragraphs":["Перед узким участком Эрик собрал всех рядом и попросил пройти по одному, не останавливаясь ради фото там, где пришлось бы перекрыть путь другим. Алиса повторила условие Нику, когда он проверил ремень камеры; Ник ответил «слышу» и убрал её за спину.","Дамир принёс Алисе не готовое наблюдение, а вопрос:","— Ты всё время записываешь, кто заботится о ком. А кто сегодня заботится о твоём материале?","Она хотела пошутить, но он ждал ответа как на обычный вопрос, без подтекста вчерашнего разговора.","— Пока я. И это неплохое начало.","У развилки Эрик объявил короткую остановку. Времени хватало на воду, на снимок из разрешённой точки и на несколько минут, в которые никто не должен был быть персонажем. Он сам отошёл проверить указатель обратного пути. Алиса пошла за ним — не потому, что получила роль, а потому, что хотела узнать, как звучит его голос, когда ему не приходится обращаться ко всей группе."]},{"level":4,"title":"Если `S12-C3=A`","paragraphs":["Дамир поставил перед Алисой кружку и негромко спросил, не хочет ли она снова тот горячий шоколад из Vík. Она рассмеялась: теперь у них было хотя бы одно новое воспоминание, не связанное с прошлым."]},{"level":4,"title":"Если `S12-C3=B`","paragraphs":["Когда Дамир вернулся с пакетами, Алиса сама помогла ему разложить продукты. Ник пошутил, что они слишком быстро организовали склад, и они оба одновременно ответили ему «нет»."]}]},{"id":"S14","title":"День 7. Тропа над ледниковой равниной. Темп","episode":4,"source":"content/season-1-literary-episode-04.md","chunks":[{"level":0,"title":"","paragraphs":["Эрик стоял у деревянного столбика и пытался вставить руку в мокрую перчатку. Та упрямо выворачивалась наизнанку. Он заметил Алису и не стал прятать борьбу.","— Ты обещал следить за временем, — сказала она.","— Время подождёт. Перчатка — нет.","— Кажется, это первый исландец, который проигрывает предмету одежды.","— Я не говорил, что у нас национальный иммунитет к перчаткам.","Она придержала край рукава; он расправил подкладку. Когда перчатка наконец села, они оба не сразу убрали руки.","За площадкой тропа поднималась плавно, потом уходила по каменистому краю к обзорной точке. Эрик показал ей на карте короткий вариант возврата. У скамьи он договорился с Ником и Дамиром: они ждут на этой площадке до обозначенного времени; если Алиса и Эрик вернутся раньше, идут к машине вместе. Ник повторил время вслух и поставил напоминание в телефоне. Дамир поднял большой палец, не отрываясь от бутылки воды. Только после этого двое пошли дальше."]},{"level":5,"title":"Если `ericTone=playful`","paragraphs":["Эрик насвистел две последние ноты той самой песни из машины. Алиса тут же отбила ритм пальцами по ремню рюкзака.","— Я надеялась, ты забыл припев.","— Я и забыл. Эти две ноты застряли отдельно.","Он попробовал насвистеть третью и сбился. Алиса рассмеялась первой."]},{"level":5,"title":"Если `ericTone=quiet`","paragraphs":["На несколько шагов они замолчали. Эрик заметил, что Алиса сбавила ход, но не сверился сразу с часами.","— В прошлый раз я дослушал песню, пока ты не вышла из машины, — сказал он. — Сейчас тоже можем остановиться, когда ты захочешь.","Она посмотрела на свет между низкими облаками.","— Пока пойдём. Я скажу."]},{"level":5,"title":"Общее продолжение","paragraphs":["— Тебе подойдёт этот отрезок? — спросил Эрик. — Если ноги устали, разворачиваемся отсюда. Никакого штрафа за недосмотренный вид.","— А если мне хочется пройти дальше?","— Тогда идём дальше. В пределах отмеченной тропы и до времени разворота.","Она усмехнулась.","— Ты даже свободу выдаёшь с инструкцией.","— Работаю над этим. Можно просто сказать: выбирай темп?","— Можно.","Они пошли. Ветер тянул за молнию её куртки, на склоне темнели низкие кусты, за ними белела дальняя кромка льда. Эрик не перечислял факты о каждом камне. Иногда он предупреждал, где скользко, и снова молчал. С ним тишина не требовала от Алисы заполнить её вопросом. Но на третьем подъёме она поняла, что ускорилась, чтобы не выглядеть той, кого нужно ждать. Разговор в голове стал неприятно знакомым: «Я не мешаю? Я не испорчу план?».","На плоском камне лежала чья-то забытая вязаная шапка. Эрик поднял её и повесил на столбик у тропы так, чтобы её было видно на обратном пути. Алиса спросила, не заведёт ли он для потерянных вещей отдельное расписание. «Могу», — сказал он и перечислил воображаемые графы: время находки, направление ветра, степень отчаяния владельца. На последнем слове его голос стал ниже и ближе; Алиса посмотрела на него, а не на шапку. Он тоже заметил это и перестал шутить. Из-за поворота вышла семья; они отошли к краю широкой площадки и пропустили её. Когда шаги стихли, Эрик не продолжил список. Между ними осталось место для чего-то нового, ещё без названия.","Эрик остановился у расширения и достал термос.","— Я обычно здесь пью чай, — сказал он. — Даже один.","— Неужели ты способен один задержать собственный маршрут?","— Именно поэтому хожу один.","Он налил чай в крышку и протянул ей. Не стал говорить, что она запыхалась. Алиса приняла крышку; ладони согрелись раньше лица.","— Почему ты так следишь за временем? — спросила она. — Кроме очевидного ответа про безопасность.","Эрик смотрел туда, где тропа изгибалась за валуном.","— Когда ведёшь людей, легко привыкнуть быть полезным. Потом они не спрашивают, устал ли ты. Я сам их этому научил. Всё время показывал, что успею за всех.","— А теперь?","— Теперь пытаюсь построить школу маршрутов. Там другие гиды должны суметь сказать: сегодня меня заменят. Звучит просто. Я составил три версии расписания и ни в одной ещё не позволил себе выходной.","Алиса рассмеялась. Он тоже, смущённо, и вернул термос в рюкзак.","— Я раньше думала, что ты просто любишь командовать.","— Я иногда люблю. Это тоже часть проблемы.","— Сегодня ты спросил.","— Сегодня у меня есть с кем потренироваться.","Последняя фраза осталась между ними. Алиса представила его без карты и расписания и вдруг захотела оказаться там, когда у него получится выйти из роли гида.","Она достала телефон, чтобы сфотографировать вид для заметки. Эрик не отошёл и не подошёл ближе. В кадре был лёд, низкое небо и край его рукава. Она убрала телефон, не снимая. После Вика ей стало яснее, как быстро «случайно попал» превращается в «почему ты не спросила»."]},{"level":4,"title":"Выбор S14-C1 — как пройти оставшийся участок","paragraphs":["Оба варианта возвращают Алису и Эрика к группе к согласованному времени."]},{"level":5,"title":"A. Попросить идти медленнее и назвать причину","paragraphs":["— Я хочу пройти до обзорной точки, — сказала Алиса, — но сейчас иду быстрее, чем мне удобно. Не из-за ноги. Не хочу быть человеком, из-за которого все ждут.","Эрик взглянул на часы и затем повернул их циферблатом к ней.","— У нас есть время на медленный шаг и обратную дорогу. Я не гадал, как тебе удобнее. Спасибо, что сказала.","Она первой пошла по тропе. Он держался рядом, не подталкивая словом или рукой. У обзорной точки оказалось меньше эффектного льда, чем она ожидала, зато был хороший просвет между облаками, и они успели увидеть, как свет переходит через долину.","— Для заметки? — спросил Эрик.","— Может быть. Сначала для меня.","Он кивнул и не попросил объяснить разницу."]},{"level":5,"title":"B. Предложить короткий возврат и взять на себя решение","paragraphs":["— Давай разворачиваться здесь, — сказала Алиса. — Я успела увидеть то, ради чего шла. Не хочу идти дальше только потому, что мы можем.","Эрик не скрывал удивления.","— Обычно мне приходится уговаривать людей, что конец тропы не обязан быть целью.","— Сегодня это моя скучная профессиональная победа.","— У журналистов тоже есть профессиональные победы без публикации?","— У меня только что появилась одна.","На обратном пути они шли не торопясь и встали у ручья, где вода уходила под тёмные камни. Эрик спросил, хочет ли она записать звук. Алиса отказалась. Они слушали его вместе, пока не подошла другая пара, и уступили место. Позже, встретив остальных, Эрик сказал ровно то, что было правдой: «Мы выбрали короткий путь». Он не назвал её уставшей и не сделал собственную осторожность её решением."]},{"level":5,"title":"Общее продолжение","paragraphs":["У машины Ник показал не снятый кадр, а свой лист со звуковыми пометками: «шаги», «ремень рюкзака», «щелчок фляжки». Последний звук он записал у скамьи, пока ждал с Дамиром; Алиса узнала щелчок крышки его бутылки. Ник не спрашивал, чем они занимались у подъёма.","— Ты тоже записываешь мелочи? — спросила она.","— Большое и без нас заметят.","Эрик спросил каждого, хватает ли воды до следующей остановки. Когда очередь дошла до Алисы, он выдержал небольшую паузу, оставив ответ ей.","— Хватает, — сказала она.","Ночевать группа собиралась ближе к ледниковой лагуне. Дорога вывела их из зелёных склонов на широкую равнину. Дамир сменил Ника на переднем сиденье, потому что тот хотел разобрать звук в наушниках, а Эрик попросил второго человека следить за указателями. Ник положил камеру в чехол. Алиса открыла блокнот и записала не чужую цитату, а собственную фразу: «Когда мне предложили выбрать темп, я сначала не поверила, что его можно выбрать»."]},{"level":4,"title":"Выбор S14-C2 — Как Алиса покажет Эрику, что ей было хорошо на тропе?","paragraphs":[]},{"level":5,"title":"A. Самой предложить прогуляться вдвоём после ужина","paragraphs":["— Без списка остановок, — добавила Алиса. Эрик на секунду растерялся, затем согласился: после ужина они пройдут до ближайшего фонаря и обратно. Она первой назначила встречу, и от этого ей стало чуть жарче под курткой."]},{"level":5,"title":"B. Поделиться с ним забавной находкой с маршрута","paragraphs":["Алиса показала Эрику на телефоне фотографию следов маленькой птицы на влажной земле. Он долго рассматривал снимок и признался, что не заметил их сам. Она сохранила фотографию не для статьи."]}]},{"id":"S15","title":"День 8. Йёкюльсаурлоун. Не снимать значит увидеть","episode":4,"source":"content/season-1-literary-episode-04.md","chunks":[{"level":0,"title":"","paragraphs":["Утром лёд появился раньше, чем лагуна: на горизонте лежала бледная полоса, похожая на светлое место в стёртой фотографии. На парковке Эрик попросил всех застегнуть куртки и показал, где проходит доступная прогулочная зона. Он не обещал подходить к кромке воды. Ник проверил аккумулятор и тут же снова убрал камеру, когда Алиса на него посмотрела.","— Я могу сначала просто походить, — сказал он.","— Тогда я тоже сначала просто посмотрю, — ответила она.","— Для меня немного экзамен.","Ник нашёл в кармане запасной аккумулятор и положил его на ограждение рядом с камерой, как два предмета, между которыми нужно выбрать. От воды тянуло холодом, и металлическая скоба под ладонью Алисы была влажной. С берега доносились короткие голоса туристов, потом их перекрывал скрежет льдины о соседнюю. Ник наклонился за камерой, но взял только аккумулятор и спрятал обратно. Алиса заметила движение краем глаза. Ей хотелось спросить, о чём он думает; она вспомнила, как сама утром терпеть не могла бы такой вопрос от человека с раскрытым блокнотом. Она отодвинулась от перил, оставив ему место рядом. Ник подошёл через несколько секунд, не касаясь камеры.","В лагуне медленно двигались льдины. Некоторые казались вырезанными из стекла, другие были серыми от старого песка. На противоположном берегу кто-то поднял телефон над головой; отсюда человек выглядел маленьким жестом рядом с большой белой массой. Алиса попробовала придумать вступление к статье и разозлилась на себя. Лёд не нуждался в её метафоре. Ей хотелось стоять, чувствовать холод на лице и не превращать всё услышанное в рабочее.","Эрик с Дамиром отошли к информационному щиту, сверяя время следующего участка дороги. Ник стоял рядом и смотрел не в видоискатель, а на ледяную полосу.","— Я вчера переслушал звук тропы, — сказал он. — На записи больше моего дыхания, чем природы.","— Это можно оставить.","— Я и оставлю. Вопрос только, кому показывать.","Алиса протянула ему одну из своих перчаток: у него на правой руке была перчатка, а левая оставалась голой после возни с ремнём. Ник натянул чужую перчатку, помахал пальцами разного цвета и сказал, что для фильма это будет провал костюмерного отдела. Алиса попросила не возвращать её сразу. Через шерсть он нащупал её ладонь там, где она придерживала ремень его камеры, и оба одновременно отпустили. Ник засмеялся слишком быстро; она тоже. Разговор, который ещё минуту назад мог остаться обычной шуткой, теперь задержался между ними.","Он попытался улыбнуться, но вышло не до конца. Алиса подождала. Ник дважды повернул кольцо на ремне камеры и отпустил его."]},{"level":5,"title":"Если `skogafossVoice=nick`","paragraphs":["Она открыла блокнот на странице о Скоугафоссе и показала ему строчку про два взмаха рукой. Между словами осталась капля высохшего дождя.","— Ты это не вычеркнула, — сказал Ник.","— Ты заметил мальчика, когда менял батарею. Я записала то, чего нет в твоём кадре.","Он провёл пальцем по краю страницы, не закрывая её.","— Значит, даже неудачный оператор может быть свидетелем.","— Я такого вывода не делала.","Он хмыкнул и вернул ей блокнот."]},{"level":5,"title":"Если `skogafossVoice=eric` или `skogafossVoice=damir`","paragraphs":["Алиса открыла блокнот, но страницы о Скоугафоссе не показала: тогда она попросила рассказать другого человека. Ник заметил её движение и подтянул ремень камеры.","— Что у тебя там?","— Вчерашняя тропа. Пока не знаю, как написать о ней.","— Тогда у нас обоих утро без готового кадра."]},{"level":5,"title":"Общее продолжение","paragraphs":["— Ты хотел снять фильм о людях, которые меняют жизнь, — сказала она. — А сегодня оставил камеру закрытой. Что изменилось?","— Название у фильма другое. Рабочее. «Те, кто не умеет останавливаться». Я говорю всем, что снимаю людей на пороге перемен. Звучит благороднее.","Льдина за его плечом почти незаметно повернулась. Ник следил за ней, как за стрелкой часов.","— На премьере одного моего фильма в зале выключили свет, а я всё равно видел, как героиня ищет выход между рядами. На экране она плакала на кухне. Следом шёл мой красивый финал: пустая комната, утреннее солнце, титры. После показа она сказала: «У тебя получилось, что я осталась жить в том дне». Я помню, как красный огонёк над дверью зажёгся раньше, чем я нашёл ответ.","— Ты изменил фильм?","— Из следующей версии вырезал кухню. Продюсер спорил со мной до последнего, но решение о первом монтаже было моим.","Ник поднял камеру за ремень, не доставая из чехла.","— Теперь я снимаю слишком много. Всё кажется, что в соседнем файле найдётся тот кадр, который объяснит человека лучше.","Алиса представила красный огонёк над дверью и свою папку с черновиками. Ник стоял так близко, что ветер трогал край её шарфа и его ремень камеры одновременно. Ей хотелось положить ладонь поверх его пальцев; она удержала руку на блокноте.","— На пляже ты испугался не только за кадр, — сказала она.","— Эрик остановил меня раньше, чем я сам положил камеру в чехол.","— Ты злился на него.","— Злился. Особенно потому, что он был прав.","Рядом прошла пара в одинаковых жёлтых шапках. Ник дождался, пока люди минуют их, прежде чем снова заговорить.","— А этот фильм я никак не закончу. Каждый вечер обещаю себе открыть отснятое. Потом заряжаю батареи и ищу, что снять завтра.","Алиса прислонилась к ограждению. Он подвинулся, чтобы пропустить пару к смотровой площадке, а потом вернулся на то же место рядом с ней. От этого маленького возвращения у неё потеплели щёки сильнее, чем от шарфа.","— Мне кажется, у тебя уже есть одно важное предложение, — сказала она. — Про кнопку монтажа.","— Оно слишком короткое для фильма.","— Тогда начни с него и посмотри, что выдержит рядом.","Он улыбнулся по-настоящему, на секунду.","— Ты сейчас работаешь редактором моего фильма?","— Нет. Это приглашение открыть папку. Я могу сидеть рядом и молчать.","— Ты умеешь?","— Проверишь, если когда-нибудь позовёшь.","Они дошли до безопасной смотровой точки. Солнце вышло на несколько минут, и вода стала цвета неба после дождя. Ник поднял камеру, спросил: «Можно снять общий вид отсюда?» Алиса кивнула. Он снял короткий план лагуны и опустил объектив, когда она вошла в край кадра.","— Я не просила тебя прекращать пейзаж.","— Могу подождать, пока ты выйдешь из кадра. Или снять снова, если захочешь.","Она осталась возле ограждения на секунду дольше и смотрела, как он опускает камеру. Он не торопил её шагом.","На телефоне Алисы всё ещё висело недописанное сообщение Марине. Она взглянула на экран и выключила его. Рассказ о премьере сам просился в текст, но рядом стоял человек, который только что доверил его ей, а не редакции."]},{"level":4,"title":"Выбор S15-C1 — что сделать с личным рассказом Ника","paragraphs":["Выбирается один фрагмент; история премьеры остаётся за пределами заметки."]},{"level":5,"title":"A. Защитить приватность: оставить разговор только между ними","paragraphs":["— Я не запишу это в заметку, — сказала Алиса. — Если когда-нибудь захочешь рассказать сам, я выслушаю. Сегодня это не мой материал.","Ник посмотрел на её закрытый блокнот.","— Ты даже не спросишь, можно ли цитату?","— Нет. Мне сейчас важнее понять тебя, чем получить цитату.","Он прислонил камеру к ноге.","— Хорошо. Тогда я скажу кое-что, что не войдёт в титры: я не знаю, как долго смогу снимать, если люди перестанут отвечать мне доверием.","Алиса встала рядом, пока маленькая льдина медленно отходила от большой. Вечером она перечеркнула строку «Ник боится провала». Ник увидел её закрытый блокнот и предложил нести его до машины; она отдала ему блокнот, а сама взяла его чехол."]},{"level":5,"title":"B. Оставить честный материал, но назвать Нику точные границы","paragraphs":["— Хочу написать только о том, что видела: ты спросил перед съёмкой и опустил камеру. Про премьеру не напишу. Покажу тебе эту строку, прежде чем отправлю.","Ник помолчал. Алиса не подталкивала его к согласию.","— То, что ты видела, можно, — ответил он. — А объяснение я, может быть, когда-нибудь скажу сам.","— Хорошо. Строка будет короткой.","— Это честно. И немного страшно.","— Мне тоже.","Она записала: «Спросил. Опустил камеру». Вечером у машины раскрыла блокнот на этой строке; Ник прочёл, кивнул и не попросил добавить причину. Для отправки редактору они ещё не садились за общий черновик."]},{"level":5,"title":"C. Предложить совместно выбрать один фрагмент и право остановить его","paragraphs":["— Выбери один звук сегодняшнего берега, — сказала Алиса. — Я попробую написать к нему две строки. Прежде чем что-то отправлять, послушаем вместе.","Ник постучал пальцем по чехлу камеры.","— Лёд и вода. Камера поймала, как льдина касается берега.","— А чужие голоса там есть?","Он посмотрел на неё, понял и кивнул.","— В начале кто-то смеётся. Я обрежу. Оставлю только воду.","— Возможно, я вообще оставлю эти две строки себе.","— Тогда у нас будет звук, который никто не обязан услышать.","Они назвали файл «берег_без_голосов». Ник обрезал начало при ней. Алиса написала две строки на обороте чека и сложила его; они договорились вернуться к файлу и тексту завтра, когда будут смотреть материал для редактора."]},{"level":5,"title":"Общее продолжение","paragraphs":["К полудню ветер переменился, и Эрик собрал группу у машины раньше намеченного времени. Ник не спорил. Дамир протянул Алисе оставшуюся булочку, спросив, хочет ли она есть сейчас или оставить на дорогу. Она выбрала половину. Вторую он взял себе, не превратив этот обмен в знак чего-либо.","Когда они уезжали, Ник спросил у Эрика, не возражает ли тот против нескольких секунд, где слышно, как гид называет время возвращения.","— Дай послушать до публикации, — сказал Эрик. — И не делай из этого момент, когда я всех спас.","— Хорошо. Там в основном ты спрашиваешь, у кого мои перчатки.","— Отлично. Оставь это тоже.","В машине Алиса открыла черновик, посмотрела на оставленное для Ника пустое место и закрыла файл. У неё было время до завтрашнего разговора, чтобы выбрать слова, которые он узнает."]},{"level":4,"title":"Если `S14-C2=A`","paragraphs":["Вечером Эрик напомнил Алисе про предложенную ею короткую прогулку. Она взяла куртку без лишних слов, и они вернулись раньше остальных, улыбаясь собственному маленькому плану."]},{"level":4,"title":"Если `S14-C2=B`","paragraphs":["Вечером Эрик спросил, нашла ли Алиса название той маленькой птицы. Они вместе пролистали местный справочник и обнаружили, что оба неправильно угадали её размер."]}]},{"id":"S16","title":"День 8. Гостевой дом у дороги. Чужая боль","episode":4,"source":"content/season-1-literary-episode-04.md","chunks":[{"level":0,"title":"","paragraphs":["До гостевого дома они добрались засветло. На площадке перед входом стояли две машины; одна семья выгружала пакеты, другая безуспешно искала свой ключ среди перчаток. Хозяйка показывала Алисе, где будет общая кухня, когда из коридора послышался короткий вскрик.","Женщина в туристской куртке сидела на низкой скамье. Она поскользнулась у входа и подвернула ногу; её спутница поддерживала её за плечи, одновременно пытаясь открыть телефон. Дамир представился врачом и спросил, можно ли взглянуть на ногу. Женщина кивнула и отодвинула край куртки, чтобы ему было удобнее присесть.","Эрик освободил проход и попросил хозяйку принести стул. Ник убрал камеру в машину. Алиса предложила женщине воду; та взяла бутылку обеими руками. У Дамира был спокойный рабочий голос, которого Алиса почти не слышала в их совместной жизни: тогда он приходил домой уже после смены и рассказывал только смешное или ничего.","— Я не могу по одному взгляду сказать, есть ли перелом, — объяснил он женщине. — Не опирайтесь на ногу, пока вас не осмотрят очно. Есть боль здесь? А здесь?","Она отвечала, показывала, где больно. Когда она попросила секунду, Дамир убрал руки и подождал. Спутница нашла номер местной медицинской консультации; хозяйка помогла уточнить, куда ехать. Дамир коротко изложил, что увидел, и последовал инструкции по телефону. Ник спросил, куда отнести сумки. Женщина указала на дверь комнаты.","Через некоторое время приехал транспорт, который организовали спутница и хозяйка. Дамир передал им записанные сведения и отошёл. Он молча вымыл руки в раковине у кухни и сел на край пустого дивана. На его запястье осталась мокрая полоса; он вытер её рукавом.","Алиса помнила, как когда-то ждала его со смены, а он приносил с собой чужие смешные истории и оставлял трудные за дверью. Потом был Брюссель; даже сейчас при этом слове у неё сжимались пальцы. Она посмотрела на его пустые руки и осталась у дверного косяка, пока он не поднял глаза.","— Ты можешь не смотреть на меня как на статью, — сказал Дамир, когда она остановилась у дивана.","— Я стараюсь. Не всегда получается.","— Тогда дай мне десять минут без вопросов.","Она села на соседнее кресло, оставив между ними столик.","— Хорошо. Что тебе нужно сейчас?","— Уже девять, — сказал он, глянув на часы. — Потом ужин. Если Ник не сварит из него клей.","Алиса вспомнила вчерашний разговор в кафе. Она не хотела возвращаться к нему сейчас, и Дамир не предложил.","— Я схожу посмотрю, что они там нашли для супа, — сказала она.","— Если там только банка фасоли, скажи, что я врач, а не чудотворец.","За окном Ник и Эрик спорили, получится ли сварить суп из еды, купленной по дороге. Один держал пакет, второй — ключ от багажника. Их голоса долетали через стекло глухо. Дамир взглянул на неё поверх спинки дивана, как будто собирался добавить что-то ещё, но лишь кивнул в сторону кухни. Алиса ответила таким же кивком."]},{"level":4,"title":"Выбор S16-C1 — как быть рядом после помощи туристке","paragraphs":["Выбирается один фрагмент; разговор в кафе остаётся на другой день."]},{"level":5,"title":"A. Подойти с конкретной заботой и не требовать разговора","paragraphs":["— Я сделаю тебе чай, — сказала Алиса. — Если не хочешь, скажи.","— Хочу. Без сахара, пожалуйста.","Она поставила чайник и нашла две разные кружки: одну с выцветшей картой острова, другую с китом в нелепом шарфе. Карту оставила себе, кита протянула Дамиру. Он посмотрел на рисунок.","— Ты выбирала специально?","— Нет. Но теперь буду утверждать, что да.","Он улыбнулся и обхватил кружку ладонями. Они не говорили, пока чай остывал до первого глотка. Когда десять минут прошли, Дамир поднялся сам.","— Пойдём посмотрим, что эти двое называют супом?","— После их макарон я требую свидетелей, — ответила Алиса.","Она открыла дверь и, пока он проходил мимо, заметила, что кит на кружке повернулся носом к нему. Дамир поймал её взгляд и усмехнулся."]},{"level":5,"title":"B. Дать ему пространство и ясно назвать, когда увидятся снова","paragraphs":["— Я пойду помогу с ужином, — сказала Алиса. — Ты просил десять минут. Если потом захочешь присоединиться, мы будем на кухне. Если нет — оставлю тебе порцию.","Дамир выдохнул, почти беззвучно.","— Спасибо. За ясное расписание без Эрика.","— Не говори ему. Он запишет меня в заместители.","Она ушла на кухню. Через полчаса Дамир пришёл, когда Ник безуспешно пытался открыть банку, а Эрик доказывал, что суп можно спасти только ещё одной кастрюлей. Алиса поставила перед ним миску; он задержал пальцы на тёплом крае и улыбнулся ей через стол."]},{"level":5,"title":"Общее продолжение","paragraphs":["Перед сном Алиса открыла блокнот. На странице о сегодняшнем дне было три строчки: «Эрик подождал у ручья. Ник опустил камеру. Дамир сел на край дивана с мокрым рукавом». Её собственной строкой стало: «Я вернулась на кухню».","На кухне она сказала, что завтра по дороге в Хёбн принесёт черновик: каждому покажет строки, где его можно узнать. Рассказ о премьере и сегодняшнюю помощь туристке она туда не внесла. Ник спросил, успеет ли она дать ему послушать собственный файл; она ответила, что сначала они вдвоём решат, нужен ли он вообще. Эрик попросил сначала доесть.","Дамир сказал:","— Я посмотрю свой кусок. Если там окажется наш вчерашний разговор, попрошу убрать.","— Его там нет, — ответила Алиса. — Остальное покажу завтра.","Ник подвинул к ней хлеб. Эрик пообещал утром проверить дорогу, прежде чем называть время выезда. Суп вышел слишком солёным; четверо доели его с хлебом и договорились завтра искать в Хёбне нормальные продукты, прежде чем опять спорить над пустой кастрюлей. Ник собирался заняться стиркой дорожных вещей. Дамир предложил взять прищепки из кладовки, если хозяйка разрешит. Алиса закрыла блокнот.","Впереди был ещё один общий день. Никто за этим столом не просил её выбрать, с кем провести вечер, и она пока не знала ответа. Ей нравилось, что незнание можно оставить на завтра.","---"]}]},{"id":"S17","title":"Höfn, день 9. Четыре куртки на одной вешалке","episode":5,"source":"content/season-1-literary-episode-05.md","chunks":[{"level":0,"title":"","paragraphs":["До Höfn они доехали поздним днём. После ледниковой лагуны разговоры в машине то возникали, то обрывались: каждый пытался удержать своё впечатление, не мешая остальным. Алиса смотрела на след от пальца на запотевшем стекле. Ник нарисовал там утку и уверял, что это схема завтрашней дороги.","— Утка смотрит на восток? — спросила Алиса.","— Она смотрит на нас с осуждением. Это универсальное направление.","Эрик не обернулся от руля.","— Если она собирается вести, пусть сначала проверит прогноз.","В гостевом доме пахло мокрой шерстью и чем-то жареным. Хозяйка показала общую кухню, стиральную машину в нише и листок с просьбой освобождать сушилку для следующих гостей. Четыре куртки они повесили на одну перекладину; вешалка жалобно качнулась. Дамир переставил её ближе к стене. Ник успел объявить это первым совместным архитектурным проектом группы.","Алиса обнаружила в кармане мелкий чёрный камешек из вчерашней прогулки. Она не помнила, как взяла его, и положила на подоконник, чтобы потом вернуть земле, а не увезти через границу вместе с квитанциями. Рядом лежал блокнот. В нём после восьми дней дороги было больше записей о том, кто спрашивал «тебе удобно?», чем о видах, за которыми они ехали.","— Есть суп, — сообщил Эрик, заглянув в холодильник. — И хлеб. Хозяйка сказала, что это её ужин для гостей, если мы успеем до девяти.","— «Успеем» звучит как профессиональный вызов, — сказал Ник.","— Девять — через два часа.","— Тем более. Мне нужен вызов по силам.","Суп оказался густым, с морепродуктами; каждый ставил миску себе сам. Ник попросил добавки, хотя ещё не доел первую порцию. Дамир отодвинул от края стола её блокнот, когда Алиса потянулась за хлебом. Он не заглянул в открытые страницы, и она заметила именно это.","За соседним столом две женщины обсуждали поездку, которую пришлось сократить из-за погоды. Одна из них смеялась слишком громко, потом сказала: «Зато мы успели здесь». Алиса записала последние слова в телефон, но не лица и не чужую историю. Поездка была полна решений, которые не принадлежали ей.","Когда ужин закончился, машина всё ещё стояла под окном с пыльными боками. Эрик разложил на столе сухую карту следующего участка. Его палец задержался на восточных фьордах.","— Завтра остаёмся здесь, — сказал он. — Стирка, запас еды, отдых. Послезавтра выедем утром. Мне нужно ещё раз сверить дорогу и время остановок.","— Спасибо за день без чемодана, — сказала Алиса.","— Чемодан можешь носить. Я не отвечаю за личные увлечения.","На кухне засмеялись. Эрик положил карту рядом с её блокнотом, не накрывая его. За эти дни она научилась различать его осторожность и его желание всё предусмотреть. Первое согревало; второе иногда заставляло защищать даже право промокнуть.","Оказалось, что у сушилки свободна только половина полки. Все четверо принесли из комнат сырые вещи. Ник разложил свой тяжёлый свитер поперёк двух секций: рукава не помещались иначе. Алиса держала мокрый шарф и попросила оставить место остальным. Ник снял свитер без спора, но ей стало досадно, что пришлось просить об очевидном. Дамир принёс две чистые прищепки из своего дорожного набора. Эрик поднял сушилку и показал, как выдвигается скрытая секция. Ник повесил свитер на неё, а Алиса подписала на бумажных полосках номера комнат — завтра никто не будет разбирать чужие рубашки.","— Нам понадобилось девять дней, чтобы научиться складывать бельё как команда, — заметил Ник.","— Складывать ещё не научились, — ответил Дамир.","Хозяйка заглянула за своей кружкой и одобрительно кивнула на сушилку. Алиса вдруг поняла, что улыбается уже несколько минут. Ничего важного не произошло: они поели, вытерли стол, освободили проход. Но если Марина спросит, в какой момент поездка перестала быть набором интервью, она, возможно, вспомнит именно эти мокрые рукава.","Она вспомнила обещание, данное у лагуны, и открыла черновик. Не весь файл: только три коротких места, где спутники могли узнать себя. Ник перестал вертеть прищепку, Эрик сложил карту, Дамир вытер руки. Алиса прочитала вслух фразу про Эрика: «У указателя он дождался, пока все подойдут, и только тогда назвал время возвращения». Эрик попросил заменить «назвал» на «предложил»: время они потом изменили вместе. Она исправила при нём.","Дамиру она показала строку: «У туристки заболела нога; Дамир помог ей, а мы задержались». Он прикрыл пальцем вторую половину.","— Про неё у тебя нет разрешения. И не надо писать так, будто я один решил, что ей делать.","Алиса удалила строку целиком. Вместо неё осталась проверяемая общая деталь: «Мы перенесли выезд на десять минут и дождались друг друга у машины». Дамир кивнул. Частный разговор после помощи она даже не открыла.","Нику она повернула экран с абзацем о том, как он остановил камеру у воды."]},{"level":5,"title":"S17-N-A — после S15-C1 A: разговор остался личным","paragraphs":["Между двумя предложениями было белое поле. Ник провёл по нему пальцем, не касаясь экрана.","— Ты правда оставила пустоту.","— Там стояла моя догадка о тебе. Я её вычеркнула.","— Пусть остаётся так. Про камеру — верно, но покажи мне окончательный вариант до отправки.","Алиса поставила рядом пометку «показать Нику», не заполняя пустое место чужим признанием."]},{"level":5,"title":"S17-N-B — после S15-C1 B: согласовано только наблюдаемое действие","paragraphs":["Алиса выделила одно предложение: «Ник спросил перед съёмкой и опустил камеру, когда я вошла в край кадра». Ник перечитал его дважды.","— Так точнее. Я снимал общий вид, ты вошла, и я опустил камеру. Не надо добавлять к этому сцену, которой не было.","Алиса переписала глаголы при нём. Ник разрешил оставить эту строку, но попросил не добавлять рассказ о прежней героине. Она закрыла соседнюю заметку, где хранила его признание."]},{"level":5,"title":"S17-N-C — после S15-C1 C: совместный файл ждёт двух согласий","paragraphs":["Ник показал на телефоне файл «берег_без_голосов»: несколько секунд льда и воды у лагуны без различимых голосов. В её черновике рядом стояло «проверить перед отправкой», без ссылки на файл.","— Мне подходит этот кусок, — сказал он. — Но это моё «да» только на просмотр сейчас. Отправка — отдельный вопрос.","— И моё «да» тоже ещё не дано. Я не прикреплю файл к письму Марине сегодня.","Он убрал телефон. Алиса показала ему отдельное предложение о его действии; он поправил время глагола, и она сохранила правку. Никаких кадров или звука редактор пока не получил."]},{"level":5,"title":"Общее продолжение после S17-N","paragraphs":["Алиса закрыла экран. Эрик вернулся к карте, Ник поставил прищепку на сушилку. Дамир принёс из коридора пустую кружку."]},{"level":5,"title":"S17-E-A — после S13-C1 A: Алиса отвечает за черновик","paragraphs":["— Я пришлю вам эти строки ещё раз перед письмом Марине, — сказала Алиса. — Не прошу одобрить всю статью. Узнаваемое место — да, проверим.","Эрик записал себе её срок на полях карты. Ник попросил не присылать ночью. Алиса отметила это в календаре: ответственность за отправку оставалась у неё."]},{"level":5,"title":"S17-E-B — после S13-C1 B: общий сбор наблюдений","paragraphs":["— Что из сегодняшнего вы сами отдали бы в заметку? — спросила Алиса.","Эрик назвал переставленную сушилку, Ник — спор о носках, Дамир — десять минут у машины. Алиса записала все три предложения рядом, не выдавая их за согласие на биографию или крупный план. Ник попросил оставить за ним право позже вычеркнуть свою строку."]},{"level":5,"title":"S17-D-A — после S16-C1 A: чай без требования рассказа","paragraphs":["Дамир посмотрел на одинаковые белые кружки гостевого дома.","— Здесь нет той, с китом. Вчерашнюю следовало попросить продать.","— Она бы не пережила нашу машину. А тебе не мешает хорошая кружка без профессионального смысла.","Он усмехнулся и отпил из белой кружки. О десяти минутах после помощи туристке никто не спрашивал."]},{"level":5,"title":"S17-D-B — после S16-C1 B: обещанное время сохранилось","paragraphs":["Дамир вернулся к столу после короткого звонка, пока остальные ещё разбирали бельё.","— Вчера мне всё-таки оставили порцию. Спасибо.","— Мы так и договорились, — сказала Алиса. — Сегодня суп стоит здесь, пока Ник не унес добавку.","Дамир сел доесть, пока они заканчивали дела. Алиса не спрашивала, о чём был звонок: у него оставалась своя жизнь за пределами общей кухни."]},{"level":4,"title":"Выбор S17-C1 — какую часть общего дела взять на себя","paragraphs":["Выбирается один фрагмент. Это действие меняет короткий отклик группы, но не определяет вечер и не закрывает ни одну линию."]},{"level":5,"title":"A. Помочь Эрику с планом завтрашнего дня","paragraphs":["— Дай мне карандаш, — сказала Алиса. — Я отмечу, где нам действительно нужно остановиться, а где мы просто привыкли останавливаться.","Эрик подвинул карту.","— Значит, ты отвечаешь за ненужные остановки?","— За нужные, которые выглядят ненужными.","Она поставила маленький круг у набережной. Он не стёр его и отложил карандаш ей."]},{"level":5,"title":"B. Разобрать бельё вместе с Ником","paragraphs":["— Я беру систему меток, — сказала Алиса. — Ты — право смешно её назвать.","Ник посмотрел на полоски бумаги.","— «Операция: носки возвращаются домой».","— На табличку не поместится.","— Тогда просто не теряй мой единственный сухой свитер.","Он протянул ей свитер и впервые за вечер не потянулся к камере, когда их руки встретились."]},{"level":5,"title":"C. Договориться о кухне с Дамиром","paragraphs":["— Ты моешь, я вытираю? — предложила Алиса.","Дамир оглядел груду посуды.","— Могу и наоборот.","— Вот эту часть оставим как есть.","Они встали рядом. Когда у него зазвонил телефон, Дамир спросил, удобно ли ей закончить одной. Раньше он уже уходил бы отвечать; теперь дождался её «да»."]},{"level":5,"title":"D. Раздать дела всем, оставив себе паузу","paragraphs":["— Выбирайте по одному делу, — сказала Алиса. — Я сейчас допью чай и вернусь за стол.","Ник взял посуду, Дамир — сушилку, Эрик — карту. Ник изобразил торжественное распределение полномочий. Алиса осталась у окна на пять минут. Никто не попросил её оправдать эти пять минут полезностью."]},{"level":5,"title":"Общее продолжение","paragraphs":["К вечеру в окне вместо порта отражалась кухня. Эрик спросил, хочет ли Алиса пройтись к огню у входа в гавань: недалеко, если погода позволит. Ник сообщил, что местный бассейн открыт до вечера, и показал расписание на телефоне; камеру он оставит в комнате, если она захочет. Дамир предложил завтра вместе приготовить ужин из продуктов, которые они ещё не покупали. Все предложения прозвучали по очереди, без публики и голосования.","Алиса могла провести это время одна. Она уже несколько дней носила в черновиках письмо Марине: не отчёт о километрах, а просьбу изменить угол материала. Она не была обязана отправлять его именно сегодня. И всё же её собственный план существовал не менее реально, чем три приглашения.","— Я скажу через минуту, — попросила она.","Она вышла в коридор к четырём курткам и выбрала, как провести свободное время до завтрашнего выезда из Höfn: сегодня с Эриком или Ником, завтра вечером с Дамиром либо оба дня по-своему."]},{"level":4,"title":"Выбор S17-C2 — один вечер","paragraphs":[]}]},{"id":"S18","title":"Маяк. Эрик и неотправленная открытка","episode":5,"source":"content/season-1-literary-episode-05.md","chunks":[{"level":0,"title":"","paragraphs":["Эрик ждал у двери не с картой, а с двумя термосами. Один был его, с облезлой наклейкой, второй — гостевого дома.","— В одном чай, — сказал он. — Во втором тоже. Я не настолько талантливый организатор свиданий.","Слово «свиданий» он произнёс спокойно, но проверил её лицо. Алиса забрала второй термос.","— Хорошее начало. Ты хотя бы не обещал мне рассвет в девять вечера.","— Я вообще не обещаю погоду.","За домами ветер был слабее, чем у лагуны, но на открытом участке холод сразу нашёл щель между шарфом и воротником. Они дошли по городской дорожке к гавани. Свет на берегу мерцал за пришвартованными судами; дальше темнота воды делала расстояние обманчивым. Эрик предложил остановиться у ограждения, не идти по мокрым камням.","— Это профессиональная привычка? — спросила Алиса.","— Сегодня — желание оставить тебе целые ботинки. Можем и обратно.","— Я хочу здесь постоять.","Он протянул ей термос. Она наливала чай сама, удерживая крышку в ладони. У Эрика были промокшие рукава: пока все сушили одежду, он забыл о собственной куртке. Алиса напомнила ему об этом. Он посмотрел на ткань с искренним удивлением.","— У специалиста по маршрутам нашёлся непроверенный участок, — сказала она.","— Теперь ты можешь написать честный отзыв.","Они смотрели на свет маяка. Алиса вспомнила, как утром он замолчал, когда она попросила остановиться у лагуны ещё на десять минут. Тогда ей показалось, что он счёл просьбу капризом.","— Ты злился из-за остановки? — спросила она.","Эрик облокотился на холодное ограждение.","— Я считал время. На тебя не злился. Но не сказал этого, и выглядело, наверное, одинаково.","— Да. Я уже готовилась спорить.","— Можешь спорить и сейчас. Иногда я выбираю короткий ответ, потому что длинный похож на оправдание.","Ей понравилось, что он не стал сразу объяснять ей её чувство. Она рассказала, как в детстве боялась отстать от экскурсии: мама шла быстро, а она всё находила камни и вывески, которые хотелось прочитать. Эрик слушал, не превращая воспоминание в урок о правильном темпе.","— А ты? — спросила она. — Куда спешишь, когда никто не платит за маршрут?","— Домой, — ответил он после паузы. — Хотя последние годы «домой» каждый раз оказывалось другим адресом.","Оказалось, он приехал сюда на один сезон и задержался на несколько. Он любил показывать людям места, но устал быть человеком, который обязательно знает ответ на следующий вопрос. Вне работы у него оставались несколько друзей, старая музыка в машине и коробка вещей, которую он ни разу не распаковал полностью. Алиса могла бы уточнить, почему он остаётся. Вместо этого спросила, есть ли в коробке что-то, о чём он скучает.","— Почтовые открытки моего деда. Он отправлял их из городов, где почти ничего не происходило. На каждой писал одно новое слово и одну очень скучную подробность. Так я знал, что он действительно там был.","Эрик вынул из кармана сложенную открытку, купленную сегодня у стойки гостевого дома. На лицевой стороне было судно, снятое так близко, что берег не попадал в кадр. Оборот оставался чистым.","— Я хотел написать сестре, — сказал он. — «Всё по плану». Уже минут двадцать не могу.","— А что было не по плану?","Он повернул открытку к свету телефона, но не предложил ей дописать за него.","— Мне хотелось, чтобы ты вышла со мной. И я не знал, как это предложить, не превращая прогулку в часть расписания.","Алиса почувствовала одновременно радость и настороженность. У неё было достаточно опыта, чтобы знать: признание в желании ещё не договорённость о завтрашнем дне. Она сказала об этом проще.","— Я вышла, потому что тоже хотела. Сегодня. За завтра не отвечаю.","— Мне подходит сегодня.","Они молча разделили остаток чая. Из открытой двери маленького заведения у гавани доносилась музыка — старая песня, которую Алиса уже слышала в машине и тогда не успела спросить название. Эрик узнал первые звуки и, к её удивлению, напел несколько слов. Голос у него был низкий и не слишком точный.","— Ты умеешь петь, — сказала она.","— Нет. Я просто не стесняюсь этой песни.","Его сестра включала её при уборке в их первом общем жилье: один держал коробку, другой непременно бросал её на пол и начинал танцевать. В этом воспоминании Эрик был младшим братом, а не человеком, у которого всегда есть ключ от машины и запасной путь. Алиса попросила показать, что сестра называла танцем. Он поставил пустой термос на сухую скамью и протянул ей ладонь. Она поправила шарф и сама подошла ближе.","Эрик сделал два шага в сторону, Алиса попыталась повторить, и оба остановились, когда из заведения вышли люди. Смешно стало не от ошибки, а от серьёзного лица Эрика: он пытался вспомнить третье движение. Алиса придумала своё и потянула его за собой. Песня закончилась прежде, чем у них получилось что-то похожее на танец.","— У сестры выходит лучше? — спросила Алиса.","— Она утверждает, что да. Когда-нибудь проверишь, если встретитесь.","Он не произнёс это как приглашение в готовое будущее. Алиса услышала лишь возможность, которая на секунду стала приятной. Она вернула ему термос, и они пошли дальше уже без музыки.","На обратной дороге заметили, что один из городских указателей повернуло ветром. Стрелка вела к мокрым камням, а освещённый тротуар обходил склад. Эрик достал карту, но Алиса остановила его:","— Вон название улицы на двери. Проверим ногами, до перекрёстка две минуты.","Она первой пошла по тротуару. Обход вывел к нужному месту. Эрик снял указатель для хозяйки гостевого дома, которая утром давала гостям этот ориентир. Алиса заметила своё отражение в стекле на краю кадра; он переснял столб без неё и отправил хозяйке короткое сообщение. Через несколько минут пришло спасибо и обещание утром проверить знак.","— Вышли просто пить чай, а уже исправили маршрут, — сказала Алиса.","— Маршрут исправила ты. Я умею отправлять фотографии.","У ограждения она вернула ему крышку термоса. Их пальцы задержались на одном краю металла. Эрик спросил:","— Можно я тебя поцелую?","Алиса поставила крышку на ограждение и посмотрела на него прежде, чем ответить. Свет маяка скользнул по воде и ушёл дальше."]},{"level":4,"title":"Выбор S18-C1 — близость у ограждения","paragraphs":[]},{"level":5,"title":"A. Поцеловать Эрика","paragraphs":["— Да, — сказала Алиса. — Только не как пункт маршрута.","— У меня нет такой графы.","Он не придвинул её к себе; она сама сделала шаг. Поцелуй вышел коротким из-за холодного воздуха и неожиданно тёплым из-за того, что после него никто не спешил назвать случившееся началом чего-то большого. Алиса коснулась его мокрого рукава.","— Тебе точно пора сушить куртку.","— Это мой лучший план на остаток ночи.","Они засмеялись и пошли обратно рядом, не держась за руки автоматически."]},{"level":5,"title":"B. Остаться рядом без поцелуя","paragraphs":["— Мне хорошо здесь, — сказала Алиса. — Поцелуй пока не нужен.","Эрик убрал руку с ограждения, чтобы не оставить её между своей рукой и металлом.","— Спасибо, что сказала.","— Это не экзамен, который ты не сдал.","— Я понимаю. И всё равно рад, что ты осталась.","По дороге назад он спросил, какую песню поставить завтра в машине. Алиса выбрала ту, название которой он однажды не назвал. Их спор о музыке занял всю дорогу до дверей дома."]},{"level":5,"title":"C. Попросить закончить прогулку","paragraphs":["— Я хочу вернуться, — сказала Алиса. — Мы поговорили больше, чем я ожидала.","Эрик сразу закрыл термос.","— Пойдём. Я могу проводить до дома и там попрощаться.","— Именно так.","Он не выяснял, испортил ли всё каким-то словом. Возле гостевого дома Алиса сказала, что разговор о его открытках ей понравился. Эрик поблагодарил её и пошёл сушить куртку. У двери не осталось ни обещания, ни долга."]},{"level":5,"title":"Общее продолжение S18","paragraphs":["У себя Алиса записала не «маяк — романтика», а: «Когда спросили, я смогла ответить сразу».","Утром десятого дня открытка всё ещё лежала у Эрика на столе. Он написал сестре сам: «Мы добрались до Höfn. У меня промокла куртка». Алиса увидела только эту строку, когда он показал ей смешную фотографию судна; остальное осталось его письмом.","Хозяйка попросила их утром помочь проверить указатель. На месте оказалось, что вернуть стрелку на прежний угол мало: с другой стороны её заслонял припаркованный фургон. Алиса прошла безопасным обходом и нарисовала хозяйке схему. Та повесила её у двери до приезда человека, который закрепит знак. Эрик не назвал схему своей. Алиса не превратила хозяйку в персонажа статьи только потому, что разговор получился удачным.","Завтрак они ели со всей группой. Ник хотел знать, видел ли кто-нибудь ночью освещённую гавань, но Алиса могла ответить ему о погоде, не отчитываясь о поцелуе или его отсутствии. Днём она прошлась по городу, выстирала шарф и дописала две страницы заметок. Эрик занимался дорогой и своим делом. Их вечер не забрал у следующего дня самостоятельности.","Перед сном десятого дня в коридоре встретились все четверо: собирали вещи к утреннему выезду."]},{"level":5,"title":"S18-K — после поцелуя","paragraphs":["Эрик остановился рядом с Алисой, пока Ник искал ключи. «Тебе удобно, если я завтра сяду рядом?» — спросил он негромко. Она ответила, что решит утром. Он кивнул и ушёл сушить термос. При остальных вчерашний поцелуй не повторился."]},{"level":5,"title":"S18-S — после вечера без поцелуя","paragraphs":["Эрик передал Алисе её шарф, забытый у схемы. «В машине есть та песня, о которой мы спорили», — сказал он. Она попросила поставить её после первого привала. Он записал название на своей карте."]},{"level":5,"title":"S18-L — после раннего возвращения","paragraphs":["Эрик указал на новый обход на схеме: «Ты вчера заметила ошибку первой. Спасибо». Алиса забрала блокнот и сказала, что утром проверит ещё один адрес для дороги. Они разошлись по комнатам."]},{"level":5,"title":"Переход S18","paragraphs":["Утром дня 11 — S22."]},{"level":4,"title":"Выбор S18-C2 — Как Алиса продолжит разговор с Эриком перед общим выездом?","paragraphs":[]},{"level":5,"title":"A. Спросить о дедушкиных открытках","paragraphs":["За завтраком Алиса спросила Эрика, сохранилась ли у него любимая открытка деда. Он показал фотографию старой почтовой марки на телефоне. Они поговорили о путешествиях его семьи; Алиса не пыталась превратить этот разговор в признание."]},{"level":5,"title":"B. Предложить ему выбрать песню для дороги","paragraphs":["Алиса попросила Эрика выбрать музыку на первые полчаса дороги. Он долго искал нужный трек, а потом остановился на песне, которую они уже слушали вместе. Алиса предложила оставить её до выезда — сначала всем нужно было собрать вещи."]}]},{"id":"S19","title":"Бассейн. Ник без удачного кадра","episode":5,"source":"content/season-1-literary-episode-05.md","chunks":[{"level":0,"title":"","paragraphs":["У входа Ник поднял телефон экраном к Алисе: в расписании стояло, что сегодня, в будний день, открыто до девяти.","— Последний час открыт. Если мы потратим его на обсуждение, это будет очень современное свидание.","— Ты уже объявил его свиданием?","— Я могу переименовать. «Совместная проверка температуры воды».","Алиса засмеялась и остановилась у двери. На его плече висела сумка, из которой торчал ремень камеры.","— Ты сказал, что оставишь её в комнате.","Ник посмотрел на ремень так, будто тот вырос только сейчас.","— В сумке ещё полотенце. Камеру я вынул... подожди.","Он расстегнул молнию. Камера действительно лежала внутри. Раздражение Алисы не исчезло от того, что он честно удивился.","— Ты взял её по привычке, — сказала она.","— Да. Отнесу назад. Ты можешь зайти и ждать внутри; можешь пойти со мной. Пять минут.","— Я подожду здесь. И если мы войдём, без съёмки.","— Без съёмки.","Он ушёл быстрым шагом и вернулся без сумки, зато с полотенцем, намотанным вокруг шеи как нелепый шарф. От своего промаха он не стал спасаться длинной шуткой.","В раздевалках они разошлись. Алиса вышла к открытому бассейну первой. Местные разговаривали негромко; никого не интересовало, кто приехал издалека и почему. Над водой темнело октябрьское небо. Вода была достаточно тёплой, чтобы постепенно перестать помнить холод прогулок, но не настолько, чтобы растворить мысли.","Ник появился с мокрыми волосами, огляделся и помахал ей из другой стороны бассейна. Он не бросился сразу рядом. Алиса подплыла к бортику, где он держал ладони на плитке.","— Если ты спросишь, как я выгляжу без камеры, я отвечу честно, — предупредила она.","— Я хотел спросить, кто придумал эту лестницу. Но теперь заинтересовался ответом.","— Выглядишь человеком, который забыл очки и слишком горд, чтобы щуриться.","Он рассмеялся. Через несколько минут Ник предложил игру: каждый должен придумать по одному невозможному названию для фильма об их сегодняшнем дне. Его вариант был «Человек, победивший молнию на сумке». Алиса назвала свой «Восемь минут, которых никто не получит». Ник не переспросил, для кого фильм. Он просто запомнил название.","У противоположного края бассейна освободилась дорожка. Алиса предложила доплыть до неё без соревнования, но Ник немедленно спросил, какие призы дают за второе место. На середине он потерял ритм, остановился и пропустил её вперёд. Она коснулась бортика первой и оглянулась. Он плыл медленно, без показной лёгкости, с упрямо сведёнными бровями. Она подождала, пока он доплывёт, не превращая его заминку в повод спасать.","— Можешь сказать, что я проиграл, — выдохнул Ник.","— Мы не соревновались.","— Тогда я зачем так старался?","— Мне тоже интересно.","Он отплыл от края на несколько метров и лёг на спину. Алиса повторила. Над ними был тёмный воздух, из соседней дорожки долетал плеск; пар поднимался от воды и исчезал прежде, чем закрыть фонари. Ник признался, что в воде всегда пытается выглядеть уверенно, потому что в детстве ходил на занятия позже всех друзей. Он не рассказал историю о травме или героическом преодолении — просто показал, как его левая рука сбивается, когда он торопится. Алиса попробовала плыть рядом медленнее, в его темпе. На этот раз он добрался до конца без остановки. Оба вышли из воды довольными не результатом, а тем, что можно было выглядеть неуклюже и всё равно остаться рядом.","Потом игра кончилась сама собой. Алиса оперлась затылком о бортик. Ник сказал, что ему трудно оставлять дни без изображения. Не потому, что все дни хорошие; наоборот, плохой можно пересобрать. Поставить утреннюю шутку перед вечерней тишиной — и получится человек, который всегда справлялся.","— Я знаю, что это нечестно, — сказал он. — Просто иногда монтаж кажется добрее памяти.","— К кому?","— Ко мне, наверное.","Он не добавил историю о провале, которую уже рассказал ей у лагуны, и не просил утешения. Алиса вспомнила, как там он впервые произнёс слово «страшно» без улыбки. Сегодня он пытался сидеть в этом слове дольше одной секунды.","— Если ты вырежешь из нашей поездки всё, где мы молчим, — сказала она, — я там не узнаю ни тебя, ни себя.","— Тогда не буду решать за тебя, какие куски оставить.","— Это обещание для фильма?","— Да. И для этого вечера — тоже.","Когда они вышли, окно в маленьком холле отразило две вытянутые тени. Ник остановился.","Администратор искал потерянный браслет от шкафчика. Гость помнил номер по фотографии, но телефон разрядился. Ник уже поднял руку к карману, будто там была камера, и опустил её. Вместе с Алисой они прошли вдоль скамей. Алиса нашла браслет под свёрнутым полотенцем. Гость поблагодарил; Ник смутился сильнее неё.","— Без кадра никто не поверит в нашу спасательную операцию, — шепнул он.","— Я подтвержу номер шкафчика под присягой.","Пока они обувались, Ник рассказал, как однажды смонтировал из чужой растерянности смешную сцену. Человек на просмотре смеялся, а на другой день попросил её убрать. Ник убрал, но запомнил своё первое раздражение. Алиса не похвалила его за удаление. Он впервые договорил историю без шуточного выхода.","— Сейчас было бы смешно снять только тени, — сказал он. — Без лиц, без публикации. Но телефона с собой нет. Я могу сходить за ним, если ты хочешь. Или оставим это своим.","Она видела, как хочется ему поймать изображение. Ей было приятно, что он спросил до того, как достал телефон. И неприятно, что вопрос всё равно возник. Это были два разных чувства, ни одно не требовало срочно отменить другое."]},{"level":4,"title":"Выбор S19-C1 — кому достанется отражение","paragraphs":[]},{"level":5,"title":"A. Снять тени на телефон Алисы","paragraphs":["— На мой, — сказала Алиса. — Один снимок. Он останется у меня, пока я сама не решу иначе.","— Договорились.","Она достала телефон и навела его на стекло. Ник отошёл на полшага, чтобы в кадре были только отражения, и спросил, можно ли вернуться. Она кивнула. На снимке получились две неровные фигуры и яркая вывеска между ними.","— Худшая реклама романтики, — сказал Ник.","— Моя любимая версия этого вечера.","Она убрала телефон, не пересылая снимок ему. Ник не попросил копию."]},{"level":5,"title":"B. Не снимать совсем","paragraphs":["— Оставим это своим, — сказала Алиса.","Ник поднял руки, словно отпустил невидимую камеру.","— Тогда мне понадобится другое доказательство, что мы здесь были.","— У тебя мокрое полотенце.","— Убедительно.","Они купили по стакану воды в холле и смотрели, как отражения распадаются всякий раз, когда кто-нибудь проходит мимо. Ник не повторил предложение. По дороге он выдумал название для отсутствующего кадра и попросил Алису запомнить его вместо записи."]},{"level":5,"title":"C. Предложить сделать снимок завтра днём, если захочется обоим","paragraphs":["— Сейчас нет, — сказала Алиса. — Завтра при свете спроси ещё раз. Возможно, я захочу снять тебя сама.","Ник широко улыбнулся, потом улыбка стала меньше и серьёзнее.","— Это честное «возможно»?","— Да. Не бронь на завтра.","— Принято.","Они вышли, оставив тени за стеклом. Завтрашнее «возможно» оставалось вопросом."]},{"level":5,"title":"Общее продолжение S19","paragraphs":["На обратном пути из бассейна мимо пустой витрины тянулась музыка из чужого автомобиля. Ник поймал ритм, сделал два нелепых шага и протянул Алисе руку ладонью вверх.","— Мой фильм сейчас переживает тяжёлое время. Может, хотя бы танец?","Алиса взяла его руку. Ник сделал шаг слишком широко, задел ботинком бордюр и рассмеялся над собой раньше, чем она успела испугаться. Она поставила его на сухой асфальт и задала медленный счёт. Музыка уехала вместе с машиной; последние два шага они сделали в тишине.","— Я думал, если не сниму, забуду, — сказал Ник.","— Забудешь часть. Я тоже.","— Мне это не нравится.","— Мне иногда нравится, что невозможно показать всё остальным.","Он посмотрел на неё без привычной готовой реплики."]},{"level":4,"title":"Выбор S19-C2 — ответить на близость","paragraphs":[]},{"level":5,"title":"A. Самой предложить поцелуй","paragraphs":["— Можно я тебя поцелую? — спросила Алиса.","— Да. Подожди, я сейчас не шучу.","Он придвинулся только после её шага. В его волосах ещё пахло водой бассейна. Когда они разошлись, Ник первым произнёс:","— Я помню.","— Это и было условие.","Он провёл её до двери гостевого дома, не превращая поцелуй в сцену про двух победителей."]},{"level":5,"title":"B. Обнять его и оставить вечер без поцелуя","paragraphs":["— Обними меня, если хочешь, — сказала Алиса. — На этом остановимся.","Ник спросил глазами ещё раз; она кивнула. Он обнял её поверх куртки, крепко и недолго.","— Я всё время ищу финальный кадр, — признался он.","— У вечера есть дверь. Этого достаточно.","Он отпустил её прежде, чем она попросила, и они вошли в дом порознь."]},{"level":5,"title":"C. Сохранить дистанцию","paragraphs":["— Мне сейчас хочется дойти одной, — сказала Алиса.","Ник убрал протянутую руку.","— Тогда я зайду через пару минут. Ты можешь не объяснять.","— Не хочу, чтобы ты считал бассейн ошибкой.","— Не считаю. И твой ответ тоже.","Она пошла впереди, слыша за спиной шаги только до угла, где он действительно остановился."]},{"level":5,"title":"Общее продолжение S19","paragraphs":["На десятый день Ник прислал Алисе сообщение из соседней комнаты: «Я помню название фильма. Не напишу его здесь, чтобы не испортить эксперимент». Она улыбнулась, но не обязана была отвечать. За общим завтраком он говорил о хлебе, прогнозе и забытой кем-то ложке. Он не использовал их вечер как шутку для группы."]},{"level":5,"title":"S19-P-A — после снимка теней на телефон Алисы","paragraphs":["Ник попросил Алису показать ему снимок, не забирая телефон из её рук. «Вчера вывеска делила нас пополам», — сказал он. Алиса заметила это только теперь. Снимок остался в её галерее, у Ника его не было."]},{"level":5,"title":"S19-P-B — после отказа от снимка","paragraphs":["Ник спросил, помнит ли она название их неснятого фильма. Алиса нарочно перепутала два слова; он поправил её и засмеялся. Записывать название никто не стал."]},{"level":5,"title":"S19-P-C — после предложения спросить утром","paragraphs":["Ник снова спросил за завтраком, осталось ли у неё желание снимать. Алиса ответила: «Сегодня нет. Мне нравится, что ты спросил снова». Он сказал «хорошо» и отодвинул ей тарелку с хлебом. Телефон так и остался в кармане.","Днём у Ника завис монтажный файл. На экране остался кадр, где Алиса у лагуны отвернулась от объектива. Он позвал её решить, оставлять ли этот кусок. Она попросила удалить его из рабочей последовательности. «Там хорошо видно ветер», — начал Ник, услышал себя и нажал удалить. Для ветра нашёлся кадр пустой тропы. Она осталась рядом, пока программа сохранила проект.","Вечером, когда Алиса вошла на кухню, экран ноутбука был закрыт. Ник спросил, хочет ли она чаю."]},{"level":5,"title":"S19-K — после поцелуя","paragraphs":["Ник поставил чай на стол, а сам сел напротив. «Вчера я говорил серьёзно», — сказал он негромко. Алиса ответила: «Я помню». Позже он прислал ей список кадров, которые хотел показать группе, чтобы она заранее отметила своё присутствие."]},{"level":5,"title":"S19-H — после объятия","paragraphs":["Ник положил возле чашки бумажку с тем самым невозможным названием фильма. Алиса спрятала её в блокнот. «Сегодня без финального кадра?» — спросила она. «Сегодня сохраняю черновик», — ответил он и пошёл за полотенцами."]},{"level":5,"title":"S19-D — после просьбы о дистанции","paragraphs":["Ник спросил из дверей, можно ли войти на кухню, где Алиса уже сидела. Она сказала «да»: вчерашнее желание пройти одной не превращало общий стол в запрет. Он занял место у окна и спросил про чай, не приближаясь к её стулу."]},{"level":5,"title":"Переход S19","paragraphs":["К вечеру вещи высохли, рюкзаки стояли у дверей. Утром дня 11 — S22."]},{"level":4,"title":"Выбор S19-C3 — Что Алиса предложит Нику после совместного вечера?","paragraphs":[]},{"level":5,"title":"A. Провести часть завтрашнего дня без камер","paragraphs":["— Хочу посмотреть город с тобой, а не на твоём экране, — сказала Алиса. Ник убрал камеру в сумку и ответил, что знает хорошую пекарню. Он пригласил её туда до общего выезда."]},{"level":5,"title":"B. Найти место с самым необычным местным завтраком","paragraphs":["Алиса предложила Нику зайти в маленькое кафе, куда они ещё не заходили. Он начал читать отзывы, но она остановила его: «Давай просто посмотрим». Они выбрали место по запаху свежего хлеба из открытой двери."]}]},{"id":"S20","title":"День 10. Дамир покупает незнакомое","episode":5,"source":"content/season-1-literary-episode-05.md","chunks":[{"level":0,"title":"","paragraphs":["Вечер девятого дня Алиса провела у себя. Через стену было слышно, как кто-то в коридоре роняет ключи; это оказался Ник, а не Дамир. Она прочитала несколько страниц книги и уснула без разговора о прошлом. Утром Дамир встретил её за общим завтраком и спросил, остаётся ли их договорённость в силе.","— Да. Но я не обещала повторить твой знаменитый ужин.","— Я и сам не хочу повторять, — сказал он. — Пойдём посмотрим, что есть в магазине.","Она знала его список покупок наизусть: рис, помидоры, знакомые специи, попытка приготовить быстро то, что когда-то удавалось без часов. Два года назад им хватало обменяться взглядами у полки. Сегодня это сходство было и удобством, и ловушкой.","В магазине Дамир потянулся к обычной упаковке крупы, затем остановился.","— Ты хочешь именно это? — спросил он.","— Я хочу, чтобы мы сначала посмотрели всё.","Они нашли небольшую упаковку перловки, местные грибы и свежую зелень. Дамир предложил добавить копчёную рыбу, но Алиса не была уверена, что сочетание получится. Продавец помог им выбрать более мягкий вкус. Пока мужчина взвешивал кусок, Алиса заметила у кассы стойку с местными открытками: на одной рыба выглядела так торжественно, будто её избрали главой города. Дамир увидел, куда она смотрит, и купил открытку вместо лишней банки специй.","— Не пытайся подкупить меня рыбой, — сказала Алиса.","— Я купил её себе. У меня дома пустая стена.","Она помнила квартиру, где раньше не было места ни для чего бесполезного. Новый адрес Дамира она не видела. Он показал ей фотографию стены — маленькой, с полкой для книг и одним криво прибитым крючком. Алиса указала, где открытка будет выглядеть хуже всего. Он сказал, что там и повесит: утром её увидит первым делом. Это была нелепая, но совершенно его собственная будущая мелочь, не адресованная ей.","У выхода пакет порвался у ручки. Дамир поймал перловку, Алиса — пучок зелени. Они присели на корточки прямо у двери, раскладывая покупки по двум сумкам, и расхохотались от того, что каждый прижал к груди свою добычу. Продавец вынес им новый пакет. Когда они поднялись, Дамир предложил нести тяжёлое; Алиса отдала ему именно рыбу, а перловку оставила себе. По дороге назад он признался, что впервые за долгое время купил продукты без мысленного плана на три дня.","— Ты ведь врач, — сказала Алиса. — Как ты переживёшь отсутствие плана?","— Очень профессионально. Буду паниковать внутри.","Она засмеялась. Ей нравилась его способность сделать полезное из беспорядка. Когда-то она стала принимать её за готовность решать и за неё тоже. Теперь Дамир спрашивал чаще, иногда неловко, будто учился новому языку в середине разговора.","До ужина они разошлись по своим делам. Алиса дописала заметку о том, как группа задержалась ради чужого темпа; Дамир сходил за хлебом и проверил, достаточно ли у них соли. В шесть вечера они заняли общую кухню: Эрик сверял маршрут и говорил по телефону у входа, Ник вернулся со съёмки гавани. На плите оставалась одна свободная конфорка. Хозяйка попросила освободить раковину к семи, когда придут следующие гости. Алиса поставила таймер и отдала Дамиру доску для грибов.","Дамир нарезал грибы слишком мелко. Алиса напомнила, что они ужарятся. Он отложил нож.","— Точно. Ты всегда... — начал он и осёкся.","— Договаривай.","— Ты всегда замечала это раньше меня.","— Замечала. Но раньше ты всё равно резал по-своему.","Он хотел возразить. Она увидела это по тому, как у него выпрямилась спина. Вместо возражения Дамир взял другой гриб и разрезал его крупнее.","— Здесь ты права. Я помнил, что мы готовили вместе. Не помнил, сколько в этом было твоего молчания.","Алиса повернула ложку в пальцах. Ей не хотелось, чтобы ужин превратился в суд над прошлым; ещё меньше хотелось снова уступить ради приятного вечера.","— Я тоже делала вид, что мне всё равно, — сказала она. — Так было проще, чем спорить из-за каждой мелочи.","— А сейчас?","— Сейчас мне не всё равно, что лежит на тарелке. И что ты слышишь, когда я это говорю.","В сковороде зашипело масло. Они вернулись к рецепту, который не знали заранее. Алиса добавила зелень в конце, Дамир попробовал и признал, что рыбы нужно было меньше. Блюдо получилось съедобным и не похожим на их прежний ужин. Он предложил записать пропорции; Алиса сказала, что лучше запомнит ошибку и удачную поправку. Оба варианта показались ему разумными, и он не настоял.","Когда таймер зазвенел, в кухню вошла пожилая пара с кастрюлей и хлебом. Они искали свободное место для своей еды. Дамир уже собирался сдвинуть чужую посуду, но Алиса остановила его и спросила гостей, нужна ли им конфорка сейчас. Оказалось, они хотели только подогреть воду. Алиса освободила свою половину стола; Дамир перенёс их сковороду на подставку. Пара получила плиту, а они — десять минут, чтобы попробовать ужин без спешки. Дамир тихо сказал, что раньше счёл бы это помехой их разговору. «А я раньше промолчала бы и злилась», — ответила Алиса. Они доели первую порцию, пока чайник соседей шумел рядом.","За столом Дамир рассказал, что за эти два года несколько раз менял дежурства и город, а в одном месте научился ужинать один без включённого телевизора. Алиса рассказала, как после расставания боялась возвращаться к некоторым песням, а потом однажды услышала знакомую мелодию в чужом кафе и не почувствовала ничего, кроме голода. Он не спросил, значит ли это, что она его забыла. Она не попросила у него перечень раскаяний.","— Мне понравилось, что в Вике мы говорили о том, как живём сейчас, — сказала она. — Но сегодня, когда ты начал фразу «ты всегда», мне захотелось уйти.","— Я заметил. Раньше я бы попросил остаться хотя бы до конца разговора.","— А теперь?","— Ужин уже закончился. Ты можешь уйти. Я хочу, чтобы ты знала: мне нравится говорить с тобой сейчас. Не с тем человеком, которым ты была тогда.","Он сложил салфетку, оставив ей пространство ответить или подняться. Хозяйка заглянула напомнить о раковине. Они вместе убрали посуду, пропустили к крану соседей и вернулись к столу уже без сковороды между ними."]},{"level":4,"title":"Выбор S20-C1 — что делать после ужина","paragraphs":[]},{"level":5,"title":"A. Остаться на чай и предложить новый поцелуй","paragraphs":["— Я останусь ещё на чашку, — сказала Алиса. — И хочу тебя поцеловать. Но это не отменяет того, о чём мы говорили.","Дамир застыл с чистой тарелкой в руках, поставил её и спросил:","— Ты уверена именно сейчас?","— Да.","Он подошёл медленно. Их поцелуй был знакомым только первые мгновения; потом Алиса отступила на шаг и поняла, что может сделать это без объяснения. Дамир налил чай. Они выпили его за столом, не называя этот вечер возвращением."]},{"level":5,"title":"B. Остаться на чай без прикосновения","paragraphs":["— На чай я останусь, — сказала Алиса. — Больше пока не надо.","— Хорошо.","Дамир разлил воду по чашкам и, вместо того чтобы сесть близко, занял место напротив. Они спорили, можно ли считать блюдо удачным, если его не получится повторить. Алиса сказала, что можно. Он записал только список продуктов, оставив пропорции пустыми. Это оказалось точным описанием их сегодняшней договорённости."]},{"level":5,"title":"C. Уйти, сохранив честность разговора","paragraphs":["— Я пойду к себе, — сказала Алиса. — Мне нужно побыть с этим разговором одной.","— Спасибо, что сказала прямо.","— Я не обещаю вернуться к нему завтра.","— И не должна.","Он протянул ей контейнер с оставшейся едой, но сначала спросил, хочет ли она взять его. Алиса отказалась. Дамир закрыл крышку и поставил контейнер в общий холодильник для всех, не превращая его в сообщение, которое ей пришлось бы принимать."]},{"level":5,"title":"Общее продолжение S20","paragraphs":["Позже Алиса увидела на доске кухни бумажку: «Перловка, грибы, слишком много рыбы — уменьшить». Почерк был Дамира. Ни её имени, ни обещания «как раньше». Она дописала карандашом: «Зелень — в конце». Когда он пришёл за курткой, заметил поправку и улыбнулся, но не стал искать её по дому.","Перед выездом утром одиннадцатого дня они оба встали у открытого багажника."]},{"level":5,"title":"S20-K — после поцелуя","paragraphs":["Дамир спросил, можно ли поставить её рюкзак рядом со своим. «Можно. Только не делай из этого систему», — сказала Алиса. Он улыбнулся и оставил между сумками место для Никовых вещей. Вчерашний поцелуй не повторился при группе."]},{"level":5,"title":"S20-T — после чая без прикосновения","paragraphs":["Дамир протянул ей бумажку с исправленным списком продуктов. Алиса увидела, что он сам вычеркнул лишнюю рыбу. «На следующий ужин?» — спросила она. «На случай, если кто-нибудь попросит рецепт», — ответил он. Она сложила лист и убрала в блокнот."]},{"level":5,"title":"S20-L — после ухода","paragraphs":["Дамир спросил, удобно ли ей самой поставить рюкзак наверх. Алиса кивнула и подняла его. Дамир придержал дверь багажника, не возвращаясь к вечернему разговору. Контейнер с едой остался в общем холодильнике для остальных."]},{"level":5,"title":"Переход S20","paragraphs":["Утром дня 11 — S22."]},{"level":4,"title":"Выбор S20-C2 — Как Алиса предложит провести оставшееся свободное время с Дамиром?","paragraphs":[]},{"level":5,"title":"A. Сходить вместе за продуктами для следующего завтрака","paragraphs":["Алиса предложила Дамиру выбрать продукты для всех, но сначала спросить остальных, что они хотят. Он принёс список в общий чат. Ник прислал в ответ фотографию пустой чашки, и им пришлось самим решить только вопрос кофе."]},{"level":5,"title":"B. Прогуляться до воды без разговора о прошлом","paragraphs":["Алиса попросила Дамира пройти с ней до набережной. По дороге он показал ей смешную вывеску, которую заметил утром. Они разговаривали о городе и холодном ветре, а не о том, что было между ними два года назад."]}]},{"id":"S21","title":"День 9, вечер. Письмо, которое не просили писать","episode":5,"source":"content/season-1-literary-episode-05.md","chunks":[{"level":0,"title":"","paragraphs":["После выбора Алиса вернулась в комнату раньше остальных. За окном медленно проходили машины; ветер трогал вывеску гостевого дома. Ей хотелось есть, хотя она только что поужинала: это было знакомое ощущение перед трудным письмом.","Марина просила материал о переменах. В первых черновиках Алиса старательно искала людей, у которых перемена звучала бы красиво: уехать, рискнуть, начать заново. Теперь в памяти всплывала женщина, сократившая поездку, и никто не называл это поражением. Всплывали перчатки у сушилки и разговор о том, кому достанется полка. Дорога состояла не только из решений свернуть. Иногда её делали возможной просьбы остаться на месте.","Алиса открыла письмо редактору. Написала: «Я предлагаю изменить серию». Удалила слово «предлагаю», потому что слышала в нём просьбу разрешить ей иметь мысль. Вернула его: редактор имела право обсудить формат, и честность не требовала резкости.","Она набрала: «Сейчас мне интереснее, как люди договариваются о маршруте, чем причины, по которым они в него отправились». Потом остановилась. Было легко сделать из спутников убедительные примеры. Но ни один из них не соглашался стать иллюстрацией её тезиса. Ей следовало сначала найти форму, которую можно защитить без чужих личных сцен.","Она вышла на общую кухню за водой. Там сидела Рагна, хозяйка гостевого дома, и подписывала новые полотенца. Утром она открывала небольшое кафе через улицу; хлеб для гостей пекла там же. Алиса спросила, можно ли оставить записку другим гостям о свободной сушилке; Рагна показала на доску у двери. Пока Алиса писала, они поговорили о том, как трудно объяснить приезжим, что завтра здесь может быть совсем другой день. Рагна не произнесла ничего похожего на готовую цитату. Алиса не записала их разговор.","Вернувшись в комнату, Алиса попыталась написать первый абзац. Вариант с группой получился слишком удобным: все четверо будто с первого раза договорились о сушилке. Она добавила мокрые носки на полу и просьбу Рагны освободить проход. Вариант с местом тоже пришлось исправить: за окном был не «суровый север», а человек, который тащил домой пакет с продуктами и прятал от ветра бумажный чек. Собственный вариант начинался с признания, что она хотела снять с себя работу согласования, назвав частные беседы уже готовым материалом. Ни один угол не делал её спутников декорацией.","В комнате она открыла письмо ещё раз. Начало осталось прежним, но дальше появились конкретные границы: места и общие решения можно описывать; частные разговоры — только с отдельного согласия; никто не обязан давать истории убедительную развязку. Она не знала, понравится ли Марине эта версия. Решение отправить её всё же принадлежало Алисе."]},{"level":4,"title":"Выбор S21-C1 — чем открыть письмо","paragraphs":["Каждый вариант отправляется, а не остаётся бесконечным черновиком."]},{"level":5,"title":"A. Начать с людей","paragraphs":["«Марина, в этой поездке я всё чаще замечаю не тех, кто громко говорит о переменах, а тех, кто делает место другому за столом. Предлагаю серию о маленьких договорённостях в дороге. Личные эпизоды появятся только там, где человек согласится на них отдельно».","Алиса перечитала письмо и добавила один пример без имён: группа переставила сушилку, чтобы проход остался свободным. Она нажала «отправить»."]},{"level":5,"title":"B. Начать с места","paragraphs":["«Марина, Höfn запомнится мне не открыткой с гаванью, а тем, как погода меняет масштаб любого плана. Предлагаю писать о месте через решения людей внутри него: где остановиться, что отложить, что сохранить. Частные разговоры я не буду превращать в текст без согласия».","Она приложила свой короткий абзац о вечернем свете на окне кухни. Нажала «отправить», прежде чем начала править его до безличности."]},{"level":5,"title":"C. Начать с собственного решения","paragraphs":["«Марина, я поняла, что продолжаю искать для серии готовых героев, хотя сама меняю маршрут текста каждый день. Предлагаю честно включить мой выбор в материал: как журналист решает, что ему не принадлежит. Истории спутников останутся за пределами публикации, пока я не спрошу каждого».","Она увидела, что написала «мой выбор» без извинения. Письмо ушло. Экран не дал ответа немедленно, и это было нормально."]},{"level":5,"title":"Общее продолжение S21","paragraphs":["Алиса поставила телефон на зарядку, надела куртку и вышла к набережной по освещённой городской улице. Она не уходила далеко и вернулась до поздней ночи. Море почти не было видно; слышалось, как стучит оснастка на судах. В кармане она нашла чек за суп. На обороте написала: «День, в который я не стала ждать, пока кто-то выберет меня». Затем зачеркнула последнюю половину. Сегодня она не участвовала в таком соревновании.","В гостевом доме она встретила Ника с полотенцем, Эрика с термосом и Дамира с пакетом продуктов — каждый занят своим делом. Ник спросил, удалось ли ей прогуляться. Она сказала «да». Он не спросил, почему не пошла с ним. Группа оставалась группой.","Утром десятого дня пришёл ответ Марины."]},{"level":5,"title":"S21-M-A — после письма о людях","paragraphs":["«Сушилка работает как сцена, но дай мне не только согласие, а трение: кто хотел занять всю полку? Покажи абзац тем, кого можно узнать». Алиса ответила, что пришлёт версию с мокрыми носками и опущенной камерой после сверки узнаваемых строк. В блокноте появилась задача на день, а не печать одобрения."]},{"level":5,"title":"S21-M-B — после письма о месте","paragraphs":["«Вижу Höfn через окно, но пока это мог быть любой порт. Найди наблюдение, которое принадлежит именно этому дню, и не выдумывай характер города». Алиса решила пройти по улицам днём и спросить у Рагны, где она покупает хлеб для кафе, не ради готовой цитаты, а чтобы проверить собственное описание."]},{"level":5,"title":"S21-M-C — после письма о собственном решении","paragraphs":["«Твоя роль годится как вход, но читатель должен увидеть цену решения. Что именно ты убрала из черновика и чем заменила? Пришли страницу с правками». Алиса открыла историю текста, отметила пустое место после Никового признания и общую строку вместо истории туристки. Она не переслала частные записи, только собственные изменения."]},{"level":5,"title":"Переход S21","paragraphs":["Ответить Марине Алиса могла после прогулки. День только начинался. Далее — S61."]},{"level":4,"title":"Выбор S21-C2 — Что Алиса сделает с временем, которое оставила себе?","paragraphs":[]},{"level":5,"title":"A. Написать подруге о неожиданно приятном вечере","paragraphs":["Алиса отправила подруге короткое сообщение: «Оказывается, мне хорошо гулять одной в чужом городе. Расскажу после возвращения». Она не стала прикладывать фотографию — хотела сохранить вечер таким, каким его запомнила."]},{"level":5,"title":"B. Найти на завтра книжный магазин для себя","paragraphs":["На карте Алиса отметила маленький книжный в нескольких улицах от гостевого дома. В списке задач не было ни статьи, ни интервью. Она закрыла телефон и впервые за день подумала не о сроках поездки, а о том, какую книгу хотела бы увезти домой."]}]},{"id":"S61","title":"День 10. Вещь без назначения","episode":5,"source":"content/season-1-literary-episode-05.md","chunks":[{"level":0,"title":"","paragraphs":["Алиса вышла одна после завтрака. В Höfn не было нужды превращать свободный день в обход обязательных точек. Она взяла кошелёк, блокнот и тонкую шапку; телефон положила глубже в карман. У небольших магазинов и кафе были свои часы. Алиса сверила их на дверях, а не предположила, что всё обязано открыться ради её прогулки.","Она прошла вдоль улицы к маленькому продуктовому магазину, где на полках лежали хлеб, банки с джемом и шерстяные вещи местных мастерских. Перед тем как войти, Алиса обнаружила, что мысленно готовит фразу для Ника: «Тут есть хороший кадр». Она не обязана была отправлять её. Вместо этого выбрала себе булочку и села у окна соседнего кафе.","За стойкой Рагна, хозяйка гостевого дома, которую Алиса вчера видела с полотенцами на кухне, раскладывала чистые чашки. Утром Рагна работала в своём кафе через улицу и пекла хлеб для обеих кухонь. Она узнала Алису, но не стала изображать старую знакомую.","— Сегодня без группы? — спросила она.","— Сегодня я за себя.","— Тогда берите стол у окна. Оттуда удобно не торопиться.","Алиса заказала кофе. Когда женщина принесла его, Алиса попросила разрешения записать одну фразу о городе для своего блокнота. Та прочитала её черновик — о том, что здесь «все умеют ждать непогоды», — и покачала головой.","— Не все. Я, например, терпеть не могу ждать. Поэтому заранее пеку ещё хлеб.","Алиса вычеркнула своё красивое обобщение. Они поговорили о том, сколько у женщины работы в дни, когда приезжих мало. Она не спросила об имени для статьи: разговор был не интервью. Женщина вернулась к стойке, а Алиса осталась допивать кофе и думать, почему так легко приписывать незнакомым людям спокойствие, если самой хочется его найти.","В магазине она долго выбирала небольшую керамическую чашку с неровной синей глазурью. Практической нужды не было: дома у неё уже стояли чашки. Она представила, как объясняет покупку Дамиру — «слишком тяжёлая для багажа»; Нику — «на фото цвет не такой»; Эрику — «заверну в одежду». Потом поняла, что ни одному из них не нужно объяснять вещь, которую она покупает себе.","Продавщица завернула чашку в бумагу. Алиса попросила ещё лист, сама проложила его между ручкой и стенкой коробки и уложила покупку в сумку. Коробка не помещалась в боковой карман; пришлось освободить место среди записей. Дома она решит, где поставить чашку.","На обратном пути ей позвонила Марина. Алиса остановилась у стены дома, защищённой от ветра."]},{"level":5,"title":"S61-R-A — после письма о людях","paragraphs":["— В абзаце про сушилку у тебя все слишком быстро стали одной командой, — сказала Марина. — Где раздражение?","— Ник разложил свитер поперёк полок. Я попросила оставить место, он сразу убрал вещи. Вторую секцию нашёл Эрик — иначе мы бы всё равно не поместились.","— Вот это и пришли. После того как покажешь им узнаваемые строки."]},{"level":5,"title":"S61-R-B — после письма о месте","paragraphs":["— Ты нашла свой сегодняшний Höfn? — спросила Марина.","— Нашла человека, который печёт лишний хлеб, потому что не любит ждать погоды. Но это не цитата для статьи. Я перепишу место через то, что увидела сама: часы на двери кафе, мокрый чек у порога, свет над входом.","— Пришли один абзац. Без обобщений про всех местных."]},{"level":5,"title":"S61-R-C — после письма о собственном решении","paragraphs":["— Ты обещала показать цену своей правки, — сказала Марина.","— Я убрала признание Ника и историю туристки. Из-за этого первый вариант кажется короче. Вместо них написала о десяти минутах ожидания у машины. Пришлю тебе страницу с видимыми правками, без удалённых частных фраз.","— Это уже работа. Посмотрю страницу."]},{"level":5,"title":"Общее продолжение разговора","paragraphs":["Алиса убрала телефон, переставила сумку: коробка с чашкой упиралась в блокнот. На углу ветер вырвал из него листок с утренней правкой. Она догнала листок у стены кафе. Бумага промокла по краю; сохранённая строка о десяти минутах у машины осталась читаемой. Алиса решила перепечатать её до ужина, пока помнила точные слова, но сначала дошла до гостевого дома обычным шагом. Рабочий срок существовал, даже когда никто не стоял над её плечом.","У гостевого дома она услышала голоса своей группы из кухни. Можно было войти сразу и рассказать о кофе, разговоре и чашке. Можно было ещё немного пройтись одной, прежде чем вернуться к людям, которым она рада. Оба желания были её."]},{"level":4,"title":"Выбор S61-C1 — закончить самостоятельный день","paragraphs":[]},{"level":5,"title":"A. Остаться одной ещё на час","paragraphs":["Алиса написала в общий чат: «Я гуляю ещё немного, вернусь к ужину». Эрик ответил адресом гостевого дома на случай, если она забудет его в заметках; Ник прислал фотографию высохших носков; Дамир поставил короткое «хорошо».","Она дошла до скамьи у освещённой улицы, достала булочку и съела её без заметок. Потом вернулась вовремя. Ник подвинул ей стул, не спрашивая, почему она не позвала его."]},{"level":5,"title":"B. Вернуться к группе сейчас","paragraphs":["Алиса вошла на кухню и поставила бумажный свёрток рядом со своей чашкой чая.","— Что купила? — спросил Ник.","— Чашку. Себе.","— Это звучит как название фильма, который я не снял.","— И правильно.","Эрик передал ей хлеб, Дамир освободил место на столе. Алиса рассказала о замечании хозяйки кафе, не превращая женщину в персонажа их общего разговора. Они обсудили завтрашний выезд и разошлись собирать вещи."]},{"level":5,"title":"Общее продолжение S61","paragraphs":["Вечером Алиса упаковала чашку между шарфом и свитером. Она отправила Марине один абзац по выбранному углу и заметила, что для него хватило наблюдений, сделанных без чужого признания. Потом помогла группе сверить время выезда и ушла спать. Утром дня 11 — S22."]},{"level":4,"title":"Если `S21-C2=A`","paragraphs":["Утром Алиса получила от подруги ответ: «Тогда запланируем прогулку, когда вернёшься». Она улыбнулась и пошла по городу без необходимости кому-либо объяснять свой маршрут."]},{"level":4,"title":"Если `S21-C2=B`","paragraphs":["Утром Алиса дошла до книжного, который отметила на карте вчера. Он оказался маленьким, с узкой полкой подержанных изданий, и она задержалась там дольше, чем собиралась."]}]},{"id":"S22","title":"День 11. Дорога, которую нельзя обещать","episode":6,"source":"content/season-1-literary-episode-06.md","chunks":[{"level":0,"title":"","paragraphs":["Утром море было справа, потом слева, потом исчезло совсем. Дорога обогнула склон, и Алиса увидела внизу узкую полоску берега: дом, пристань и три лодки, вытащенные на траву. На карте путь выглядел прямым. За стеклом он всё время передумывал.","Ник спал, обняв рюкзак с камерой. Дамир листал на телефоне письмо и, поймав её взгляд, перевернул экран вниз. Эрик вёл машину осторожнее обычного. У развилки он притормозил: на информационном табло горела строка о закрытом участке дальше по берегу.","— Оползание грунта после дождя, — сказал Эрик. — Проезд до следующего посёлка закрыт, пока дорожная служба не осмотрит склон.","— Это до нашего ночлега? — спросила Алиса.","— Прямой путь вдоль берега идёт через этот участок. Объезд выводит к Egilsstaðir; оттуда к нашему ночлегу ведёт дорога через перевал к Seyðisfjörður. Сначала проверю, открыт ли перевал.","Ник проснулся на слове «объезд».","— Звучит как начало фильма, где все ходят по кругу и становятся лучше.","— Для начала станет позже, — сказал Дамир.","У придорожной остановки Эрик набрал номер дорожной службы. Алиса слышала, как он дважды уточнил, относится ли запрет к их машине; затем спросил о другой дороге и времени следующего обновления. Ник уже открыл маршрут на своём телефоне. Там синяя линия спокойно шла сквозь закрытый участок.","— Телефон об этом ещё не знает, — сказал Эрик. — Мы его не послушаем.","Они могли срезать только на бумаге. На деле объезд означал несколько часов в машине, отменённую встречу с хозяйкой маленькой рыбной коптильни и возможное позднее прибытие в гостевой дом в Seyðisfjörður. Марина ждала от Алисы обещанный разговор для статьи; хозяйка выделила им час между рабочими сменами. Ник рассчитывал снять разгрузку в гавани до темноты. За всеми этими маленькими обещаниями стояли чужие дни.","Эрик развернул бумажную карту на капоте. Ветер поднял её угол. Алиса придержала его ладонью и вдруг вспомнила тот день у Hveragerði, когда ветер впервые поменял их план. Тогда отмена казалась личным поражением. Теперь перед ней были имена людей, которым придётся сообщить, что их время потрачено зря."]},{"level":4,"title":"Отклик S05-C1 — выбрать ровно один фрагмент по `weatherChoice`","paragraphs":[]},{"level":5,"title":"A. Если Алиса помогла Нику (`weatherChoice=nick`)","paragraphs":["Ник прижал к карте чехол камеры.","— Ты тогда сказала снимать не потерянный вид, а то, как мы меняем план. Сегодня у меня руки заняты звонками, зато я могу написать хозяйке и предложить другое время. Сначала спрошу, хочет ли она вообще съёмку.","Алиса услышала в его словах свою прежнюю мысль, но и поправку к ней. В Hveragerði они могли потерять кадр. Здесь можно было потерять чужое согласие и чужой рабочий час.","— Напиши, что интервью для текста отдельно от камеры, — сказала она. — Пусть решит про каждое сама.","Ник показал ей набранное сообщение до отправки. Она убрала лишнее «мы очень рассчитывали»: оно звучало как просьба помочь им за счёт хозяйки."]},{"level":5,"title":"B. Если Алиса попросила Эрика объяснить перемену (`weatherChoice=erik`)","paragraphs":["— Как у Hveragerði, — сказала Алиса. — Назови две версии дня, только честно: что уже нельзя спасти?","Эрик провёл пальцем по карте.","— Встречу к полудню — нельзя. Место на дороге — тоже не наше решение. Если перевал открыт, доедем в Seyðisfjörður вечером. Если нет, ночуем ближе к Egilsstaðir и звоним хозяйке дома. Я должен был предупредить вас раньше, что этот участок после дождя уязвим.","Он сказал последнее без привычной защиты профессионала. Алиса вспомнила, как тогда услышала от него «не уверен» и поверила ему именно поэтому.","— Сейчас ты предупредил, — ответила она. — Дай мне номер хозяйки коптильни. За мой разговор отвечаю я."]},{"level":5,"title":"C. Если Алиса села с Дамиром (`weatherChoice=damir`)","paragraphs":["Дамир молча подал ей термос. Она не взяла; держала карту, пока Эрик говорил по телефону. Дамир убрал термос обратно, не обидевшись.","— Помнишь, как мы просто сидели в машине, пока остальные спорили с ветром? — спросила Алиса.","— Помню, — сказал он. — Тогда тебе нужна была пауза. Сейчас, кажется, нужна ручка.","Он достал из кармана ручку и чистый лист рецептурного блокнота. На листе Алиса записала три звонка: гостевой дом, коптильня, Марина. Дамир не стал распределять их за неё. Он только подложил блокнот под карту, чтобы страницы не уносило ветром."]},{"level":5,"title":"Общее продолжение","paragraphs":["Сначала Алиса позвонила хозяйке коптильни. Ответила женщина с запыхавшимся голосом; у неё на фоне стучали ящики.","— Мы не успеем к полудню, — сказала Алиса. — Дорога закрыта. Мне жаль, что предупредила только сейчас. Завтра утром я могла бы приехать одна, без камеры. Вам подойдёт двадцать минут? Отказ я пойму, подстраиваться под нас не прошу.","Женщина спросила, знают ли они, что завтра у неё короткая смена. Алиса не знала. Они договорились созвониться вечером: тогда хозяйка решит, сможет ли выделить двадцать минут, и не будет ждать группу у двери сегодня.","— Ты не пообещала ей материал? — уточнил Ник.","— Нет. Она не обязана компенсировать нам закрытую дорогу своей историей.","Ник на секунду посмотрел на свою камеру и убрал её в багажник.","Гостевой дом ответил сразу. Комната останется за ними, если они доедут до девяти; позже хозяйка оставит ключ в условленном месте. Эрик сверил официальное сообщение о дороге и прогноз на перевал. Проезд был открыт, но обещали туман к вечеру. Он произнёс вслух время, после которого они перестанут останавливаться ради съёмки и поедут прямо к ночлегу.","— А если время выйдет до красивого поворота? — спросил Ник.","— Тогда красивый поворот увидит кто-то другой.","Алиса позвонила Марине. Редактор начала с вопроса про интервью; Алиса сказала, что его пока нет.","— Сделай мне хотя бы начало к вечеру, — попросила Марина. — Мне нужен человек, который меняет планы, а не сводка о состоянии дороги.","Алиса посмотрела на остальных. Их лица отражались в стекле остановки, наложенные на море.","— Я напишу о выборе, который можно показать, — сказала она. — И согласую с людьми то, что касается их лично.","— Только не растворяй себя в группе.","— Не растворю.","Когда она положила трубку, выяснилось, что проблема не исчерпывается объездом. Ник, ища запасной путь, уже сообщил одному знакомому местному водителю, будто группа готова подъехать к нему ради съёмки вечером. Водитель ответил: он может выйти на воду на рассвете, если люди действительно приедут. Ник ещё не подтвердил встречу, но оставил впечатление, что решение принято.","— Я хотел спасти тебе материал, — сказал он. — И свой, если честно.","— Ты предложил чужое утро, — сказала Алиса. — И моё согласие говорить с ним.","Ник перестал искать слова для шутки.","— Да. Я напишу ему, что решение не принято, и извинюсь.","Эрик сложил карту. Ему тоже пришлось назвать своё: он обещал хозяйке ночлега время прибытия прежде, чем получил подтверждение по перевалу. Дамир предложил проверить, у всех ли есть вода и что-то съедобное на длинный отрезок; не потому, что они оказались в опасности, а потому, что ближайшее кафе могло закрыться раньше их приезда."]},{"level":4,"title":"Выбор S22-C1 — как Алиса участвует в исправлении","paragraphs":[]},{"level":5,"title":"A. Взять на себя разговоры и не обещать за других","paragraphs":["— Я отвечу Марине за текст и хозяйке коптильни за перенос, — сказала Алиса. — Ник, напиши водителю сам. Эрик, ты ведёшь и решаешь по официальной дороге. Мне не нужно, чтобы кто-нибудь говорил от моего имени ради удобного плана.","Ник набрал сообщение при ней, но не протянул телефон как экзаменационную работу. Эрик спросил, устроит ли Алису остановка у гавани, если они успеют до оговорённого часа. Она ответила, что да: разговаривать с людьми, которые не ждут интервью, она умеет и без обещаний.","Впервые за утро каждому достался свой участок работы. От этого задержка не исчезла, зато перестала быть чьей-то личной виной. Алиса открыла заметки и написала Марине: «Первый абзац пришлю сегодня вечером. Интервью перенесено; чужие слова без согласования не вставляю»."]},{"level":5,"title":"B. Сказать вслух, на кого Алиса сердится, и затем распределить работу","paragraphs":["— Меня злит не закрытие дороги, — сказала Алиса. — Меня злит, что мы снова успели пообещать чужое время, не спросив. Я тоже: я сказала Марине, что дам сцену к вечеру, прежде чем поняла, будет ли у меня право её писать.","Ник кивнул без возражений. Эрик провёл ногтем по сгибу карты.","— Значит, отменяем то, чего не можем обещать, — сказал он.","Они составили короткий список сообщений. Алиса написала Марине: «Первый абзац пришлю завтра утром; сегодня проверю, что могу рассказать без чужого согласия». Ник исправил своё приглашение водителю. Эрик уточнил прибытие в гостевом доме. Гнев оказался полезен ровно до тех пор, пока не превращался в приговор человеку."]},{"level":5,"title":"Общее продолжение","paragraphs":["Водитель ответил Нику: «Спасибо, что предупредили. Утром не смогу. Если будете в гавани сегодня, заходите просто поздороваться». Ник прочитал сообщение вслух и убрал телефон. Нового материала им никто не был должен.","Они поехали на объезд. Дамир раздал яблоки, найденные в пакете под сиденьем. Через час на возвышенности показался просвет, а под ним — фьорд, похожий на длинную складку бумаги. Алиса записала не «мы преодолели трудность», а время трёх звонков и три разных ответа. Ей хотелось запомнить, что большая поездка меняется из-за маленьких договорённостей.","К вечеру они прошли перевал от Egilsstaðir и спустились в Seyðisfjörður. У гостевого дома Ник спросил, можно ли снять, как они выгружают вещи после длинной дороги. Камеру видели все; никто не возразил против съёмки для его рабочего архива. Алиса засмеялась, когда ремень сумки зацепился за ручку чемодана. Ник снял несколько секунд и убрал камеру. Разрешения отправлять этот фрагмент продюсеру он не спрашивал.","За домами открылась рыбная гавань. Эрик спросил, хочет ли Алиса пройтись до конца причала, пока Ник и Дамир относят вещи в дом. Она захотела. После прогулки они вернулись той же улицей и успели заселиться до девяти."]},{"level":4,"title":"Выбор S22-C2 — Как Алиса предложит провести короткую остановку у фьорда?","paragraphs":[]},{"level":5,"title":"A. Пойти к воде вместе с группой","paragraphs":["Алиса предложила всем выйти на разрешённую дорожку к обзорной площадке. Ник взял камеру, но в итоге снимал только небо. Эрик подошёл к ней с двумя бумажными стаканчиками кофе, а Дамир задержался рядом, разглядывая карту."]},{"level":5,"title":"B. Остаться на несколько минут с собственными заметками","paragraphs":["Алиса попросила остальных подождать у машины и прошла к скамье с блокнотом. Она записала несколько слов о дороге, которые не собиралась отправлять редактору. Вернувшись, предложила всем выбрать следующий плейлист."]}]},{"id":"S23","title":"День 11. Гавань и чужой план","episode":6,"source":"content/season-1-literary-episode-06.md","chunks":[{"level":0,"title":"","paragraphs":["Лодки стояли низко в воде. На бетонных плитах сохли сети; чайки спорили над пустым ящиком так яростно, будто внутри ещё оставалась рыба. Эрик провёл Алису мимо склада и остановился у края, где не мешали работе. Он не рассказывал ей, как называется каждая лодка. После утра с дорогой молчание рядом с ним ощущалось новой роскошью.","— Ты звонил кому-то ещё? — спросила она.","— Своему знакомому. Он сдаёт помещение под короткие занятия для начинающих. Я хотел посмотреть его после сезона. Теперь он просит ответ до пятницы.","Алиса повернулась. Эрик всегда говорил о школе маршрутов так, словно она уже лежала на карте и нужно было только найти поворот. Сегодня у него в руке была сложенная вчетверо смета, мокрая по углам.","— Не готова школа? — спросила она.","— Не готов я объяснить, зачем она нужна человеку, который не станет проводником. Позавчера переписал программу три раза. В каждом варианте я делаю за участника самое интересное: решаю, когда ему страшно и где ему остановиться.","— А сегодня ты объяснил нам, где остановиться.","— Сегодня я отвечал за машину. Там есть граница, — сказал Эрик. — На занятиях я хочу, чтобы люди научились принимать маленькие решения сами. Я умею обещать безопасность. Труднее не обещать человеку, что он никогда не ошибётся.","После двух дней в Höfn Алиса уже знала, как внимательно Эрик складывает карту, когда не уверен в решении. Теперь он держал смету двумя пальцами, будто лист может соскользнуть в воду. Она хотела коснуться его руки, но прежде спросила:","— Ты позвал меня из-за листа? Или просто хотел побыть вдвоём?","— И то и другое, — сказал Эрик. — Про второе я боялся сказать прямо."]},{"level":4,"title":"Отклик на вечер эпизода 5 — выбрать ровно один фрагмент по `eveningState`","paragraphs":[]},{"level":5,"title":"A. После вечера с Эриком (`eveningState=eric`)","paragraphs":["— У маяка ты говорил об этом легче, — заметила Алиса.","— У маяка ты не должна была платить аренду по моим расчётам, — ответил он. — Я рад, что рассказал тебе тогда. И всё-таки сегодняшний вопрос мой, а не наше обещание после прогулки.","Она оценила эту поправку. Их прогулка к маяку осталась общей памятью, а не доводом в разговоре о его будущем. Эрик ждал, какой разговор она выберет сейчас."]},{"level":5,"title":"B. После вечера с Ником (`eveningState=nick`)","paragraphs":["— Я видел вас с Ником позавчера после бассейна, — сказал Эрик. — Не спрашиваю, что было. Просто не хочу делать вид, будто не понимаю, что у тебя есть своя жизнь вне моих чертежей.","— Есть. Но я здесь и слушаю тебя.","— Тогда этого достаточно для разговора. Мне нужен честный взгляд, не место в чьём-то расписании.","Она могла быть рядом с Ником в Höfn и идти по причалу с Эриком сегодня. Эрик не попытался превратить эту свободу в испытание."]},{"level":5,"title":"C. После вечера с Дамиром (`eveningState=damir`)","paragraphs":["— После вашего разговора с Дамиром в Höfn я не был уверен, уместно ли звать тебя одну, — сказал Эрик. — Не знаю, что вы решили, и это не моё дело.","— Мы не обязаны решать всё в один вечер. Ты хотел показать мне свой план?","— Хотел спросить о нём. Если тебе сейчас не до этого, я пойму.","Алиса осталась. Она заметила, что его осторожность не похожа на отступление: он предложил ей сказать «нет» и выдержал бы это без обиды."]},{"level":5,"title":"D. После самостоятельного вечера (`eveningState=alice`)","paragraphs":["— В Höfn ты ушла писать одна, — сказал Эрик. — Я подумал, что это мог быть самый разумный выбор из всех наших разговоров.","— Не надо хвалить меня за одиночество. Я просто хотела довести мысль до конца.","— Справедливо. Тогда и я попробую довести свою, не превращая тебя в редактора по умолчанию.","Он спрятал смету, пока Алиса сама не протянула руку. Её самостоятельность в Höfn не означала, что сегодня она должна стоять в стороне."]},{"level":5,"title":"S23-I-K — после поцелуя у гавани Höfn","paragraphs":["Эрик заметил, что Алиса смотрит на его мокрый рукав — он снова вышел без сухой куртки. Она коснулась ткани кончиками пальцев.","— Ты ведь помнишь тот вечер? — спросила она.","— Помню. Сегодня я позвал тебя не затем, чтобы получить продолжение поцелуя.","— Я знаю. Мне всё равно хотелось подойти ближе.","Он улыбнулся, но не притянул её к себе посреди работающей гавани."]},{"level":5,"title":"S23-I-S — после вечера рядом без поцелуя","paragraphs":["— Ты нашёл ту песню? — спросила Алиса.","Эрик кивнул. Сестра прислала ему название и написала, что он опять напутал слова. Он предложил включить её позже, когда они будут в машине. Алиса согласилась: у них уже была маленькая общая память, которой не требовалось объяснение."]},{"level":5,"title":"S23-I-L — после раннего возвращения","paragraphs":["— Спасибо, что тогда проводил меня домой без расспросов, — сказала Алиса.","— Я был рад прогулке. И сегодня рад, что ты пришла, хотя ты ничем мне не обязана.","Она осталась у ящика, пока он раскладывал лист, потому что её интерес к нему не исчез вместе с тем отказом."]},{"level":5,"title":"Общее продолжение","paragraphs":["Эрик развернул лист на сухой крышке ящика. Там были занятия на два часа, аренда, страховка, имена двух преподавателей. Алису удивило, что первое занятие называлось «Как сказать группе, что я хочу назад».","— Вот это оставь, — сказала она.","— Я собирался убрать. Звучит как провал маршрута.","— Звучит как право участника. А кто решит, если один хочет назад, а остальные нет?","Эрик не ответил сразу. Из склада вышли двое работников, перенося длинный ящик; им пришлось отступить, освободив проход. Эрик сдвинул бумагу, дождался, пока люди пройдут, и только потом сказал:","— Я напишу разные сценарии. Не обещание, что всем будет удобно. Способ назвать, кто за что отвечает.","Ветер поднял край листа. Алиса прижала его ладонью рядом с рукой Эрика; он посмотрел на неё и замер. Она сама убрала руку, почувствовав, как приятно было бы не убирать. Ей хотелось узнать не только о школе, но и почему он побоялся позвать её просто так.","— Ты мог обойтись без сметы, — сказала она.","— В следующий раз попробую, — ответил он. — Просто позову тебя пройтись.","— Ты покажешь мне новую версию? — спросила она.","— Только если сама захочешь. Я могу попросить другого читателя."]},{"level":4,"title":"Выбор S23-C1 — чем ответить на приглашение Эрика","paragraphs":[]},{"level":5,"title":"A. Предложить одно проверяемое действие","paragraphs":["— Я прочту первую страницу утром за завтраком, — сказала Алиса. — И отмечу места, где ты говоришь за ученика. Остальное пусть проверят те, кто будет учиться.","Эрик сложил лист пополам.","— Это лучше, чем «всё будет хорошо». Особенно если на полях будет твоё ужасное журналистское «почему».","— Я могу написать его дважды.","Алиса попросила оставить страницу ей до утра. На полях она написала два вопроса своим почерком и положила лист в блокнот, чтобы вернуть владельцу за завтраком."]},{"level":5,"title":"B. Не становиться его советником, но назвать услышанное","paragraphs":["— Я не хочу сегодня брать на себя твою программу, — сказала Алиса. — Я слышу, что ты боишься воспроизвести в классе то, с чем сам споришь. С этим стоит поговорить с будущими учениками.","Эрик некоторое время смотрел на бумагу.","— Значит, приглашу двух человек на пробный разбор, — сказал он. — Без оплаты и без показательного похода.","Он не просил её передумать. По дороге от ящика Алиса взяла его под руку. Эрик подстроил шаг и спросил, не холодно ли ей. «Немного», — ответила она. Они постояли рядом ещё минуту без нового задания для неё."]},{"level":5,"title":"Общее продолжение","paragraphs":["Когда они вернулись к машине, Ник держал в руках пакет с хлебом, а Дамир — четыре бумажных стакана. Ник спросил Эрика, выиграл ли тот спор с чайками. Эрик ответил, что чайки потребовали страховку. Алиса засмеялась раньше остальных.","Она запомнила его неловкое «хотел побыть вдвоём» сильнее, чем смету. Произнести это ему оказалось труднее, чем назвать расстояние до перевала.","Хозяйка открыла кухню и показала, где оставить мокрую обувь. У стойки Алиса выполнила обещанный звонок хозяйке коптильни. Та назвала двадцать минут завтрашнего утра и попросила приехать одной, без камеры; Алиса повторила условие и записала адрес. Ночью она написала начало статьи: «Мы не доехали туда, куда обещали. Первым делом пришлось узнать, кому именно мы это обещали»."]},{"level":4,"title":"Продолжение S22-C1 — выбрать ровно один фрагмент","paragraphs":[]},{"level":5,"title":"A. После разговора о распределении обещаний","paragraphs":["Алиса отправила первый абзац Марине вечером, как обещала. В ответ пришло: «Вижу. Завтра обсудим, но чужие слова пока не добавляй». Алиса закрыла ноутбук: первая договорённость дня была выполнена без придуманного интервью."]},{"level":5,"title":"B. После разговора о злости","paragraphs":["Алиса сохранила абзац в черновике. Марина ответила на уточнённый срок: «Завтра утром жду. Двадцать минут разговора с хозяйкой сначала проверь по записи». Алиса поставила напоминание и оставила текст до утра."]},{"level":4,"title":"Если `S22-C2=A`","paragraphs":["У причала Эрик спросил Алису, понравилась ли ей вчерашняя общая остановка у воды. Он заметил, что впервые за день никто не торопил другого обратно к машине."]},{"level":4,"title":"Если `S22-C2=B`","paragraphs":["У причала Эрик кивнул на её блокнот и спросил, удалось ли записать то, ради чего она задержалась одна. Алиса ответила, что пока оставит эти строки себе."]},{"level":4,"title":"Если `S18-C2=A`","paragraphs":["У гавани Эрик показал Алисе фотографию ещё одной дедушкиной открытки. Она узнала почерк и спросила о городе на марке: теперь их разговор продолжался без необходимости возвращаться к вчерашнему выбору."]},{"level":4,"title":"Если `S18-C2=B`","paragraphs":["У гавани Эрик напомнил Алисе про обещанную песню для дороги. Они слушали первые такты на его телефоне, пока остальные ещё собирали вещи."]}]},{"id":"S24","title":"День 12. Причал без кадра","episode":6,"source":"content/season-1-literary-episode-06.md","chunks":[{"level":0,"title":"","paragraphs":["Утро открылось видом на цветные дома по другую сторону узкой воды. Ник уже сидел на пустом причале, болтая ногами над досками. Камера лежала в закрытой сумке у его ботинок. Алиса подошла, потому что увидела рядом с ним второй стакан кофе.","— Это приглашение или ты страшно рискуешь с двумя дозами кофеина? — спросила она.","— Приглашение. Кофе — страховка на случай отказа.","Он подвинул стакан, но не коснулся её руки. На телефоне у него было письмо от продюсера: до вечера нужен короткий тизер поездки. Тот хотел увидеть «живую близость группы», особенно Алису, потому что она говорила в кадре без заготовленных фраз.","— Я не обещал им тебя, — сказал Ник. — И не пришёл спрашивать разрешения на всё, что уже снято. Я хочу сначала понять, что вообще можно им показать. Если скажешь «не сейчас», я найду другой ответ. Только не говори «да» из жалости к сроку.","Вода под причалом двигалась медленно. Алиса вспомнила руки Ника на камере у ветреной дороги и его вчерашнее сообщение водителю. Он учился не бежать впереди согласия, но письмо от продюсера могло снова сделать бег соблазнительным."]},{"level":4,"title":"Отклик на вечер эпизода 5 — выбрать ровно один фрагмент по `eveningState`","paragraphs":[]},{"level":5,"title":"A. После вечера с Эриком (`eveningState=eric`)","paragraphs":["— Ты не обязан обсуждать со мной свои письма, чтобы выяснить, что было у меня с Эриком в Höfn, — сказала Алиса.","Ник покачал головой.","— Не знаю, что было. Плохо знаю и то, что будет у меня. Письмо касается твоего лица и голоса — поэтому я здесь. Если хочешь, мы можем вернуться к нему с Эриком рядом.","Она услышала в предложении не ревность, а возможность сделать профессиональный разговор безопаснее."]},{"level":5,"title":"B. После вечера с Ником (`eveningState=nick`)","paragraphs":["— Позавчера ты убрал камеру, — сказала Алиса. — Мне было важно, что ты сделал это до того, как я попросила.","— Я помню. Поэтому и пришёл до ответа продюсеру. Наш вечер не даёт мне прав на сегодняшний тизер.","Он сказал «наш вечер» тихо, без улыбки. Между ними осталось тепло, но оно не подписывало за неё разрешение. Алиса села рядом и дождалась, пока он откроет папку с материалом."]},{"level":5,"title":"C. После вечера с Дамиром (`eveningState=damir`)","paragraphs":["— Я видела, как ты в Höfn оставил нам с Дамиром кухню, — сказала Алиса.","— Она не принадлежит мне, — ответил Ник. — Как и ваши отношения. Я зову тебя из-за письма, а ещё потому, что с тобой можно признаться: мне страшно снова сделать из человека удобный кадр.","Он не пытался быть лучше Дамира на словах. Страх был его собственным и оставался на причале между ними."]},{"level":5,"title":"D. После самостоятельного вечера (`eveningState=alice`)","paragraphs":["— В Höfn ты предпочла свою статью нашей компании, — сказал Ник. — Сегодня тебе нужна та же дистанция? Я напишу продюсеру сам.","— Тогда я предпочла закончить письмо, — поправила Алиса. — Сегодня могу посмотреть. Но моё свободное утро не превращает меня в твоего монтажёра.","— Справедливо. Монтажёр у нас дорогой и довольно нервный. То есть я.","Шутка на этот раз не скрыла просьбу. Он ждал ответа, глядя на неё, а не в экран."]},{"level":5,"title":"S24-I-K — после поцелуя у бассейна","paragraphs":["Ник коснулся края второго стакана, потом остановил руку.","— Я хотел поцеловать тебя ещё раз, — признался он. — Но сначала покажу письмо. Не хочу, чтобы одно стало платой за другое.","— Я тоже думала о поцелуе, — сказала Алиса. — Письмо всё равно посмотрю отдельно.","Он подвинул телефон, оставив стакан между ними."]},{"level":5,"title":"S24-I-H — после объятия","paragraphs":["— У тебя ещё хранится то название фильма? — спросил Ник.","— В блокноте. Оно мне нравится больше, чем твой сегодняшний рабочий заголовок.","— Мне тоже. Обнять тебя сейчас хотелось бы, но сперва я объясню письмо.","Алиса села рядом, не отвечая за весь остаток дня."]},{"level":5,"title":"S24-I-D — после просьбы пройти одной","paragraphs":["Ник поставил второй стакан на расстоянии вытянутой руки.","— Если тебе и сегодня нужно утро одной, я уйду, — сказал он.","— Сегодня я сама подошла. Расскажи, зачем звал.","Он не назвал это переменой её решения о нём; они говорили о новом приглашении."]},{"level":5,"title":"Общее продолжение","paragraphs":["Ник показал четыре коротких фрагмента без звука. Дорога за стеклом. Эрик у карты. Дамир, передающий Алисе яблоко. Алиса у гостевого дома, смеющаяся, когда ремень её сумки зацепился за чемодан. Последний фрагмент был снят вчера, когда Ник спросил разрешения на общий кадр после долгой дороги. Алиса помнила камеру и тогда не возражала. Сейчас, увидев своё лицо отдельно от того вечера, она поняла, что для письма продюсеру этого разрешения мало.","— Это удалить, — сказала Алиса.","Ник спросил, нужна ли ей полная копия для проверки, а потом при ней удалил фрагмент из рабочей папки и подборки для тизера. Он не спорил о том, что она когда-то видела камеру.","— Я спросил разрешения снимать общий день, — сказал он. — Не спросил, можно ли отправлять твоё лицо в тизере. Это моя ошибка.","— Да.","Он не попросил похвалить его за признание. Алиса сама предложила позднее обсудить, какие общие кадры вообще допустимы для показа; сейчас ей хотелось допить кофе рядом с ним.","— Что ты хочешь от меня сейчас? — спросила она.","— Посмотреть вместе оставшиеся три фрагмента. Или уйти пить кофе и разрешить мне самому сказать продюсеру, что людей я пока не показываю. Это два разных приглашения. Одно рабочее, другое — просто остаться."]},{"level":4,"title":"Выбор S24-C1 — что Алиса предлагает Нику","paragraphs":[]},{"level":5,"title":"A. Проверить материал вместе на ограниченных условиях","paragraphs":["— Давай посмотрим сегодня десять минут, — сказала Алиса. — Только то, где есть я. Согласие на просмотр не равно согласию на отправку. И Эрика с Дамиром ты спросишь отдельно.","Ник поставил таймер на десять минут и показал ей кнопку паузы.","— Ты всегда так серьёзно считаешь время? — спросила она.","— Только когда обещаю его не красть.","Они нашли фрагмент с дорогой, в котором были слышны лишь шины и дождь. Для тизера его хватило бы как начала. Но Алиса не сказала «отправляй»: это решение требовало ещё двух разговоров, и Ник принял работу на себя."]},{"level":5,"title":"B. Отказаться от совместного просмотра и остаться рядом","paragraphs":["— Сегодня я не хочу быть в твоём монтаже даже как проверяющая, — сказала Алиса. — Но кофе допью. Если ты им ответишь, что тизер будет без меня, я поверю ответу по письму, не по обещанию на причале.","Ник убрал телефон в карман.","— Отвечу до обеда. Покажу тебе только свой ответ, не новый черновик с просьбой передумать.","Они допили кофе, обсуждая, почему цветные дома напротив выглядят так, словно каждый владелец спорил с предыдущим. Ник придумал трёх воображаемых соседей; Алиса добавила четвёртую, которая просто любит жёлтый. Они смеялись без записи, и это не требовало доказательства для продюсера."]},{"level":5,"title":"Общее продолжение","paragraphs":["Ник встал первым и предложил Алисе руку, чтобы подняться с низких досок. Она оперлась на неё на короткое мгновение, пока искала ногой устойчивую доску. Ник отпустил её сразу, как только она выпрямилась.","— Есть ещё одно приглашение, — сказал он. — После поездки найти вечер без камеры. Не как обещание фильма, а как проверку, интересно ли нам говорить, когда некуда это вставить. Отвечать сейчас не надо.","Алиса увидела, чего стоило ему произнести последнюю фразу. Он привык заполнять паузы. Здесь оставил её ей.","По дороге к дому она получила подтверждение от хозяйки коптильни: договорённые двадцать минут остаются в силе, Алису ждут одну и без камеры до обеда. Алиса спросила, можно ли поговорить о том, как меняются рабочие дни, когда закрывают дорогу. Женщина ответила: «Об этом можно». История начиналась с согласованного вопроса."]},{"level":4,"title":"Если `S19-C3=A`","paragraphs":["На причале Ник вспомнил вчерашнее обещание пойти гулять без камеры. Он положил телефон в карман и несколько минут просто слушал Алису, не пытаясь придумать кадр."]},{"level":4,"title":"Если `S19-C3=B`","paragraphs":["На причале Ник спросил Алису, не жалеет ли она о выбранном наугад завтраке. Она ответила, что рада: они наконец-то нашли что-то без чужих отзывов."]}]},{"id":"S25","title":"День 12. Разговор до решения","episode":6,"source":"content/season-1-literary-episode-06.md","chunks":[{"level":0,"title":"","paragraphs":["Дамир нашёл Алису возле входа в гостевой дом, когда она записывала время встречи в блокнот. Он держал телефон так, будто только что положил трубку, хотя экран давно погас.","— У меня была беседа по работе, — сказал он. — Не экстренная. Если у тебя десять минут, я хотел сказать об этом до ответа им.","Алиса закрыла блокнот. Раньше слов «я уже решил» хватило бы, чтобы тело вспомнило старую злость. Здесь прозвучало «до». Дамир предложил пройти к боковой дорожке, где они не будут мешать входящим, и дождался её согласия.","Клиника в другой стране предложила ему собеседование на должность с долгим контрактом. Это ещё не предложение работы. Для следующего этапа ему нужно подтвердить интерес до конца недели. Он не просил Алису ехать с ним; не обещал, что останется, если она попросит.","— Я хочу пройти собеседование, — сказал он. — Пока не знаю, соглашусь ли потом. Я говорю тебе сейчас не для того, чтобы ты решила за меня. В прошлый раз я сообщил тебе о конце разговора. Сегодня это начало.","Ветер затянул капюшон Алисы на глаза. Она откинула его назад.","— Начало чего? — спросила она.","— Разговора о том, что тебе нужно знать, если мы попробуем быть близкими снова. Даже если не попробуем, я не хочу делать вид, что мой выбор не влияет на поездку.","Он не назвал вакансию судьбой. Алиса впервые увидела в нём человека, который может хотеть работу и одновременно не знать, как она изменит отношения. Желание перестало быть обвинением, но вопрос о расстоянии никуда не делся."]},{"level":4,"title":"Отклик на вечер эпизода 5 — выбрать ровно один фрагмент по `eveningState`","paragraphs":[]},{"level":5,"title":"A. После вечера с Эриком (`eveningState=eric`)","paragraphs":["— Ты видел, что в Höfn я ушла с Эриком, — сказала Алиса. — Я не хочу делать этот разговор тайной, которая будет звучать иначе потом.","— Видел, — ответил Дамир. — Не знаю, что между вами, и не прошу отчёта. Я сказал бы тебе о вакансии в любом случае. Это моя работа и моя ответственность.","Ей стало легче оттого, что он не использовал новую честность как заявку на неё. Их прошлое оставалось общим фактом, но не давало ему права спрашивать о настоящем с Эриком."]},{"level":5,"title":"B. После вечера с Ником (`eveningState=nick`)","paragraphs":["— Ты говоришь мне это после того, как я была с Ником в Höfn. Поздно выбирать момент для соревнования, — сказала Алиса.","Дамир выдержал неприятную паузу.","— Справедливо, что это выглядит так. Звонок назначили ещё утром девятого дня. Я собирался поговорить независимо от того, где ты проведёшь вечер. Могу показать письмо, но ты не обязана проверять меня документами.","— Не обязана, — повторила она. — Расскажи своими словами.","Он убрал телефон. Она осталась не потому, что поверила оправданию, а потому, что увидела готовность не делать из неё судью."]},{"level":5,"title":"C. После вечера с Дамиром (`eveningState=damir`)","paragraphs":["— Ты знал об этом в наш вечер? — спросила Алиса.","— Знал о возможности, не о приглашении на собеседование. Я должен был сказать о возможности, когда мы говорили о будущем. Побоялся превратить наш вечер в переговоры. Это не оправдание.","Она вспомнила тепло кухни и то, как легко было принять паузу за отсутствие скрытого вопроса. Если она позволила ему приблизиться, это не означало согласия ждать следующего письма в неведении.","— Сегодня мы как раз ведём переговоры, — сказала она. — И мне нужны все известные тебе обстоятельства."]},{"level":5,"title":"D. После самостоятельного вечера (`eveningState=alice`)","paragraphs":["— В Höfn я выбрала быть одна, — сказала Алиса. — Это не приглашение вернуть меня в нашу прежнюю историю через большое признание.","— Я и не хочу возвращать прежнюю, — ответил Дамир. — Могу ограничиться информацией: возможная работа, пока без решения. Больше я от тебя сейчас не жду.","Она проверила себя: любопытство было её собственным, не уступкой прошлому. Поэтому спросила, что его привлекает в этой работе, и дала ему время ответить не как бывшему, а как человеку у развилки."]},{"level":5,"title":"S25-I-K — после нового поцелуя","paragraphs":["— В Höfn я сама тебя поцеловала, — сказала Алиса. — Тогда я не знала о возможности этой работы.","— Знаю. Мне следовало назвать её до ужина.","Она отступила от стены, чтобы видеть его лицо. Желание повторить поцелуй не исчезло, но сейчас она хотела закончить разговор."]},{"level":5,"title":"S25-I-T — после чая без прикосновения","paragraphs":["— Помнишь список для нашего ужина? — спросила Алиса. — Мы оставили пропорции пустыми.","— Сегодня у меня есть одна новая строка. Я не хотел дописывать её за тебя.","Алиса поморщилась: он снова пытался укрыть неудобную новость красивой фразой. Дамир заметил это.","— Извини. Мне просто стоило сказать раньше.","Теперь она могла спросить о самой работе."]},{"level":5,"title":"S25-I-L — после раннего ухода","paragraphs":["— Я тогда ушла, потому что мне нужна была пауза, — сказала Алиса. — Не воспринимай сегодняшний разговор как разрешение вернуться к тому вечеру.","— Не воспринимаю. Я пришёл с новостью о работе. Ты можешь сейчас закончить и этот разговор.","Алиса осталась — не из вежливости, а потому, что хотела знать его нынешнюю жизнь."]},{"level":5,"title":"Общее продолжение","paragraphs":["Дамир рассказал о программе: небольшая команда, возможность вести приём и учить молодых врачей. Его волновало, хватит ли там места для пациентов, которым нельзя уделить стандартные пятнадцать минут. Он не говорил о повышении зарплаты первым, но не скрывал его, когда Алиса спросила.","— Почему ты хочешь именно этого? — спросила она.","— Мне нравится объяснять, пока человек не поймёт, что происходит. В старой клинике это считалось лишним временем. Здесь обещают считать частью работы. Я хочу проверить, правда ли.","Он говорил с неожиданной живостью. Алиса вспомнила, как он когда-то терпеливо показывал ей, почему болит лямка рюкзака, и как этой же терпеливостью иногда заменял вопрос о её желании. Хорошее качество не отменяло плохой привычки. Новая работа не доказывала, что привычка исчезла.","— А если тебя возьмут? — спросила она.","— Я сначала узнаю условия, потом решу. И сообщу тебе, когда узнаю. Тебе не нужно обещать, что это тебя устроит."]},{"level":4,"title":"Выбор S25-C1 — какую ясность просит Алиса","paragraphs":[]},{"level":5,"title":"A. Потребовать конкретного срока разговора","paragraphs":["— Если собеседование состоится, скажи мне дату, — сказала Алиса. — И давай после него отдельно поговорим о результате. Не по дороге между завтраком и выездом. Я не хочу угадывать по твоему лицу, что уже решено.","— Договорились. Напишу дату, когда её подтвердят. И спрошу, когда тебе удобно говорить.","Она заметила, что он повторил не только срок, но и право выбирать время. Небольшая вещь, которую можно будет проверить делом."]},{"level":5,"title":"B. Дать ему время без обещания ждать","paragraphs":["— Пройди собеседование, — сказала Алиса. — Я не стану сейчас строить гипотезы за тебя. Но не называй моё молчание согласием с любым исходом. Когда у тебя будут условия, приходи с ними как с новостью, а не с готовым решением о нас.","— Услышал. Я не буду просить у тебя авансом поддержку, которую ещё не заслужил.","Он выдохнул. Алиса поняла, что дать время — это тоже действие, если назвать его границу вслух."]},{"level":5,"title":"Общее продолжение","paragraphs":["У дверей их окликнул Ник: нашлась хозяйка гостевого дома, готовая подвезти Алису до коптильни на своём пути. Эрик уточнил, что обратно Алиса сможет вернуться на местном автобусе, но оставил ей решить, соглашаться ли. На мгновение все трое стояли перед ней с предложениями, и ни одно не требовало романтического ответа.","— Я поеду, — сказала Алиса. — Только возьму диктофон и спрошу разрешения на запись на месте.","Дамир придержал дверь, чтобы она достала куртку. В этот раз она позволила ему помочь; это не было обещанием начать сначала. Ник пожелал ей найти хороший вопрос. Эрик напомнил: сегодня они остаются в городе, к Egilsstaðir выезжают утром дня 13. Эти простые действия сделали группу снова целой после разговора, который мог разделить её на лагеря.","В коптильне хозяйка сначала показала, куда поставить мокрые ботинки. Потом рассказала, как в дни закрытой дороги люди звонят друг другу раньше, чем службам: не за прогнозом, а чтобы понять, кто не сможет привезти ребёнка, продукты или сменщика. Алиса спросила, можно ли записать её слова. Женщина согласилась на аудио для расшифровки, попросив прислать цитаты перед публикацией. Алиса записала это условие в начале файла вслух. После возвращения она сверила начало статьи с записью, убрала фразу, приписывавшую женщине жалость к путешественникам, и послала Марине исправленный абзац. Марина ответила: «Теперь вижу хозяйку, а не вашу задержку».","Когда она вернулась, Ник показал ей ответ продюсеру, как обещал. Он предлагал тизер без её лица и голоса; кадры с Эриком и Дамиром обещал показывать только после разговора с каждым. Дамир уже сообщил клинике, что согласен на собеседование и ждёт дату. Ни одна из этих новостей не решила жизнь Алисы. Зато каждый сделал то, что назвал."]},{"level":5,"title":"S25-E-PAGE — после чтения страницы","paragraphs":["За завтраком Алиса вернула Эрику первую страницу с двумя вопросами на полях. После её возвращения из коптильни он сказал, что возьмёт лист на пробный разговор с будущими участниками, а не попросит Алису переписывать курс. Её помощь получила продолжение, но не стала новой обязанностью."]},{"level":5,"title":"S25-E-READERS — после отказа от роли советника","paragraphs":["Эрик показал Алисе два сообщения: он предложил знакомым новичкам прочесть пробную программу и ответить, где они хотели бы остановиться. От неё он ничего не просил. Алиса спросила, волнуется ли он перед их ответом; Эрик признался, что да, и на этом разговор о школе закончился."]},{"level":4,"title":"Если `S20-C2=A`","paragraphs":["Перед разговором у гостевого дома Дамир предложил Алисе показать новый список продуктов. Она засмеялась: теперь он действительно спросил группу, а не решил за всех."]},{"level":4,"title":"Если `S20-C2=B`","paragraphs":["Перед разговором у гостевого дома Дамир заметил ту же вывеску, которую они видели на прогулке. Алиса первой улыбнулась ему: у них появилось простое новое воспоминание."]}]},{"id":"S58","title":"День 12. Кухня на четверых","episode":6,"source":"content/season-1-literary-episode-06.md","chunks":[{"level":0,"title":"","paragraphs":["После обеда дождь снова привёл их к главной улице Seyðisfjörður. Кто-то предложил искать ужин в кафе, но первое оказалось закрыто на частное мероприятие, второе открывалось слишком поздно. Хозяйка гостевого дома разрешила пользоваться общей кухней и указала на магазин, который ещё работал.","— Значит, экспедиция за продуктами, — сказал Ник. — Тот редкий жанр, где мой талант выбирать сладкое считается навыком выживания.","— За хлеб отвечает не человек, называющий шоколад крупой, — сказал Дамир.","Эрик посмотрел на часы.","— Магазин закроется через сорок минут. Если пойдём сейчас, успеем без бега.","Они прошли по улице мимо расписанных фасадов. Ручей после дождя шёл быстрее, чем утром; где-то над водой хлопнула незакрытая дверца. Алиса поймала себя на мысли, что их день можно было бы описать списком помех — дорога, перенос интервью, письмо продюсера, вакансия, закрытое кафе. Но в памяти всё настойчивее оставались ответы людей на эти помехи.","В магазине нашлись картофель, лук, морковь, банка фасоли, хлеб и небольшая упаковка сливок. Ник держал две пачки печенья с видом человека, которому поручили международные переговоры. Эрик проверял, хватит ли кастрюли на четверых. Дамир спрашивал у продавщицы, какой хлеб лучше взять к густому супу. Алиса выбирала между петрушкой и укропом, не в силах решить, что из них более похоже на их поездку."]},{"level":4,"title":"Выбор S58-C1 — с кем Алиса идёт за последним недостающим продуктом","paragraphs":[]},{"level":5,"title":"A. С Эриком за хлебом","paragraphs":["На соседней полке оставалась одна буханка. Эрик протянул к ней руку и остановился.","— Мы точно хотим эту? Я уже сегодня трижды говорил «точно» слишком рано.","— Я хочу эту, — сказала Алиса. — Она выглядит так, будто выдержит твой суп.","Он взял хлеб и положил в корзину, не превратив её фразу в разрешение на другие решения. По дороге к кассе рассказал, что когда был ребёнком, мать заставляла его покупать хлеб самому: «Нельзя учить людей дороге, если боишься спросить цену у продавца».","— А ты боялся?","— Ужасно. Сейчас иногда тоже.","Алиса впервые представила маленького Эрика, который репетирует у полки одну простую фразу. Ей стало теплее, чем от отопления магазина."]},{"level":5,"title":"B. С Ником за зеленью","paragraphs":["Ник предложил взять укроп «из уважения к супу» и петрушку «из уважения к свободе выбора».","— Один пучок, — сказала Алиса. — В кастрюле уже тесно.","Он выбрал петрушку и приложил к подбородку как бороду, но, заметив её телефон в руке, не попросил фотографию.","— Странно, — признался Ник. — Раньше я бы уже объяснял, почему это смешно в монтаже. А сейчас мне достаточно, что ты смеёшься.","— Даже если я смеюсь над тобой?","— Особенно тогда. В кино этот нюанс почему-то всегда теряется.","Он положил зелень в корзину и не попытался удержать момент экраном."]},{"level":5,"title":"C. С Дамиром за картофелем","paragraphs":["Дамир искал картофелины примерно одного размера и складывал их в пакет с профессиональной серьёзностью.","— Ты знаешь, что они всё равно попадут в одну кастрюлю? — спросила Алиса.","— Знаю. Я пытаюсь заслужить пять минут, за которые Ник не переименует блюдо в «фьорд под одеялом».","Она взяла самую неровную картофелину и положила сверху.","— Эту оставляем. У неё характер.","— Тогда чистить будешь ты.","— Согласна.","Они рассмеялись без оглядки на старые кухни. Дамир не назвал это возвращением. Он просто запомнил, какая картофелина её."]},{"level":5,"title":"D. Оставить всех у полок и выбрать продукты самой","paragraphs":["Алиса попросила остальных идти к кассе, а сама вернулась за солью: никто не проверил, есть ли она в общей кухне. Продавщица подсказала маленькую упаковку, которую можно будет оставить хозяйке дома. По дороге назад Алиса увидела на доске объявлений расписание местного любительского хора и короткую записку о сборе вещей для соседей после перекрытия дороги.","Она переписала номер не ради статьи: утром перед выездом можно будет узнать у хозяйки дома, собирают ли здесь что-то нужное и уместно ли им присоединиться. У кассы она показала записку остальным. Дамир сказал, что у него есть свободная тёплая пара носков; Ник заметил, что сперва нужно спросить, нужны ли именно они. Алиса убрала номер в карман и не стала превращать чужую беду в групповое развлечение. Возвращаться к людям без спутника оказалось не одиночеством, а её собственным способом быть внутри поездки."]},{"level":5,"title":"Общее продолжение","paragraphs":["На кухне выяснилось, что кастрюля меньше, чем представлял Эрик. Дамир предложил варить в два захода, Ник — назвать первую партию «режиссёрской версией». Алиса вытряхнула фасоль в дуршлаг и предложила сварить овощи вместе, а хлеб подать тёплым отдельно. Решение никого не обидело.","Ник резал морковь слишком толстыми кружками. Эрик показал ему один, отдал нож обратно и спросил, нужна ли помощь. Дамир очистил половину картофеля и подвинул Алисе миску с оставшимися клубнями."]},{"level":5,"title":"S58-P-C — если Алиса выбрала картофель с Дамиром","paragraphs":["Сверху лежала та самая неровная картофелина. «Договор остаётся в силе?» — спросил Дамир. Алиса взяла нож и разрезала её пополам. Он не стал подсказывать, как удобнее чистить каждую половину."]},{"level":5,"title":"S58-P-OTHER — если Алиса выбрала Эрика, Ника или самостоятельную покупку","paragraphs":["Алиса взяла два небольших клубня, Дамир — самый крупный. Ник предложил поменяться, чтобы никому не досталась вся трудная работа, и они действительно поменялись. Пока чистили, никто не руководил остальными из-за стола."]},{"level":5,"title":"Общее продолжение S58","paragraphs":["На мокром окне дрожали отражения четырёх человек, то близко, то далеко в зависимости от того, кто подходил к плите.","Когда суп начал тихо кипеть, хозяйка дома заглянула узнать, не нужен ли им ещё стул. Услышав историю с закрытым кафе, она принесла маленькую банку горчицы и сказала, что так ужин будет менее похож на наказание погодой. Они предложили ей попробовать позже. Она сказала, что сначала закончит убирать комнаты, и оставила им четыре дополнительные ложки «на случай, если вы опять пригласите половину города».","За столом Ник действительно пролил сливки на угол карты. На этот раз Эрик засмеялся так громко, что сам удивился. Ник застыл с салфеткой.","— Я приготовился к лекции о сохранности маршрута.","— Маршрут уже был закрыт, — сказал Эрик. — Теперь хотя бы открыт соус.","Дамир перевернул карту сухой стороной вверх. Алиса сказала, что сливки не стоили такой удачной шутки, и все снова засмеялись. Суп получился гуще, чем планировалось, зато его хватило и на вторую тарелку каждому.","Разговор перескакивал. Ник признался, что из сорока часов прежнего фильма оставил семь минут и долго считал их доказательством провала. Дамир рассказал о пациентке, которая однажды научила его объяснять процедуру без привычных врачебных слов. Эрик вспомнил своё первое самостоятельное занятие, где человек в конце спросил, можно ли было просто не подниматься на холм. Алиса описала хозяйку коптильни, чьё «об этом можно» оказалось важнее десятка эффектных цитат.","— Как ты это назовёшь в статье? — спросил Ник.","— Пока не знаю. Но я хочу, чтобы там были люди, которые вправе поправить меня.","Ник поднял ложку, будто предлагая тост. Дамир сказал, что это ужасный предмет для тоста. Эрик всё же стукнулся своей ложкой о ложку Алисы. Звук получился почти неслышным.","Потом они менялись местами: Ник пересел к розетке проверить, дошёл ли его ответ продюсеру; Дамир уступил хозяйке стул, когда она всё-таки зашла попробовать суп; Эрик подошёл к окну проверить погоду. Алиса осталась у стола и увидела каждого отдельно, но не как три возможных ответа на один вопрос. У каждого было своё дело завтра, даже если её рядом не будет.","Перед сном она вышла на улицу. Между домами пахло дождём и ужином. Эрик сказал, что завтра впервые за долгое время хотел бы пройтись без карты; Ник вернулся к разговору о вечере без камеры, но не попросил немедленного ответа; Дамир ждал дату собеседования. Ни один не требовал решения этой минутой. И всё же Алиса уже знала: если она будет делать вид, что ничего не выбирает, это тоже затронет других."]}]},{"id":"S26","title":"День 12. Назвать своё направление","episode":6,"source":"content/season-1-literary-episode-06.md","chunks":[{"level":0,"title":"","paragraphs":["Они собирались уехать утром к Egilsstaðir. В гостевом доме погас свет на кухне; в коридоре горела только лампа над входом. Алиса вернулась за блокнотом и нашла его на подоконнике, рядом с бумажной картой, на которой высохло сливочное пятно.","Она перечитала свой первый абзац и дописала: «Закрытая дорога не сказала нам, кого любить. Она заставила спросить, кто имеет право решать за другого». Формулировка показалась слишком ровной для того, как неровно билось сердце. Алиса вычеркнула её. Статья могла подождать до утра. Разговор, который она откладывала под видом работы, — нет.","Она вышла во двор. Трое мужчин оставались поблизости: Эрик укладывал карту в машину, Ник пил воду у ступеней, Дамир возвращал хозяйке пустую кастрюлю. Каждый мог выслушать честный ответ. Никто не мог вынести его вместо неё. Вечер в Höfn не заключил за Алису договор; сегодняшний ужин тоже. Она решала, с кем хочет продолжить близость после этой поездки — или хочет ли сейчас выбирать отношения вообще."]},{"level":4,"title":"Выбор S26-C1 — сознательное намерение. Ровно один исход","paragraphs":[]},{"level":5,"title":"A. Выбрать Эрика (`routeIntent=eric`)","paragraphs":["Алиса подошла к машине. Эрик закрыл багажник и не двинулся навстречу, пока она не сказала:","— Я хочу продолжить разговор, который начался не у твоей карты, а там, где ты позволил мне с ней не согласиться. Мне хочется попробовать быть с тобой. Без обещания переехать и без роли человека, который исправит твою школу.","Эрик опустил руку с ключами.","— Я хочу того же. И мне придётся учиться спрашивать, когда я привык действовать быстро.","— Мне придётся говорить «нет» сразу, а не ждать, пока рассержусь.","Они договорились о ближайшем: завтра на приозёрной тропе в Egilsstaðir Алиса расскажет, какой участок хочет пройти сама. Эрик будет рядом, но не поведёт её без просьбы. Это не звучало как обещание на всю жизнь. Этим оно было честнее."]},{"level":6,"title":"S26-E-N — ранее вечер с Ником","paragraphs":["Алиса нашла Ника возле ступеней, прежде чем он увидел её рядом с Эриком в машине.","— Тот вечер в бассейне был мне дорог. Сегодня я решила попробовать отношения с Эриком. Я хотела сказать тебе сама.","Ник посмотрел на свою бутылку, потом убрал её в карман куртки.","— Мне нужна минута, — сказал он. — Завтра я всё равно еду с вами. Давай просто не заставлять меня шутить за завтраком.","— Не буду."]},{"level":6,"title":"S26-E-D — ранее вечер с Дамиром","paragraphs":["Дамир задержался у входа, когда Алиса позвала его. Она рассказала о своём выборе, не пересказывая Эриковы слова и не оправдывая их кухонный вечер.","— Мне больно, — ответил Дамир. — Я рад, что ты сказала прямо. Завтра я останусь в группе; сегодня хочу побыть один.","Алиса не остановила его вопросом о прошлом. Он ушёл в дом, придерживая дверь для выходившей хозяйки."]},{"level":6,"title":"S26-E-E — ранее вечер с Эриком","paragraphs":["Эрик заметил, что Алиса смотрит на его руку с ключами, и положил ключи на крышу машины. Они оба помнили гавань в Höfn; она сказала, что сегодняшний ответ относится не только к тому вечеру. Эрик кивнул: он хотел того же."]},{"level":6,"title":"S26-E-A — ранее самостоятельный вечер","paragraphs":["Алиса вспомнила свою прогулку по Höfn и покупку чашки. Она пришла к Эрику сегодня по собственному желанию, а не потому, что одиночный вечер оказался ошибкой. Она сказала ему это, и он не попросил её объяснять выбор дальше."]},{"level":5,"title":"Общее продолжение исхода «Эрик»","paragraphs":["Эрик спросил: «Можно обнять тебя?» Алиса шагнула ближе и сказала: «Сейчас можно». Он обнял её без той крепости, с какой обычно удерживал разлетающуюся карту. Когда она отступила, отпустил сразу. У двери они остановились, услышав, как Ник ищет свою кружку, и вернулись в общую жизнь с новым намерением, которое предстояло подтвердить поступками."]},{"level":5,"title":"B. Выбрать Ника (`routeIntent=nick`)","paragraphs":["Ник стоял у ступеней и пытался закрыть бутылку одной рукой. Алиса взяла её у него, закрутила крышку и вернула.","— Я хочу увидеть тот вечер без камеры, о котором ты спросил, — сказала она. — И не только вечер. Мне интересно, как мы будем рядом, когда нечего спасать монтажом. Я хочу попробовать отношения с тобой, если ты тоже хочешь — без договора, что моя жизнь станет твоим фильмом.","Ник открыл рот для шутки, закрыл и кивнул.","— Хочу. И мне страшно, что я опять окажусь интересным только пока куда-то еду. Не прошу тебя это опровергать. Просто говорю заранее.","— Тогда завтра, когда мне потребуется тишина для текста, ты дашь её мне. А я скажу, когда смогу прийти.","— Это уже похоже на вечер без камеры, только более трудный."]},{"level":6,"title":"S26-N-E — ранее вечер с Эриком","paragraphs":["Алиса нашла Эрика у машины и сказала, что их прогулка в Höfn ей понравилась, но теперь она хочет попробовать отношения с Ником. Эрик долго смотрел на сложенную карту.","— Я надеялся на другое, — сказал он. — Страницу программы я попрошу прочесть кого-нибудь ещё. Не сегодня.","— Хорошо. Мне жаль, что это больно.","Он кивнул и вернулся к дверце багажника. Алиса не требовала от него лёгкости, которой сама бы не почувствовала."]},{"level":6,"title":"S26-N-D — ранее вечер с Дамиром","paragraphs":["Дамир выслушал её у входа в дом. Алиса назвала их ужин настоящим, но сказала, что сейчас хочет быть с Ником. Дамир прислонился к перилам и помолчал.","— Мне понадобится время привыкнуть, — сказал он. — О собеседовании я сообщил тебе не ради этого ответа. И завтра не стану забирать свои слова.","Она поблагодарила его. Он пропустил её в дом первой, но сам остался на воздухе."]},{"level":6,"title":"S26-N-N — ранее вечер с Ником","paragraphs":["Ник вспомнил бассейн и, впервые за вечер, улыбнулся без попытки развеселить Алису. Она сказала, что выбирает его сейчас не из-за одного удачного свидания; он ответил, что тоже хочет увидеть, какими они будут в обычный день."]},{"level":6,"title":"S26-N-A — ранее самостоятельный вечер","paragraphs":["Алиса достала из кармана чек из Höfn: она всё ещё собиралась сохранить его для себя. Нику она сказала, что может хотеть собственной прогулки и отношений с ним одновременно. Ник спросил, как выглядит прогулка, в которую его пригласят. «Я сама сообщу», — ответила она, и он согласился ждать приглашения, не снимая ожидание."]},{"level":5,"title":"Общее продолжение исхода «Ник»","paragraphs":["Ник протянул ладонь вверх. Алиса положила на неё свою, и Ник тихо сказал: «Вот этого я не стану снимать». Она ответила: «Лучше запомни». Через минуту он отпустил её руку, чтобы взять две кружки. Они вместе занесли их на кухню; утром им предстояло разговаривать с остальными как членам той же группы, а не прятаться за кадром."]},{"level":5,"title":"C. Выбрать Дамира (`routeIntent=damir`)","paragraphs":["Дамир вышел от хозяйки с пустыми руками. Алиса дождалась, пока он остановится у ступеней.","— Я не хочу возвращаться туда, где мы закончили, — сказала она. — Я хочу попробовать начать с сегодняшнего дня. Я выбираю тебя, если ты готов не решать за нас двоих, даже когда уверен, что так удобнее.","— Готов пробовать, — сказал он. — Но я не стану обещать, что никогда не сорвусь в старую привычку. Могу обещать замечать и исправлять её, когда ты назовёшь. И не скрывать письма, чтобы сохранить хороший вечер.","— Мне нужен не идеальный ответ, а разговор до решения.","Они условились, что после собеседования вернутся к вопросу о расстоянии без предварительных уступок. Завтра, на дороге к Egilsstaðir, они не будут воспроизводить знакомый маршрут пары перед всей группой. Начнут с простого: сядут рядом, если оба захотят, и спросят об этом утром."]},{"level":6,"title":"S26-D-E — ранее вечер с Эриком","paragraphs":["Алиса остановила Эрика возле машины и рассказала о решении. Она не назвала прогулку в Höfn ошибкой. Он ответил после паузы:","— Мне нужно немного времени. Сегодня давай не будем говорить о школе.","— Договорились.","Она вернулась к дому, не пытаясь утешить его близостью, на которую только что отказалась согласиться."]},{"level":6,"title":"S26-D-N — ранее вечер с Ником","paragraphs":["— Я не забираю обратно наш вечер, — сказала Алиса Нику. — Но сейчас я хочу попробовать отношения с Дамиром.","Ник отвёл взгляд к гавани.","— Я понял. Только не проси меня сегодня сделать вид, что мне совсем не грустно.","— Не попрошу."]},{"level":6,"title":"S26-D-D — ранее вечер с Дамиром","paragraphs":["Дамир вспомнил их новую кухню в Höfn; Алиса сказала, что выбирает не воспоминание о ней, а возможность продолжать узнавать его сегодняшнего. Он не стал отвечать обещанием, что теперь всё будет иначе. Вместо этого спросил, когда она захочет поговорить после собеседования."]},{"level":6,"title":"S26-D-A — ранее самостоятельный вечер","paragraphs":["Алиса думала о чашке, купленной для себя в Höfn. То, что она провела там день одна, не делало выбор Дамира уступкой. Она сказала ему, что не собирается отдавать свою работу или поездки в обмен на близость. «Я и не прошу», — ответил он; проверить это предстояло позже."]},{"level":5,"title":"Общее продолжение исхода «Дамир»","paragraphs":["Дамир спросил, можно ли обнять её. Алиса сказала: «Пока нет. Давай начнём с того, о чём договорились». Он кивнул, не превращая её отказ в испытание и не пряча радость от её слов. Позже она открыла блокнот и рядом с временем собеседования написала собственную будущую встречу с Мариной: её работа оставалась её работой и в выбранной близости."]},{"level":5,"title":"D. Выбрать Алису (`routeIntent=alice`)","paragraphs":["Алиса не стала ждать, пока кто-то спросит первым. Она собрала троих на кухне, где ещё пахло супом, и сказала:","— Мне было важно быть с каждым из вас в этой поездке. Я хочу продолжить её как журналист и как ваш друг. Романтических отношений сейчас не выбираю. Это моё решение, а не просьба кому-то доказать, что я ошиблась.","Ник поставил кружку на стол. Эрик кивнул, проверяя, верно ли услышал. Дамир посмотрел на неё так, будто хотел задать личный вопрос, но удержался: разговор был общим и не требовал отчёта о прошлом."]},{"level":6,"title":"S26-A-E — ранее вечер с Эриком","paragraphs":["Позже, когда остальные разошлись, Алиса сказала Эрику, что прогулка к маяку не была обманом: тогда ей хотелось быть рядом, но сейчас она не выбирает пару. Он опёрся на дверной косяк.","— Я огорчён, — сказал он. — И не хочу делать вид, что легко. Но ты не должна была знать ответ в Höfn.","Она оставила ему возможность уйти первым. Он воспользовался ею."]},{"level":6,"title":"S26-A-N — ранее вечер с Ником","paragraphs":["Ник остановился у раковины, когда Алиса попросила минуту. Она сказала, что вечер без камеры останется её памятью, но она не выбирает отношений. Он открыл кран, потом закрыл его, так и не вымыв кружку.","— Я понял, — сказал он. — Мне нравилось надеяться. Завтра, наверное, буду тише обычного.","— Это можно."]},{"level":6,"title":"S26-A-D — ранее вечер с Дамиром","paragraphs":["Алиса сказала Дамиру, что новый ужин не отменил её желания идти дальше самостоятельно. Он поблагодарил за прямой ответ и не стал просить пересмотреть его из-за общего прошлого. На кухне они поставили чашки рядом, но разошлись по разным комнатам."]},{"level":6,"title":"S26-A-A — ранее самостоятельный вечер","paragraphs":["Алиса вспомнила, как гуляла одна по Höfn, пока остальные занимались своими делами. Сегодняшний ответ не был продолжением того вечера по инерции: она прислушалась к себе после каждого разговора и всё равно хотела оставить этот маршрут за собой."]},{"level":5,"title":"Общее продолжение исхода «Алиса»","paragraphs":["— А завтра? — спросил Ник уже за столом. — Вместе едем?","— Вместе, — ответила Алиса. — Мне нужна ваша помощь с дорогой и ваше право не участвовать в статье. Я хочу дописать её так, чтобы место было не фоном для моего выбора.","Эрик предложил показать ей приозёрную тропу, не сопровождая как гид, если она захочет идти одна. Дамир спросил, можно ли оставить ей копию расписания на утро. Ник предложил не снимать её, пока она работает. Они не торопились доказать, что всем уже легко. Алиса вымыла четыре кружки и забрала блокнот с подоконника. Впереди была поездка, которую она выбирала сама."]}]},{"id":"S27","title":"День 13. Берег, который не попал в кадр","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Наутро Эрик сказал, что до следующего ночлега меньше трёх часов, и Ник сразу предложил снять по дороге три места. Потом Эрик показал ему сообщение от Инги: вчера на приозёрной тропе размыло настил, местные добровольцы собирались заменить две доски, собрать вынесенный ветром мусор и разобрать старые крепления. Для приезжих была работа — не героическая, просто нужная. Если группа хотела присоединиться, следовало приехать до десяти и слушать инструкции.","— Ты уверен, что мы не будем мешать? — спросила Алиса.","— Я уточнил. Инга ответила: четыре пары перчаток есть, фотографировать лица без просьбы не стоит, а пилу нам в руки никто не даст.","Инга ждала у начала тропы в красной шапке. Она не рассказывала гостям, как важно беречь природу. Просто вручила им мешки, показала, где ходить нельзя, и попросила не трогать сложенные для ремонта доски. Ник попробовал поднять мешок одной рукой и обнаружил, что там не пустые бутылки, а намокшая верёвка. Дамир подхватил второй конец. Эрик ушёл с Ингой за инструментами. Алиса нашла под кустом потерянную детскую рукавицу, стряхнула грязь и положила её в отдельный пакет.","В середине работы они разошлись вдоль кромки тропы. Алиса на секунду осталась одна. Озеро почти не было видно: между ней и водой стояли мокрые невысокие деревья. Зато она слышала смех Ника, когда верёвка снова зацепилась за корень, и короткое «сюда» Дамира. Она приехала написать о красивой стране; полдня ей пришлось смотреть себе под ноги.","Инга остановилась рядом, оценила два собранных мешка и предложила сделать перерыв. Ник поднял камеру, но не включил её.","— Я могу снять доски и наши руки? — спросил он. — Без лиц местных, если они не хотят.","— Попроси сначала Ингу, — ответила Алиса. — И покажи ей потом, что получилось.","Инга согласилась на один общий план тропы, но попросила не превращать ремонт в историю о том, как туристы приехали кого-то спасать. Ник опустил объектив ниже. В кадре оказались четыре пары грязных перчаток и старая доска, которую местные добровольцы унесли мимо них.","Алиса вспомнила редакторское письмо: Марина просила заметный сюжетный поворот. Здесь не было поворота. Был человек, который ещё вчера увидел, что доска разболталась, и сегодня пришёл её заменить. Она сделала запись, не называя Ингу героиней."]},{"level":4,"title":"Выбор S27-C1 — как Алиса проведёт последний час работы","paragraphs":[]},{"level":5,"title":"A. Остаться с Ингой и закончить настил","paragraphs":["Алиса подала Инге крепления и слушала, как та объясняет, почему эту доску нельзя класть ровно на землю. Она записала несколько точных слов об устройстве тропы и спросила, можно ли использовать их в статье. Инга исправила название местности в заметках и улыбнулась, увидев написанное правильно."]},{"level":5,"title":"B. Помочь Нику со съёмкой, не мешая работе","paragraphs":["Ник доверил Алисе держать штатив, пока сам перетаскивал доски. Она выбрала точку, где камера не закрывала проход. Получился короткий неподвижный кадр: сначала пустая тропа, потом по ней идут люди с тяжёлой доской, и снова пустая тропа. Ник посмотрел и ничего не стал комментировать."]},{"level":5,"title":"C. Отнести полные мешки и вернуться за остальными","paragraphs":["Алиса отнесла мешки к машине координатора, сверила, что в них не попали чужие инструменты, и принесла всем воду. Это была не самая заметная работа, зато она успела застать момент, когда Дамир незаметно сменил перчатку: старая порвалась по шву. Алиса молча передала ему запасную."]},{"level":5,"title":"Общее продолжение","paragraphs":["Перед отъездом Инга сфотографировала готовый участок на свой телефон, чтобы отправить отчёт тем, кто не смог приехать. Четверых путешественников она попросила постоять в стороне: на снимке должны были быть доски, а не они. Ник первым отошёл с тропы.","На обратной дороге к гостевому дому Эрик спросил, хотят ли они завтра остановиться у Mývatn подольше. Ник ответил, что готов смотреть куда угодно, лишь бы не тащить мокрую верёвку. Дамир уснул, прижав ладонь к тёплому стаканчику. Алиса не стала будить его, хотя хотела показать снимок детской рукавицы: хозяйка гостевого дома обещала спросить у соседей, не потерял ли её кто-нибудь."]}]},{"id":"S59","title":"День 13. Самая плохая песня","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Бутерброды расползались в бумаге. Эрик разложил их на крышке пластикового контейнера, Дамир выдал каждому сухую салфетку, Ник отказался от последней и через минуту попросил две. У Алисы всё ещё пахли руки мокрой древесиной, хотя она вымыла их в гостевом доме.","— Выбираем песню для дороги, — объявил Ник, когда они доели. — Не самую любимую. Ту, от которой у водителя начнёт дёргаться глаз.","— Тогда водитель лишит нас музыкальных прав, — сказал Эрик.","— У нас есть демократия.","— И водитель с ключами.","Дамир предложил старую мелодию, которую все, кроме Эрика, знали с детства. Алиса поймала себя на том, что готова подсказать ему слова. В другой поездке это было бы так естественно, что она даже не заметила бы. Здесь она не стала угадывать, какой вечер им теперь положен после её решения. Она просто пропела первую строчку; Дамир продолжил, немного фальшивя.","Ник выбрал рекламу шампуня, застрявшую у него в голове после аэропорта. Эрик, к общему удивлению, напел совершенно серьёзную детскую считалку, которую помнил от сестры. Когда остальные рассмеялись, он пожал плечами и доел бутерброд."]},{"level":4,"title":"Выбор S59-C1 — чью песню Алиса ставит в машине","paragraphs":[]},{"level":5,"title":"A. Детскую считалку Эрика","paragraphs":["Эрик прослушал вступление, постучал пальцами по рулю и заметил, что в песне не хватает одного куплета. Ник пытался выведать его всю дорогу. Эрик не поддался."]},{"level":5,"title":"B. Неудачную рекламную мелодию Ника","paragraphs":["Ник включил её всего на сорок секунд, но этого хватило: через полчаса Дамир тихо насвистывал припев, даже не замечая. Алиса засмеялась, когда он сам это услышал."]},{"level":5,"title":"C. Песню из детства Алисы и Дамира","paragraphs":["Дамир сначала смотрел в окно. На втором куплете он подпел, но не потянулся за её рукой. Алиса была рада этому: у воспоминания хватало места, чтобы просто остаться воспоминанием."]},{"level":5,"title":"Общее продолжение","paragraphs":["Вечером Инга прислала фотографию починенного настила. Ник предложил распечатать её и наклеить на бок машины. Эрик ответил, что сначала надо спросить владельца машины. Алиса сохранила снимок в папке статьи и отдельную копию — себе. Иногда день запоминался не тем, что с ними произошло, а тем, что они успели сделать вместе."]}]},{"id":"S28","title":"День 14. Не туда, куда указал палец","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Эрик попросил Алису идти впереди на коротком размеченном участке. Не ради урока: его телефон разрядился до восьми процентов, а бумажную карту он оставил в машине, решив не брать на прогулку лишнего. На развилке стоял указатель с двумя стрелками и перечёркнутый знак для закрытой тропы. Алиса выбрала открытую дорожку к обзорной площадке. Эрик не поправил её, хотя прежде обязательно объяснил бы, почему второй путь чуть короче.","— Ты специально молчишь? — спросила она.","— Да. Но если мы пропустим поворот к машине, скажу.","У площадки ветер опрокинул её капюшон. Эрик поймал край куртки, прежде чем ткань закрыла Алисе глаза. Он не потянул её назад; просто придержал воротник, пока она застёгивала молнию. Под ними лежало озеро, тусклое под серым небом. Никакой вид не делал день торжественным. Они оба были после вчерашней работы голодны, у Алисы промок носок, а Эрик безуспешно пытался вспомнить, где оставил запасные батарейки.","— Я хотела спросить тебя о завтраке, — сказала Алиса.","— Опасная тема после прогулки.","— Ты каждый раз ешь стоя, пока остальные собираются. Можно завтра просто сесть с нами?","Он удивился сильнее, чем если бы она предложила изменить маршрут. Оказалось, за несколько лет работы он привык приходить первым и проверять, завели ли машину, заказаны ли продукты, есть ли горячая вода. По выходным сестра звала его на завтрак, но он всё равно вставал раньше остальных и мыл за ними посуду, пока они ещё ели.","— Тогда завтра я мою чашки, — предложила Алиса.","— Нет. Завтра я сначала ем.","Она рассмеялась и запомнила его обещание. Оно было маленьким, и оттого ей захотелось узнать, сможет ли он его выполнить."]},{"level":4,"title":"Выбор S28-C1 — на обратной развилке","paragraphs":[]},{"level":5,"title":"A. Попросить Эрика показать более спокойную дорогу","paragraphs":["— На обратном пути поведёшь? Я устала следить за табличками.","Он достал карту из кармана — маленькую, сложенную вчетверо; бумажную карту он всё-таки взял. Алиса выразительно посмотрела на него. Эрик признал, что не способен уйти без запасного плана, и дал ей карту самой выбрать удобную дорожку."]},{"level":5,"title":"B. Предложить ему идти рядом и не выбирать лидера","paragraphs":["Они пошли рядом. У развилки Алиса прочла указатель вслух; Эрик увидел тропу и сказал, что она ведёт к парковке. Решение заняло десять секунд, и оба остались довольны. На обратном пути они обсудили не маршрут, а то, какую музыку Эрик терпеть не может на семейных праздниках."]},{"level":5,"title":"Общее продолжение","paragraphs":["У машины Эрик достал из багажника сухие носки — свои, слишком большие для Алисы. Она всё равно надела их. Вечером он вспомнил об этом, когда группа собралась выбрать, куда пойти после ужина. И впервые спросил не «успеем ли», а «хочешь ли ты». Алиса ответила, что хочет. Не потому, что они успевали."]},{"level":4,"title":"Выбор S28-C2 — Что Алиса предложит Эрику на вечер после возвращения?","paragraphs":[]},{"level":5,"title":"A. Поставить ту самую песню и пригласить его на танец","paragraphs":["— Даже если здесь нет зала, — сказала Алиса. Эрик посмотрел на её протянутую ладонь, потом на ботинки, испачканные после тропы, и согласился. Они сделали два шага у машины и оба рассмеялись."]},{"level":5,"title":"B. Провести вместе тихий вечер без планов","paragraphs":["— Мне хочется просто посидеть рядом с тобой, — сказала Алиса. Эрик не стал доставать карту. Он спросил, взять ли им чай в гостевом доме. Она ответила, что чай можно, а расписание — нет."]}]},{"id":"S49","title":"День 14. Танец, для которого не нужен повод","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["В зале пахло шерстяными куртками и крепким кофе. Кто-то поставил старую пластинку, и двое пожилых гостей вышли танцевать между столами. Алиса шла за стаканом воды, когда Эрик протянул ей руку. В этот раз не после личного признания, как у гавани в Höfn, а просто потому, что он услышал музыку и захотел танцевать.","— Ты ведь говорил, что танцуешь плохо, — напомнила она.","— Сегодня у меня новый партнёр. Возможно, проблема была в прежнем.","— У тебя была партнёрша до меня?","— Сестра в детстве. Она до сих пор уверена, что я наступил ей на ногу нарочно.","Они не вышли на середину зала. Танцевали рядом с окном, чтобы никому не мешать. Эрик помнил шаг лучше, чем показывал в Höfn, но на повороте едва не задел стул. Алиса успела придержать спинку и рассмеялась. Он взглянул на её руку, затем на лицо — и рассмеялся тоже.","Когда музыка закончилась, он не отпустил её сразу. Алиса почувствовала тепло его ладони сквозь прохладный воздух зала. Это не было обещанием. Просто не хотелось расходиться прямо сейчас."]},{"level":4,"title":"Выбор S49-C1 — что делает Алиса","paragraphs":[]},{"level":5,"title":"A. Пригласить Эрика на второй танец","paragraphs":["— Один раз не считается. Я хочу проверить, действительно ли ты умеешь.","Эрик попросил хозяина поставить другую пластинку. Ник из дверей заметил их и тут же повернулся к стойке за кофе, будто увидел что-то личное. Эрик не сделал вид, что не заметил его. Он только подошёл к Алисе ближе, когда заиграла музыка."]},{"level":5,"title":"B. Предложить выйти к озеру вдвоём","paragraphs":["На улице было слишком холодно для долгого разговора. Они дошли до тёмного берега, посмотрели на отражение единственного фонаря и вернулись через пять минут. Эрик предложил следующий танец завтра, если Алиса всё ещё захочет. Она ответила, что может захотеть и без назначенной даты."]},{"level":5,"title":"Общее продолжение","paragraphs":["Позднее у лестницы он вручил Алисе её шарф, который она оставила в зале. Шарф пах кофе и дымом от печки. Эрик не сказал ничего необычного: пожелал ей спокойной ночи и пошёл к своей комнате. Алиса задержалась на площадке, потому что улыбка не исчезала так быстро, как ей хотелось."]},{"level":4,"title":"Если `S28-C2=A`","paragraphs":["Вечером Алиса первой узнала знакомую мелодию и протянула Эрику руку. Он не удивился: она уже приглашала его танцевать после тропы, и им обоим было легче начать снова."]},{"level":4,"title":"Если `S28-C2=B`","paragraphs":["Вечером Эрик предложил Алисе сесть у окна, прежде чем началась музыка. Их тихий час после тропы остался у неё в памяти не менее ясно, чем первый танец."]}]},{"id":"S29","title":"День 14. Удалить, оставить, переснять","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Ник показал Алисе короткий фрагмент из первого дня поездки. На экране она стояла рядом с чужим чемоданом и смотрела в сторону Дамира, ещё не поверив, что это он. Тогда Ник обещал не использовать этот кадр без её решения. Сейчас он открыл монтажную папку и положил телефон между ними, как кладут предмет, который принадлежит обоим.","— Здесь есть хорошая пауза перед тем, как ты его увидела, — сказал он. — Но она не моя. Я не хочу, чтобы ты потом узнала о ней из тизера.","Алиса просмотрела фрагмент дважды. На втором просмотре она заметила, что камера сняла ещё и его собственное лицо в отражении окна автобуса: Ник тоже выглядел растерянным. В первый день она думала, что он способен превратить в шутку любое событие. Сейчас он не пытался развеселить её.","— А ты сохранишь копию себе? — спросила она.","— Если скажешь удалить — нет. Мне не нужно объяснение.","Он протянул телефон. Алиса могла не принимать решение за весь фильм; только за конкретные сорок секунд, в которых её жизнь случайно оказалась частью чужой работы."]},{"level":4,"title":"Выбор S29-C1 — что делать с кадром","paragraphs":[]},{"level":5,"title":"A. Удалить его из фильма и исходников","paragraphs":["Ник открыл исходную папку и удалил фрагмент при ней. Потом показал пустое место на временной шкале. Неловкость не исчезла сразу: Алиса всё ещё помнила, как выглядела на экране. Ник предложил вместо этого снять руки группы после вчерашней работы — кадр, за который им не придётся объясняться друг перед другом."]},{"level":5,"title":"B. Оставить фрагмент только в личном архиве Алисы","paragraphs":["Ник передал ей исходник, а из своего монтажа убрал кадр. Алиса не знала, сохранит ли его надолго. Ей было важно, что решение об этом не принадлежит человеку с камерой только потому, что он нажал кнопку первым."]},{"level":5,"title":"C. Переснять начало поездки сейчас, с её участием","paragraphs":["Они поставили камеру на скамью, и Алиса попыталась произнести первую фразу своей статьи вслух. Через три слова она сбилась. Ник не предложил готовую реплику; вместо этого спросил, что она сказала бы подруге, если бы рассказывала о вчерашнем дне. На четвёртой попытке Алиса заговорила нормально, уже не глядя в объектив."]},{"level":5,"title":"Общее продолжение","paragraphs":["Когда они вернулись к машине, Ник отдал ей картридер и попросил на обратной дороге показать, какие кадры она сама хотела бы оставить. Алиса убрала его в карман. До конца дня они дважды забывали о съёмке: сперва в маленькой лавке с горячим хлебом, потом в холле гостевого дома, где кто-то играл на расстроенном пианино. Ей понравилось, что их лучший разговор так и не попал ни в какой файл."]},{"level":4,"title":"Выбор S29-C2 — Как Алиса предложит провести оставшийся свободный час с Ником?","paragraphs":[]},{"level":5,"title":"A. Выйти без камеры и просто погулять","paragraphs":["Ник положил чехол камеры в багажник и пошёл рядом с Алисой к лавке с открытками. Она купила самую нелепую, а он долго искал марку, которая подходила бы к рисунку. Так прошло полчаса, и никто не спросил, кто кого снимает."]},{"level":5,"title":"B. Попросить его научить её снимать короткий немой фильм","paragraphs":["Ник дал Алисе камеру с заранее выбранными настройками. Она сняла пять секунд ветра в траве и пять — его сосредоточенное лицо. Он попросил переснять второй кадр, потому что совсем не узнал себя. Алиса ответила, что именно таким увидела его."]}]},{"id":"S52","title":"День 14. Перчатка с чужими инициалами","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Ник потерял перчатку. Не свою — выданную на волонтёрской работе. На ладони были вышиты инициалы Инги; она попросила вернуть пару перед отъездом. Ник положил перчатки в карман куртки, но теперь обнаружил только одну. Водитель уже собирался идти за ключами, и Ник попросил Алису помочь обойти их вчерашние остановки.","Они проверили багажник, стойку у входа и кафе, где покупали кофе. В кафе хозяйка предложила им совершенно другую, детскую варежку с оторванной резинкой. Алиса поблагодарила и оставила её на стойке: это была чужая потеря, не решение их задачи.","У почты Ник признался, что иногда легко придумывает квесты из чужих неудобств, потому что так проще переждать собственное раздражение. Алиса посмотрела на его мокрые волосы — он не надел капюшон и теперь мёрз не меньше её.","— Ты можешь просто злиться, — сказала она. — Перчатка от этого не исчезнет окончательно.","— Могу. Но тогда у тебя будет очень скучное свидание.","— Это свидание?","Ник остановился. Он явно не собирался говорить это вслух, и впервые за день у него не нашлось готовой шутки.","Они обнаружили перчатку у двери мастерской, где Ник вчера помогал заносить тяжёлую коробку. Она лежала на подоконнике; кто-то аккуратно расправил пальцы, чтобы ткань высохла."]},{"level":4,"title":"Выбор S52-C1 — что отвечает Алиса","paragraphs":[]},{"level":5,"title":"A. Назвать прогулку свиданием","paragraphs":["— Тогда у нас хорошее свидание, — сказала Алиса. — Только в следующий раз давай без пропаж.","Ник сложил обе перчатки в карман и пообещал попытаться, но не гарантировал. На обратном пути он взял её за руку первым; она не отпустила."]},{"level":5,"title":"B. Предложить обычную прогулку завтра","paragraphs":["— Давай завтра просто выйдем вместе. Без повода и без поиска вещей.","Ник кивнул. Он не спросил, считается ли это свиданием. На обратной дороге они сравнивали окна домов: у каких загорается свет раньше, у каких на подоконнике стоят растения."]},{"level":5,"title":"Общее продолжение","paragraphs":["Инга ответила на их сообщение почти сразу: «Спасибо, я думала, они уехали с вами навсегда». Ник показал ответ Алисе, затем убрал телефон. До гостевого дома оставалось пять минут. Они шли медленно и не говорили о камере."]},{"level":4,"title":"Если `S29-C2=A`","paragraphs":["В магазине Алиса узнала открытку, похожую на ту, что они выбирали без камеры. Ник заметил её улыбку и предложил отправить настоящую открытку, вместо того чтобы снимать ещё одно видео."]},{"level":4,"title":"Если `S29-C2=B`","paragraphs":["В магазине Ник увидел маленькую фоторамку и спросил, помнит ли Алиса свой немой фильм. Она ответила, что помнит его лицо в кадре больше, чем всю остальную дорогу."]}]},{"id":"S30","title":"День 14. Непридуманное будущее","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Дамир заказал суп и достал письмо от клиники. Раньше Алиса видела бы по его лицу, хорошие это новости или плохие. Теперь не угадала: он смотрел на экран с таким вниманием, будто читал чужой анализ.","— Они предлагают мне разговор после поездки. Не работу и не обещание. Просто видеособеседование с заведующей, — сказал он.","— Ты хочешь согласиться?","— Хочу узнать, что за место. Но после Брюсселя боюсь говорить об этом так, будто ты снова должна собирать чемодан вслед за мной.","Алиса взяла ложку, хотя суп был ещё слишком горячим. Она помнила их последний совместный вечер два года назад, когда Дамир сообщил о готовом контракте и спросил, сможет ли она приехать через месяц. Тогда ей понадобились две секунды, чтобы понять: вопрос задан после решения, а не до него. Сейчас перед ним стоял не контракт, а открытое письмо.","— Если тебе предложат работу, ты захочешь поехать? — спросила она.","— Может быть. Но я не хочу, чтобы ты отвечала сегодня. Мы можем поговорить об этом, когда у меня будет что-то кроме письма.","За окном Ник спорил с Эриком о количестве остановок. Алиса вдруг заметила, что им с Дамиром не обязательно проводить этот обед как собеседование на должность бывших возлюбленных. Она спросила, что он заказал бы, если бы в меню было только одно блюдо, от которого его всегда тошнило в студенческой столовой. Дамир посмотрел на тарелку, поморщился и наконец улыбнулся."]},{"level":4,"title":"Выбор S30-C1 — как Алиса отвечает на письмо","paragraphs":[]},{"level":5,"title":"A. Поздравить его и предложить обсудить варианты позже","paragraphs":["— Я рада, что тебя зовут. Правда. Давай поговорим, когда ты сам поймёшь, хочешь ли туда.","Дамир накрыл ладонью край её рукава на столе. Ему явно было легче от того, что разговор не закончился ни ссорой, ни большим обещанием."]},{"level":5,"title":"B. Попросить сразу назвать важные даты и не строить общих планов до них","paragraphs":["— Напиши мне, когда будет собеседование. Я не хочу строить догадки о том, где ты окажешься зимой.","— Напишу. И не буду выдавать возможность за готовое решение.","Они доели суп и вышли на улицу без новой договорённости. Алисе это впервые показалось не пустотой, а честной остановкой."]},{"level":5,"title":"Общее продолжение","paragraphs":["Возвращаясь к машине, Дамир купил в маленькой лавке две одинаковые шоколадки. Алиса сказала, что теперь любит другую начинку. Он вернулся и поменял одну. Это было смешно и немного неловко; зато на этот раз он не настоял на том, что помнит её лучше неё самой."]},{"level":4,"title":"Выбор S30-C2 — Как Алиса пригласит Дамира провести свободное время?","paragraphs":[]},{"level":5,"title":"A. Предложить ему выбрать новую песню для совместной прогулки","paragraphs":["— Не ту, которую мы слушали раньше, — попросила Алиса. Дамир поставил незнакомую ей мелодию, и они прошли от кафе до гостиницы, деля одни наушники. В конце она попросила прислать ей название."]},{"level":5,"title":"B. Позвать его в магазин за смешными сувенирами","paragraphs":["В сувенирной лавке Дамир нашёл открытку с нелепым рисунком лошади, а Алиса — носки с овцами. Они обменялись покупками у кассы. Дамир сказал, что носки пригодятся на ферме; она предложила проверить это завтра."]}]},{"id":"S55","title":"День 14. Конь по имени Шум","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Инструктор выдала им шлемы и объяснила, как держать повод. Маршрут проходил по ровной огороженной дорожке; из-за ветра часть тропы была закрыта, и группа не выезжала за пределы фермы. Алисе досталась спокойная гнедая кобыла. Дамир получил небольшого светлого коня по имени Шум, который немедленно решил, что стоять перед воротами интереснее, чем идти.","— Он всегда такой? — спросил Дамир.","— Только если ему скучно, — ответила инструктор и показала, как дать животному понять направление.","Алиса давно не видела Дамира растерянным в ситуации, которую нельзя решить знаниями и скоростью. Он серьёзно слушал инструктора, попробовал движение, получил в ответ полный покой и тихо выругался. Алиса рассмеялась. Он обернулся к ней и сам засмеялся, а потом конь наконец сделал шаг.","На остановке инструктор разрешила им снять шлемы и выпить воды. Алиса обнаружила, что по-прежнему улыбается. Дамир вытер со лба пот рукавом и сказал, что на работе ему не приходится просить пациентов объяснить, куда они хотят идти, но здесь Шум явно считал иначе.","— У него есть преимущество, — ответила Алиса. — Он может притвориться, что не понял твой вопрос.","— Иногда я тоже так делал.","Она ожидала продолжения, но Дамир просто закрыл бутылку и пошёл поправить седло по просьбе инструктора. Алисе понравилось, что этот день не превратился в очередное обсуждение их расставания. У неё осталось новое воспоминание: Дамир с перекошенным шлемом, который вежливо просит у лошади хотя бы один шаг."]},{"level":4,"title":"Выбор S55-C1 — после прогулки","paragraphs":[]},{"level":5,"title":"A. Поддразнить Дамира фотографией","paragraphs":["Алиса показала ему снимок, где Шум смотрел прямо в объектив, а Дамир — в совершенно другую сторону. Он попросил прислать фото и назвал его лучшим кадром путешествия. Она отправила снимок без подписи."]},{"level":5,"title":"B. Сказать, что ей понравилось видеть его таким","paragraphs":["— Мне понравилось, как ты смеялся, — сказала она. — Не когда всё получается, а когда совсем не получается.","Дамир снял перчатки и посмотрел на неё чуть дольше обычного. Потом спросил, согласится ли она завтра выбрать для них музыку. Алиса кивнула."]},{"level":5,"title":"Общее продолжение","paragraphs":["У ворот фермы они встретили Ника, который приехал с Эриком за кофе. Ник хотел спросить, кто победил — человек или лошадь, но увидел выражение Дамира и передумал. Всю обратную дорогу Алиса пыталась вспомнить, когда в последний раз ей было так легко рядом с бывшим возлюбленным. Оказалось, она не хотела сравнивать."]},{"level":4,"title":"Если `S30-C2=A`","paragraphs":["У ворот фермы Дамир тихо насвистывал ту мелодию, которую выбрал для их прогулки. Алиса узнала её и вдруг поняла: новое воспоминание возникло так легко, что никто не заметил, когда это случилось."]},{"level":4,"title":"Если `S30-C2=B`","paragraphs":["У ворот фермы Дамир показал Алисе открытку с нелепой лошадью. Она сняла перчатку и достала из кармана носки с овцами: обещанный обмен неожиданно оказался подходящим нарядом для прогулки."]}]},{"id":"S31","title":"День 14. Не их история","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Марина вышла на связь с опозданием. В кадре у неё за спиной постоянно проходили люди, и дважды кто-то просил её подписать документ. Алиса расположилась на подоконнике гостевого дома, потому что в комнате соседка смотрела фильм. Она успела переписать начало статьи три раза и теперь всё равно не хотела отправлять ни один вариант.","— У тебя есть человек, за которым интересно следить? — спросила Марина. — Не виды, не отели. Человек.","— Есть несколько. Но я не уверена, что хочу писать о них так, будто они приехали сюда ради моей истории.","— Ты журналистка. Люди обычно не приезжают ради твоей статьи.","Алиса усмехнулась: Марина не была злодейкой, она просто хотела материал с началом и концом. На столе рядом лежала фотография настила, которую прислала Инга. Алиса повернула телефон так, чтобы Марина увидела снимок.","— Я хочу написать о том, кто остаётся, когда туристы уезжают. Мы помогли час, а Инга придёт туда ещё завтра. Это ведь тоже человек, за которым можно следить. Только её надо спросить, согласна ли она.","Марина попросила план на три абзаца. Алиса открыла заметки и впервые за долгое время продиктовала начало без попытки угадать желаемый ответ редактора."]},{"level":4,"title":"Выбор S31-C1 — какой материал она предложит","paragraphs":[]},{"level":5,"title":"A. Сделать героиней Ингу — после отдельного согласования","paragraphs":["Алиса написала Инге короткое сообщение. В нём не было просьбы срочно помочь редакции. Она предложила прислать вопросы и дать право проверить факты о работе на тропе. Ответ пришёл позже: Инга готова рассказать, но не хочет, чтобы её называли «спасительницей природы»."]},{"level":5,"title":"B. Рассказать об общей поездке без чужих личных подробностей","paragraphs":["Алиса выбрала пять маленьких действий группы: перенесённое интервью, мокрые перчатки, осторожную остановку у дороги, ужин без съёмки и возвращённую рукавицу. У каждого факта был человек, который согласился его рассказать. Марина предложила сильнее выделить начало, но не потребовала чужих признаний."]},{"level":5,"title":"Общее продолжение","paragraphs":["Отключившись, Алиса положила телефон экраном вниз и впервые за вечер услышала, что в соседней комнате кто-то играет на расстроенной гитаре. Она не пошла узнавать, кто это. Ей было хорошо одной, и на этот раз в этом не было ни жеста против кого-то, ни ожидания, что сейчас случится что-нибудь значительное."]},{"level":4,"title":"Выбор S31-C2 — Что Алиса сделает для себя после разговора с редактором?","paragraphs":[]},{"level":5,"title":"A. Записать короткое письмо себе домой","paragraphs":["Алиса открыла заметки и написала, что хочет попробовать после возвращения: досмотреть старый фильм с подругой, дописать статью без ночных смен и выбрать прогулку, где никто не будет ждать отчёта. Письмо осталось в черновиках."]},{"level":5,"title":"B. Самостоятельно выбрать место для завтрашнего завтрака","paragraphs":["Алиса спросила у хозяина гостевого дома, где по утрам пекут хлеб. Он назвал небольшую лавку; она сохранила адрес и пошла проверять, когда там открывается дверь. Даже такая маленькая договорённость с собой подняла ей настроение."]}]},{"id":"S62","title":"День 14. Книжный, где никто её не ждёт","episode":7,"source":"content/season-1-literary-episode-07.md","chunks":[{"level":0,"title":"","paragraphs":["Утром Алиса сказала группе, что встретит их к ужину. Ник предложил прислать ей свой список красивых мест. Она поблагодарила и оставила телефон в кармане. За этот день ей хотелось отвечать только на собственные вопросы.","В магазине у кассы стояла полка книг на нескольких языках. Алиса долго перелистывала тонкий сборник рассказов, который не могла прочитать без словаря, затем выбрала книгу с фотографиями старых исландских кухонь. На одной странице кто-то от руки записал рецепт. Продавщица объяснила, что книги приносит местная библиотека после обменов: если захочется, Алиса сможет оставить здесь свою, когда будет проезжать обратно.","В бассейне было тихо. Алиса проплыла несколько дорожек, потом села у бортика и наблюдала, как пожилая женщина учит внука держаться на воде. В её руках не было камеры, в кармане халата не лежал блокнот. За час ни один человек не попросил её решить, с кем проводить вечер."]},{"level":4,"title":"Выбор S62-C1 — кому она напишет после бассейна","paragraphs":[]},{"level":5,"title":"A. Подруге, с которой давно не виделась","paragraphs":["«Я купила книгу и вспомнила, что хочу просто прийти к тебе в гости, когда вернусь». Ответ пришёл не сразу, зато подруга прислала фотографию своего нового чайника и спросила, не против ли Алиса субботы."]},{"level":5,"title":"B. Никому: оставить этот день без отчёта","paragraphs":["Алиса убрала телефон обратно, села в маленьком кафе и съела горячую булочку, пока та не остыла. Вечером она всё равно рассказала группе о книге; разница была в том, что рассказала, когда захотела."]},{"level":5,"title":"Общее продолжение","paragraphs":["За ужином Дамир спросил, как прошёл день. Алиса показала страницу с рецептом. Эрик попытался прочитать подпись; Ник предложил приготовить блюдо в последнюю ночь поездки. Она согласилась подумать. Её день не принадлежал ни одному из них, но им было место в разговоре о нём."]},{"level":4,"title":"Если `S31-C2=A`","paragraphs":["Утром Алиса перечитала своё письмо себе из гостевого дома. Она добавила в него одну строчку: «Не обязательно выполнять всё сразу». После этого спокойно пошла в книжный."]},{"level":4,"title":"Если `S31-C2=B`","paragraphs":["Утром Алиса нашла рекомендованную лавку и купила завтрак без спешки. Книжный магазин открылся позднее, и у неё оставалось время просто посидеть у окна."]}]},{"id":"S32","title":"День 15. Не совпасть расписаниями","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":0,"title":"","paragraphs":["Утром Эрик действительно сел завтракать вместе со всеми. Первые пять минут он пытался глазами проверить, закрыли ли водительскую дверь и где лежит аптечка. Алиса передвинула к нему тарелку с горячими тостами. Он откусил один, только тогда перестал оглядываться. Никаких победных слов она не произнесла: ей нравилось, что он просто сидит рядом.","На телефон Эрика пришло два сообщения почти одновременно. Сестра предлагала зимой помочь ей с переездом в небольшое поселение, а руководитель программы местных гидов приглашал Эрика вести сезонное обучение в те месяцы, когда туристов немного. Он прочёл вслух оба сообщения, потому что сестра просила о дате, а о школе Алиса уже знала.","— Ты хочешь согласиться? — спросила она.","— На обучение — да. Сестре тоже хочу помочь. Если взять оба дела, меня почти не будет в Рейкьявике зимой.","У Алисы в это же утро было письмо от Марины: редакция обсуждала её участие в длинной городской серии после возвращения домой. Несколько месяцев интервью, монтаж материала и много встреч в одном городе. Впервые за путешествие Алиса увидела ближайшую зиму целиком и не нашла в ней ни одного общего дня с Эриком.","— Мне предложили остаться в редакции над новой серией, — сказала она. — Пока предварительно. Я хочу попробовать.","Эрик убрал телефон. Он был рад за неё, и это было видно прежде, чем он произнёс «поздравляю». Затем спросил, как долго будет длиться работа, и Алиса назвала приблизительные сроки. Они не спорили. Разговор закончился потому, что Ник позвал их к машине, а продолжать его на глазах у остальных не хотелось.","После переезда в Akureyri они вышли за кофе. Эрик всё время нёс с собой бумажный пакет с двумя булочками — одну купил Алисе, но забыл отдать. Когда вспомнил, булочка остыла. Алиса взяла её. Это было так похоже на него, что от обиды ей стало немного смешно.","— Мне не нужен ответ о зиме сегодня, — сказала она. — Но я не хочу обещать, что брошу работу, если мы понравились друг другу в путешествии.","— Я этого не прошу. И не хочу обещать, что отменю всё своё. Просто я думал, что время появится само.","Они дошли до перекрёстка, где нужно было выбрать: повернуть к гостинице или пройти по старым улицам. Эрик остановился, ожидая её решения. Алисе стало ясно, что ему трудно не потому, что он не умеет считаться с ней. Он умеет; но одного согласия недостаточно, если два календаря не оставляют места человеку."]},{"level":4,"title":"Выбор S32-C1 — что предлагает Алиса","paragraphs":[]},{"level":5,"title":"A. Продолжить отношения, не решая зиму немедленно","paragraphs":["— Я хочу провести с тобой оставшиеся дни. Дома мы посмотрим на реальные даты, а не будем спорить с воображаемым расписанием.","Эрик кивнул. Он не назвал это готовым планом. Зато впервые за утро открыл телефон не с рабочим сообщением, а чтобы записать день, в который они вместе собирались позвонить друг другу после возвращения Алисы."]},{"level":5,"title":"B. Попросить паузу без обещания свиданий","paragraphs":["— Мне нужно немного побыть отдельно, — сказала Алиса. — Я не знаю, хочу ли продолжать, пока всё выглядит так.","Эрик отдал ей булочку в бумажном пакете и ответил, что встретит её у машины к общему отъезду. Он не пытался превратить паузу в наказание. Алиса пошла к гостинице одна и впервые с утра смогла спокойно прочитать письмо Марины."]},{"level":5,"title":"C. Закончить романтическую историю сейчас","paragraphs":["— Я рада, что мы были близки, — сказала Алиса. — Но я не хочу строить следующие месяцы из надежды, что кто-нибудь из нас передумает жить своей жизнью.","Эрик не спорил. Спросил, хочет ли она, чтобы он предупредил остальных о смене плана вечера, или она сама скажет. Алиса сказала, что сама. Они вернулись к группе разными улицами; вечером Эрик всё равно оставил у её двери забытый в машине шарф."]},{"level":5,"title":"Общее продолжение","paragraphs":["После разговора Алиса записала время и место для статьи: Akureyri, мокрая улица, булочка с остывшим маслом. Она не записала чужих слов. Эрик не просил её ничего скрывать, но это был разговор, который она прожила как Алиса, а не как журналистка. Город жил дальше. На остановке двое подростков смеялись, пытаясь укрыть один рюкзак от дождя, а в гостинице Ник искал переходник к своему ноутбуку."]}]},{"id":"S50","title":"День 15. Город без карты","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":4,"title":"Если `routeStatus=active`","paragraphs":["Эрик оставил в гостинице бумажную карту и телефон с приложением маршрутов. Он предложил Алисе выбрать одну улицу, а потом сам выбирал бы следующую. Условие было одно: вернуться к ужину, не идти за пределы освещённого центра и не спорить, если один из них устал. Алиса повела их к лавке с яркими открытками, потому что там в окне стояла смешная деревянная птица. Эрик выбрал лестницу к старой церкви. Наверху оказалось так ветрено, что они тут же вернулись вниз.","В маленьком книжном Эрик нашёл издание рецептов, по которому в детстве пытался готовить с сестрой. Алиса попросила показать страницу самого неудачного блюда. Он открыл её наугад: клейкие картофельные лепёшки, которые они однажды испекли настолько твёрдыми, что отец предложил использовать их вместо подставок под горячее. Алиса смеялась, пока продавец не принёс им две бумажные закладки.","На обратной дороге Эрик всё-таки заговорил о зиме — не о том, кто чем пожертвует, а о том, когда Алиса обычно чувствует себя дома. Она рассказала про воскресное утро, когда можно читать газету и не отвечать на телефон. Эрик сказал, что для него это вечер после долгой дороги: снять ботинки и услышать, как на кухне кто-то ставит чайник. Они не обещали друг другу общего адреса. Но на перекрёстке Алиса взяла его за руку."]},{"level":4,"title":"Если `routeStatus=paused`","paragraphs":["Они встретились у лестницы в гостинице и пошли к книжному, потому что там продавали карту города для Ника. Эрик не пытался взять Алису за руку. Они обсуждали подарок его сестре и фотографию починенного настила, которую прислала Инга. Когда Алиса попросила подождать её у витрины, он ответил «конечно» и остался на улице. Это было непривычно — не холодно, просто иначе. У неё было время понять, хочет ли она снова идти рядом с ним по собственному желанию."]},{"level":4,"title":"Выбор S50-C1 — что Алиса берёт из города","paragraphs":[]},{"level":5,"title":"A. Купить открытку себе, а не для статьи","paragraphs":["Она выбрала карточку с зимним окном, хотя сейчас в городе шёл дождь. На обратной стороне написала: «Здесь мы не знали, что будет дальше». Положила открытку в книгу, которую собиралась дочитать дома."]},{"level":5,"title":"B. Подарить Эрику закладку с деревянной птицей","paragraphs":["Эрик посмотрел на маленький бумажный прямоугольник, будто не ожидал от такой вещи подарочного значения. Потом спрятал его в карман внутренней куртки, где держал документы, и поблагодарил Алису без шутки."]},{"level":5,"title":"Общее продолжение","paragraphs":["К ужину они вернулись вовремя. Ник спросил, не заблудились ли они. Алиса ответила, что в центре Akureyri очень трудно заблудиться, если каждые пять минут заглядывать в витрины. Эрик не стал спорить с таким описанием дня."]},{"level":4,"title":"Выбор S50-C2 — Что Алиса предложит Эрику перед завершением прогулки?","paragraphs":[]},{"level":5,"title":"A. Попросить рассказать о любимом семейном вечере","paragraphs":["Эрик вспомнил, как сестра в детстве заставляла всех играть в настольную игру, правила которой меняла по ходу партии. Алиса рассмеялась и предложила однажды попробовать сыграть так же. Это было приглашение, а не требование обещать дату."]},{"level":5,"title":"B. Пригласить его вместе выбрать небольшой подарок сестре","paragraphs":["Они зашли в магазин и выбрали деревянную птицу для сестры Эрика. Алиса настояла, чтобы он подписал открытку сам. Эрик долго выбирал слова, а она стояла рядом и рассматривала витрину."]}]},{"id":"S33","title":"День 15. Тизер","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":0,"title":"","paragraphs":["Ник показал Алисе новый монтаж накануне вечером. Она одобрила свои слова для одного эпизода фильма и отказалась от кадра в аэропорту. Утром продюсер попросил тизер к встрече с заказчиком, и Ник отправил рабочую версию, в которой уже не было аэропорта, но оставалась короткая запись их разговора после бассейна. Ник не заметил её в общей монтажной дорожке; точнее, заметил, но убедил себя, что в кадре они говорят не о ней, а о путешествии.","Алиса увидела тизер в гостинице Akureyri, когда получила ссылку от Марины с вопросом: «Это ты?» На экране Ник смеялся, а её голос произносил фразу, которую она сказала ему, когда они были вдвоём. Алиса не смогла сразу ответить редактору. Она открыла дверь соседнего номера и постучала.","Ник показался с наушниками на шее. Увидев экран её телефона, он сразу понял, о чём речь. Не сказал, что «это всего лишь рабочая версия». Спросил, кому ещё продюсер отправил ссылку. Оказалось, заказчику и трём коллегам. Ник позвонил при Алисе, попросил закрыть доступ к файлу и удалил его из общей папки. Продюсер был раздражён; новая версия понадобилась к вечеру.","— Я думал, что вырезал всё личное, — сказал Ник, когда положил трубку.","— Ты думал. А я просила показать мне материал до отправки. Не весь фильм, а то, что касается меня.","Он хотел объяснить, почему спешил. На столе лежала распечатка нового предложения о работе: продюсер видел в нём режиссёра следующего проекта. Ник перевернул лист текстом вниз.","— Я отправил не туда взгляд, — сказал он после паузы. — Я смотрел на срок и пропустил твой голос.","Алиса села на край кресла. Ей нравился Ник, и именно поэтому чужая ссылка оказалась больнее, чем случайная публикация незнакомого видеографа. Она не хотела читать ему лекцию и не хотела немедленно прощать ради красивой следующей сцены."]},{"level":4,"title":"Выбор S33-C1 — что делает Алиса после удаления файла","paragraphs":[]},{"level":5,"title":"A. Попросить увидеть исправленный тизер до новой отправки","paragraphs":["— Если ты хочешь, чтобы мы продолжили, пришли мне версию без моего голоса до того, как покажешь кому-то ещё.","Ник согласился. Он закрыл ноутбук на десять минут, чтобы не отвечать сразу монтажом. Потом попросил Алису выйти на улицу, пока он переделает файл: ей не нужно было сидеть рядом и проверять каждое движение мыши."]},{"level":5,"title":"B. Взять паузу и отказаться обсуждать фильм сегодня","paragraphs":["— Я не хочу сейчас смотреть ещё один монтаж, — сказала Алиса. — Сделай то, что обязан сделать без моего участия. А мне нужно побыть одной.","Ник кивнул. Он сообщил продюсеру о запрещённом фрагменте и отправил Алисе подтверждение закрытого доступа, не добавляя просьбы поговорить. Алиса прочитала сообщение, когда сама захотела."]},{"level":5,"title":"C. Закончить романтическую историю","paragraphs":["— Я не хочу проверять, повторится ли это, — сказала Алиса. — Фильм твой. Моя жизнь — не часть условий его сдачи.","Ник не предложил ей исправить всё одним монтажом. Спросил, хочет ли она, чтобы он удалил все личные записи, и сделал это после её ответа. Позже они ехали в общей машине молча. Дружба с остальными не требовала, чтобы Алиса притворялась, будто ничего не произошло."]},{"level":5,"title":"Общее продолжение","paragraphs":["К вечеру появилась новая версия тизера. Ник сначала показал её продюсеру с пометкой, что использовать личные фразы Алисы нельзя, а затем прислал Алисе только информацию о том, что спорный материал удалён. За окном гостиницы шёл дождь. Группа договорилась встретиться за ужином, но Алиса решила прийти чуть позже, когда сможет разговаривать не только о том, что случилось."]}]},{"id":"S53","title":"День 16. Один день без камеры","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":4,"title":"Если `routeStatus=active`","paragraphs":["Ник положил камеру в багажник и закрыл машину. Потом вернулся, чтобы убедиться, что оставил там и запасную батарею. Алиса не просила его избавляться от профессии на целый день; он сам сказал, что хочет узнать, что они будут делать, когда нечего снимать и не нужно придумывать план на следующий кадр.","В бассейне они проплыли по нескольку дорожек и долго сидели на скамье, отогревая пальцы о бумажные стаканы с чаем. Ник не рассказывал историю на каждый случай. Он следил, как ребёнок учится держаться у бортика, и тихо заметил, что в детстве сам боялся глубокой воды. Алиса спросила, кто научил его плавать. Он ответил: младшая сестра, хотя по возрасту это звучало нелепо. Она терпеливо стояла на мелководье и говорила, что он может выйти из воды в любой момент. Алиса подумала о вчерашнем разговоре, но не стала превращать воспоминание в урок.","После бассейна они вышли в пекарню. Ник долго выбирал между двумя одинаково большими булочками и взял ту, где было больше корицы. Он признался, что ему нравится обычное утро, но он часто не умеет оставаться в нём: начинает искать следующее событие, словно без него исчезнет сам. Алиса предложила съесть булочку, пока она тёплая, и поговорить об этом потом. Он согласился и действительно не достал телефон."]},{"level":4,"title":"Если `routeStatus=paused`","paragraphs":["Они встретились за общим завтраком и после него прошли вместе только до пекарни. Ник не предлагал свидание. Алиса спросила, удалён ли личный фрагмент из всех рабочих копий; он показал письмо продюсера, подтверждавшее удаление. Затем каждый выбрал себе булочку. Разговор был спокойным и немного чужим. Оказалось, паузу нельзя сыграть как романтическую сцену, и Алиса не стала пытаться."]},{"level":4,"title":"Выбор S53-C1 — что они делают после пекарни","paragraphs":[]},{"level":5,"title":"A. Пойти к книжному без цели и без камеры","paragraphs":["Они долго выбирали открытку с самым странным изображением города, затем отправили её сестре Ника. На улице Алиса поняла, что не запомнила половину вывесок. Ей это понравилось: не каждый день обязан стать чьим-то материалом."]},{"level":5,"title":"B. Вернуться к группе и не требовать продолжения дня","paragraphs":["Они вышли к машине разными дорожками. За ужином Ник сел рядом с Эриком и рассказывал историю о том, как потерял перчатку. Алиса могла слушать, не решая сразу, что означает их общий день."]},{"level":5,"title":"Общее продолжение","paragraphs":["Ночью Ник прислал ей фотографию пустой карты памяти с короткой подписью: «Сегодня ничего не снял». Алиса ответила снимком обёртки от коричной булочки. Он поставил под ответом сердечко и больше ничего не написал."]},{"level":4,"title":"Выбор S53-C2 — Что Алиса предложит Нику делать в конце дня без камеры?","paragraphs":[]},{"level":5,"title":"A. Договориться о коротком свидании после возвращения домой","paragraphs":["— Без расписания съёмок, — добавила Алиса. Ник на секунду перестал улыбаться, а потом предложил конкретную кофейню возле её редакции. Они не бронировали столик; ей понравилось, что он не сделал из приглашения шутку."]},{"level":5,"title":"B. Обменяться любимыми книгами из дорожных сумок","paragraphs":["Алиса принесла свой недочитанный роман, Ник — потрёпанный сборник рассказов. Они обменялись книгами до последнего дня поездки. Ник пообещал не заглядывать в её заметки на полях и действительно закрыл обложку."]}]},{"id":"S34","title":"День 16. Отменённый вечер","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":0,"title":"","paragraphs":["Накануне они договорились поужинать вдвоём. Дамир выбрал небольшое кафе недалеко от гостиницы и прислал Алисе меню, чтобы она могла решить, подходит ли ей место. Алиса ответила «да», даже представила, как они сядут у окна. Утром она прочла письмо Марины о новой городской серии и внезапно почувствовала, будто снова стоит в квартире двухлетней давности среди коробок: Дамир собирается в другой город, она решает, ехать ли следом, и оба делают вид, что времени достаточно.","Дамир в этот день не просил её менять планы. Наоборот, он сказал, что собеседование в клинике назначили на неделю после возвращения и что решать о работе он будет отдельно. Это была хорошая новость. Именно поэтому Алиса испугалась: исчезла возможность объяснить тревогу его очередной ошибкой.","Она написала ему, что ужин отменяется. Без причин. Он ответил: «Понял. Встретимся с группой вечером». Алиса перечитала сообщение и разозлилась на себя за то, что ждала от него привычных попыток уговорить её. В полдень она вышла на улицу, купила себе кофе и прошла два квартала под дождём. Телефон был в кармане. Дамир не звонил.","У входа в гостиницу она увидела его с пакетом из аптеки. Он забирал пластырь для Эрика, натёршего пятку на прогулке. Они поздоровались почти как случайные знакомые. Алиса могла пройти мимо, но остановилась сама.","— Я испугалась, — сказала она. — Не тебя сегодня. Того, как быстро мне снова стало хорошо рядом с тобой.","Дамир прижал пакет к боку.","— Я не знаю, что с этим делать за тебя.","— Я тоже. И не хочу, чтобы ты опять стал человеком, на которого удобно злиться.","Он не пытался приблизиться. Сказал, что кафе никуда не исчезнет, но им обоим стоит решить, хотят ли они вообще идти туда вместе."]},{"level":4,"title":"Выбор S34-C1 — как Алиса поступит с договорённостью","paragraphs":[]},{"level":5,"title":"A. Предложить встретиться позже, без обязательства решить будущее","paragraphs":["— Давай поужинаем завтра, если оба захотим. Я расскажу, что меня напугало, а ты скажешь, если этот разговор тебе тяжёл.","Дамир согласился, и Алиса впервые не испытала облегчения от того, что всё снова «решено». Они договорились только о времени."]},{"level":5,"title":"B. Взять паузу до конца следующего дня","paragraphs":["— Мне нужен день без наших свиданий. Я скажу тебе завтра, хочу ли продолжить.","— Хорошо, — ответил Дамир. — И если не захочешь, я пойму.","Он ушёл к лестнице. Алиса поняла, что сама попросила паузу и теперь должна использовать её не для выдумывания его будущих ответов, а для собственного решения."]},{"level":5,"title":"C. Закончить романтическую историю","paragraphs":["— Я не готова снова начинать. Мне было хорошо рядом с тобой, но я не хочу делать тебе обещание из своей тоски по прошлому.","Дамир выдохнул и ответил, что тоже не хочет такого обещания. Вечером они сидели за общим столом напротив друг друга и обсуждали завтрашний переезд. Это было неловко. Но неловкость не требовала нового свидания, чтобы исчезнуть немедленно."]},{"level":5,"title":"Общее продолжение","paragraphs":["Алиса вернулась в номер и села на пол рядом с чемоданом. Плащ капал на коврик у двери. Впервые за день она не ждала сообщения от Дамира, чтобы узнать, как ей жить дальше. Она открыла статью и переписала один абзац о дороге: там больше не было фразы, будто все перемены происходят с человеком против его воли."]}]},{"id":"S56","title":"День 16. Песня, которую они не знали раньше","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":4,"title":"Если `routeStatus=active`","paragraphs":["Дамир пришёл без обычной привычки заранее узнать, куда садиться. Он увидел свободный столик и спросил, хочет ли Алиса остаться ближе к музыкантам или у окна. Она выбрала окно: оттуда было видно, как на улице двое людей под одним зонтом спорят, в какую сторону идти.","Музыканты играли песни, которых Алиса прежде не слышала. Дамир не пытался найти знакомую мелодию из их общего прошлого. Он пил безалкогольный напиток и слушал, чуть наклоняя голову, как делал когда-то на первом курсе. Алиса могла бы сказать, что помнит этот жест. Вместо этого спросила, нравится ли ему музыка. Он ответил, что не знает, но хочет остаться до конца.","Когда началась медленная композиция, Дамир протянул ей руку. Они вышли на свободное место у стены. Алиса сама положила ладонь ему на плечо. Его движения были неуверенными; за два года они разучились угадывать шаг друг друга, и это неожиданно облегчило танец. Не нужно было воспроизводить то, как они двигались раньше."]},{"level":4,"title":"Если `routeStatus=paused`","paragraphs":["Они пришли на музыкальный вечер вместе с группой и сели по разные стороны стола. Ник увлёк Эрика спором о самой ужасной дорожной песне. Дамир спросил Алису, не мешает ли ей музыка работать. Она сказала, что сегодня не пишет. За весь вечер они не обсуждали паузу. Алиса была благодарна, что он не устроил из общей поездки испытание её решения."]},{"level":4,"title":"Выбор S56-C1 — когда начинается новая композиция","paragraphs":[]},{"level":5,"title":"A. Остаться ещё на одну песню","paragraphs":["Алиса не смотрела на время. Она слушала ударные, иногда ловила взгляд Дамира и думала о том, что можно узнать знакомого человека без необходимости вернуть прежний вечер."]},{"level":5,"title":"B. Выйти на улицу и пройтись до гостиницы","paragraphs":["Они пошли рядом под дождём. Дамир уступил ей сторону тротуара под навесом, но Алиса всё равно промокла. Она засмеялась, когда вода стекла с его рукава прямо на ботинок. Он попробовал извиниться, потом тоже засмеялся."]},{"level":5,"title":"Общее продолжение","paragraphs":["У дверей гостиницы они задержались всего на минуту. Дамир сказал, что ему понравилась песня, хотя он не сможет вспомнить её названия. Алиса ответила, что, может быть, и не нужно. Она поднялась к себе, прислушиваясь к музыке, которая ещё долетала с улицы."]},{"level":4,"title":"Выбор S56-C2 — Что Алиса предложит Дамиру после музыкального вечера?","paragraphs":[]},{"level":5,"title":"A. Найти вместе новое блюдо на завтрашний день","paragraphs":["Алиса предложила попробовать что-нибудь, чего они оба раньше не ели. Дамир показал вывеску маленького кафе, мимо которого проходил утром. Они договорились зайти туда, если группа не поменяет план."]},{"level":5,"title":"B. Научить его припеву незнакомой песни","paragraphs":["Дамир дважды перепутал слова, а Алиса никак не могла попасть в ритм. Они рассмеялись и решили оставить попытку до следующей прогулки. У них появился припев, который никому не нужно было связывать с прошлым."]}]},{"id":"S35","title":"День 16. Не дать им чужих слов","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":0,"title":"","paragraphs":["Марина прислала черновой заголовок: «Как четыре незнакомца нашли друг друга на краю света». Алиса прочла его трижды. Они не были незнакомцами, и не все искали друг друга. Кроме того, Марина вставила в подзаголовок фразу из личного разговора, которую Алиса однажды пересказала в редакторском письме без имени. В письме это было рабочее замечание; в готовом материале оно превращало живого человека в эффектную цитату.","Алиса позвонила Марине из кафе, где пахло мокрой одеждой и корицей. Она объяснила, что не может подтвердить слова за человека, который не согласился говорить для статьи. Марина раздражённо ответила, что читателю нужен конкретный герой. Алиса не стала спорить о том, что нравится читателям вообще. Она показала Ингину фотографию настила и предложила героем сделать работу, которую туристы обычно не замечают.","Марина замолчала, затем попросила прислать готовую структуру до вечера. Разговор не стал победой Алисы над редакцией. Ей ещё нужно было доказать, что материал будет интересен без чужой исповеди."]},{"level":4,"title":"Выбор S35-C1 — что Алиса оставляет в статье","paragraphs":[]},{"level":5,"title":"A. Сохранить согласованные прямые цитаты и убрать личные подробности","paragraphs":["Алиса открыла список собеседников и написала каждому, что именно собирается использовать. Инга прислала исправленное название тропы; хозяйка коптильни попросила убрать время смены. Алиса внесла изменения и почувствовала знакомую усталость от хорошей журналистской работы — конкретной, долгой и без эффектных обещаний."]},{"level":5,"title":"B. Пересобрать материал вокруг собственных наблюдений","paragraphs":["Алиса взяла пять заметок, сделанных во время поездки, и вычеркнула все чужие слова, сказанные не для публикации. Остались вещи, которые она видела сама: закрытая дорога, мокрые перчатки, свет в гостевом доме и люди, готовые менять планы. Материал стал тише, но точнее."]},{"level":5,"title":"Общее продолжение","paragraphs":["Вечером Марина прислала одно сообщение: «Новый угол вижу. Доделывай». Алиса не знала, одобрят ли весь текст. Зато теперь у неё был материал, за каждую строку которого она могла отвечать."]}]},{"id":"S63","title":"День 16. Концерт для одного человека","episode":8,"source":"content/season-1-literary-episode-08.md","chunks":[{"level":0,"title":"","paragraphs":["Вечером Алиса купила один билет. У кассы женщина спросила, не ждёт ли она кого-то ещё. «Нет», — ответила Алиса и почувствовала, что объяснять больше нечего. В небольшом зале стояли складные стулья, музыканты настраивали инструменты без занавеса, а мужчина у двери искал потерянный шарф. Алиса помогла ему поднять шарф со спинки последнего ряда и села ближе к окну.","На третьей композиции рядом кто-то стал тихо отбивать такт носком ботинка. Алиса тоже двигала ногой, пока не заметила этого. Музыка не обещала, что путешествие изменит её судьбу. Это был просто удачный вечер, на который она пришла потому, что захотела."]},{"level":4,"title":"Выбор S63-C1 — после концерта","paragraphs":[]},{"level":5,"title":"A. Остаться на короткую встречу с музыкантами","paragraphs":["Алиса спросила, откуда взялась мелодия, звучавшая посередине концерта. Скрипачка рассказала, что научилась ей у бабушки, и написала название на обратной стороне билета. Алиса сохранила билет в кармане рядом с чеком из книжного."]},{"level":5,"title":"B. Вернуться в гостиницу пешком, не задерживаясь","paragraphs":["По пути она купила горячий чай и дошла до гостиницы через освещённую площадь. На ресепшене Ник спросил, как прошёл концерт. Алиса ответила: «Хорошо. И не снято ни секунды». Он улыбнулся и не стал просить подробностей."]},{"level":5,"title":"Общее продолжение","paragraphs":["Ночью в общий чат пришло сообщение Эрика о времени завтрашнего выезда. Алиса поставила будильник. Она уезжала вместе с группой, и это оставалось её путешествием независимо от того, с кем она собиралась проводить вечер."]},{"level":4,"title":"Выбор S63-C2 — Как Алиса продолжит самостоятельный вечер после концерта?","paragraphs":[]},{"level":5,"title":"A. Сохранить билет и написать несколько строк для себя","paragraphs":["Алиса положила билет в книгу и записала на обороте дату и песню, которую хотела бы снова услышать. Она не собиралась включать этот вечер в статью: ему не требовался зритель."]},{"level":5,"title":"B. Спросить соседку по ряду о следующем концерте","paragraphs":["Женщина рядом рассказала Алисе, где музыканты будут играть в следующий раз. Алиса записала название площадки и поблагодарила её. Оказалось приятно планировать что-то своё в городе, где завтра можно оказаться совершенно одной."]}]},{"id":"S36","title":"День 17. Место для остановки","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Они загрузили чемоданы в машину молча. За окном гостиницы дождь наконец перестал, но никто не стал объявлять это наградой за вчерашний день. Ник проверил ремни на сумках с аппаратурой, Дамир принёс оставленную Алисе бутылку воды, Эрик сверил выезд с официальной дорожной информацией. Алиса села на своё место, где под сиденьем всё ещё лежала перчатка из первого дня. Она подняла её и положила в карман двери: вещи в машине за эти недели успели стать общими, хотя у каждой когда-то был хозяин.","К середине дня они оказались на длинном открытом участке дороги. Ник предложил включить их плохую песню. Эрик ответил, что сначала необходимо остановиться и проверить давление в одном колесе: машина слегка тянула в сторону, и при выезде это было почти незаметно. Он свернул на разрешённую площадку, осмотрел колёса и позвонил в прокатную компанию. Сотрудник рекомендовал ближайший сервис; ехать дальше, не проверив колесо, было бы глупо.","Пока они ждали, Алиса наблюдала, как каждый по-разному переносит незапланированную паузу. Дамир сходил за кофе для всех. Ник вышел к ограждению, сделал два кадра пустой дороги, затем убрал камеру. Эрик разговаривал с мастером и наконец сел на скамью. Ник спросил, не слишком ли тот устал. Эрик ответил, что устал, и добавил, что это не повод заставлять остальных ждать его в машине.","В сервисе выяснилось, что в шину попал маленький металлический предмет. Ремонт занял меньше часа. Никакой беды не произошло; они просто не успели к одной из планировавшихся остановок. Алиса спросила, можно ли заменить её прогулкой возле следующего ночлега. Все согласились, и от этого последняя длинная дорога внезапно стала менее похожа на выполнение заранее написанного списка."]},{"level":4,"title":"Выбор S36-C1 — как Алиса использует незапланированную паузу","paragraphs":[]},{"level":5,"title":"A. Предложить всем короткую прогулку до возвращения в машину","paragraphs":["Они прошли по обозначенной дорожке от сервиса к маленькому кафе. Ник сфотографировал вывеску, Дамир купил пачку печенья в дорогу, а Эрик первым признал, что кофе здесь оказался лучше, чем на предыдущей остановке. Алиса не записала ничего для статьи. Ей было достаточно этой получасовой прогулки."]},{"level":5,"title":"B. Остаться в кафе и поговорить с теми, кто хочет","paragraphs":["Алиса заняла столик у окна. Через минуту рядом сел Ник, потом Дамир; Эрик подошёл с чеком за ремонт. Они слушали местное радио, пытались угадать следующую песню и впервые за несколько дней обсуждали событие, которое не было ни работой, ни чужими чувствами."]},{"level":5,"title":"Общее продолжение","paragraphs":["До ночлега они добрались поздним вечером. За окном стали появляться низкие горы полуострова Snæfellsnes. Алиса знала, что поездка заканчивается, но больше не пыталась заранее придумать её последний абзац. У неё ещё оставалось время пережить то, о чём она потом захочет написать."]}]},{"id":"S37","title":"День 18. Эрик без списка","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":4,"title":"Если `routeStatus=paused`","paragraphs":["Эрик ждал возле гостевого дома с двумя бумажными стаканами кофе. Один он взял по привычке для Алисы, но не протянул сразу: сначала спросил, хочет ли она сегодня идти с ним. Алиса могла ответить «нет», и он был готов к этому. Она сказала, что хочет пройтись и договорить о том, что осталось между ними после Akureyri. Они пошли по освещённой улице без единого романтического жеста. Эрик говорил о зимних занятиях школы, но впервые не предлагал ей занять место рядом с его будущим графиком. Алиса рассказала о своей городской серии и призналась, что скучала по нему вчера, хотя сама попросила паузу. В ответ он не приблизился; спросил, чего она хочет сейчас. Это был вопрос о прогулке, а не о соглашении на год вперёд."]},{"level":4,"title":"Если `routeStatus=active`","paragraphs":["Наутро Эрик оставил карту в номере. Не как испытание и не как демонстрацию перемен. Просто предложил Алисе свободный день вдвоём: за кофе, за смешными открытками, в музее, если они оба захотят туда зайти. На улице было холодно. Алиса выбрала лавку, где продавались шерстяные шапки, и купила яркую, слишком большую. Эрик надел её первым, чтобы она могла оценить размер. Он выглядел настолько серьёзно, что Алиса сфотографировала его на свой телефон, прежде чем рассмеяться. Снимок остался только у неё.","Они остановились в маленьком музее рыболовства. Эрик прочёл несколько подписей на исландском и пересказал Алисе не всё подряд, а историю женщины, которая много лет вела журнал погоды для соседей. Алиса спросила, есть ли у него дома такая записная книжка. Он сказал, что есть, но половина страниц теперь занята чужими списками, присланными сестрой. Она попросила показать однажды одну из страниц, где он записал что-то для себя. Эрик обещал подумать, не превращая это в большую клятву.","В конце улицы они нашли кафе с тремя свободными столиками и одним огромным окном. Алиса села так, чтобы видеть прохожих. Эрик сел рядом, а не напротив. Он рассказывал, как сестра когда-то уговорила его выступить на семейном вечере с песней, которой он не знал. Алиса представила его в детстве с нотным листом и захотела услышать эту историю ещё раз уже дома, в другом городе."]},{"level":4,"title":"Выбор S37-C1 — чего Алиса хочет после поездки","paragraphs":[]},{"level":5,"title":"A. Предложить конкретную встречу после возвращения домой","paragraphs":["— Давай посмотрим, когда у нас совпадут два выходных, — сказала она. — Я не перееду завтра и не прошу тебя отменять работу. Но хочу увидеть тебя снова.","Эрик достал телефон. Не чтобы немедленно купить билет: они вместе отметили две возможные даты и договорились подтвердить одну после его разговора с руководителем обучения. Алиса допила кофе. Ей было хорошо от конкретной незавершённости: следующая встреча впервые зависела от двух людей, а не от программы поездки."]},{"level":5,"title":"B. Оставить близость путешествию и завершить роман","paragraphs":["— Мне было хорошо с тобой, но я не хочу строить обещание, которое сейчас не смогу выполнить.","Эрик долго смотрел в окно. Потом попросил Алису оставить ему фотографию в смешной шапке. Она отправила снимок и положила телефон. Они дошли до гостевого дома вместе; дальше каждый пошёл в свой номер. Их роман закончился, но общая дорога оставалась общей."]},{"level":5,"title":"Общее продолжение","paragraphs":["Вечером Ник спросил, удалось ли им провести день без карты. Алиса ответила, что они почти не потерялись. Эрик посмотрел на неё поверх чашки и сказал, что не уверен, где теперь лежит его шапка. Ник предложил нарисовать объявление о пропаже, и Алиса впервые за несколько дней смеялась не потому, что кто-то пытался поднять ей настроение."]},{"level":4,"title":"Выбор S37-C2 — Как Алиса предложит Эрику провести свободное утро?","paragraphs":[]},{"level":5,"title":"A. Позвать его увидеть рассвет вдвоём","paragraphs":["— Только если ты тоже хочешь, — добавила Алиса. Они вышли к освещённой дорожке ещё до того, как остальные проснулись. Эрик принёс один термос на двоих, и Алиса впервые за неделю не спросила, сколько у них времени."]},{"level":5,"title":"B. Пригласить его вместе приготовить поздний завтрак","paragraphs":["Алиса нашла на кухне муку и попросила Эрика помочь с тестом. Он прочитал рецепт дважды, а потом всё равно перепутал миски. Их завтрак вышел позже задуманного, зато Ник первым попросил добавки."]},{"level":4,"title":"Если `S50-C2=A`","paragraphs":["Во время свободного дня Эрик вспомнил рассказ о семейной настольной игре. Алиса предложила придумать одно нелепое правило для них двоих, и они рассмеялись, даже не доставая коробку."]},{"level":4,"title":"Если `S50-C2=B`","paragraphs":["На свободном дне Эрик показал Алисе сообщение сестры: та получила деревянную птицу и обещала прислать фотографию. Алиса узнала маленький подарок, который они выбрали вместе."]}]},{"id":"S51","title":"День 19. Обычный ужин","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Эрик принёс продукты к маленькой кухне, но обнаружил, что не умеет готовить выбранный Алисой рецепт из книги, купленной у Mývatn. Они договорились не обращаться к интернету, пока не испробуют собственный способ. Оказалось, на первой странице написано «оставить тесто на два часа», а ужин был нужен гораздо раньше. Алиса предложила приготовить что-то другое, но Эрик уже успел высыпать муку на стол. Пришлось вытирать её рукавом, потому что бумажные полотенца закончились.","Пока варилась картошка, они играли в карты, найденные в ящике стола. Правила были незнакомы обоим. Эрик уверял, что вспомнит их к третьему ходу, а Алиса тихо складывала выигрышные карты под локтем, потому что он отвлёкся на закипающую кастрюлю. Когда обнаружилось жульничество, он потребовал реванш после ужина. Алиса согласилась, но предупредила, что теперь будет играть честно только при наличии письменного договора. Эрик предложил нарисовать договор на бумажной салфетке.","Дождь стучал по окну. Алиса вытерла стол, Эрик выставил две тарелки. Это была самая обычная комната: чужая посуда, неровная ножка стула, инструкция к плите на другом языке. Алисе вдруг захотелось узнать, как выглядит его кухня зимой, когда никуда не нужно собираться с утра. Она сказала об этом вслух. Эрик ответил, что на полке у окна у него стоит горшок с растением, которое сестра постоянно спасает от его нерегулярного полива. Алиса предложила купить ему другое — более живучее. Он сказал, что сначала надо сохранить нынешнее.","Они сели ужинать. Тесто так и не поднялось, зато картошка получилась хорошей. Они доели её прямо из кастрюли, не делая из неудачного рецепта метафоры своих отношений. Когда Эрик наклонился за упавшей салфеткой, Алиса коснулась его плеча, чтобы он выпрямился. Он поднял голову, увидел её лицо близко и улыбнулся."]},{"level":4,"title":"Выбор S51-C1 — чем заканчивается вечер","paragraphs":[]},{"level":5,"title":"A. Остаться ещё на час вдвоём","paragraphs":["Они убрали посуду, включили музыку негромко и доиграли партию. Алиса проиграла с перевесом в одну карту; Эрик согласился не рассказывать об этом Нику. Перед сном он проводил её до двери и поцеловал, когда она сама задержалась рядом."]},{"level":5,"title":"B. Пожелать спокойной ночи и закончить день отдельно","paragraphs":["— Я хочу запомнить именно такой ужин, — сказала Алиса. — Без большого продолжения сегодня.","Эрик проводил её до двери, отдал забытый шарф и пожелал спокойной ночи. У себя в комнате Алиса нашла в кармане салфетку с нарисованным договором о честной карточной игре."]},{"level":5,"title":"Общее продолжение","paragraphs":["Наутро им оставалось два дня до возвращения в Reykjavík. Алиса не знала, получится ли назначенная встреча через месяц. Но впервые представляла её не как идеальное свидание у океана, а как человека, который пришёл на её кухню и не испугался неудачного теста."]},{"level":4,"title":"Если `S37-C2=A`","paragraphs":["За ужином Эрик вспомнил рассветную прогулку, которую Алиса предложила сама, и на минуту оставил список дел в кармане. Она улыбнулась — им было хорошо даже без назначенной следующей остановки."]},{"level":4,"title":"Если `S37-C2=B`","paragraphs":["За ужином Эрик достал миску и напомнил, как они перепутали тесто утром. Алиса сказала, что теперь умеет отличать его серьёзный взгляд над рецептом от настоящего беспокойства."]}]},{"id":"S38","title":"День 18. Скучный день, который удался","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":4,"title":"Если `routeStatus=paused`","paragraphs":["Ник встретил Алису у лестницы гостевого дома и спросил, хочет ли она пройтись без камеры. Она согласилась, предупредив, что пока не готова обсуждать продолжение романа. Они зашли за хлебом, занесли пакет хозяину и вернулись другой улицей. Ник рассказал, что продюсер подтвердил удаление спорного фрагмента из всех рабочих версий. Алиса поблагодарила его за конкретное действие, но не стала обещать, что после этого ей снова будет легко доверять ему. Они дошли до площади и сели на скамью, потому что устали."]},{"level":4,"title":"Если `routeStatus=active`","paragraphs":["Ник проснулся раньше Алисы и вместо камеры принёс к её двери два билета в небольшой местный музей. Она удивилась: прежде Ник редко планировал что-то, где нельзя ничего снять. Он сказал, что билеты можно вернуть, если она предпочитает пройтись просто так. Алиса выбрала музей, а потом захотела зайти в магазин за кофе. Ник не сделал вид, что это скучный выбор.","У музейного окна висела старая фотография семейного праздника. Люди на ней смотрели не в объектив, а друг на друга; фотографу удалось поймать момент, который никто не собирался показывать другим. Ник долго рассматривал снимок. Он признался, что, когда начинает общаться с кем-то всерьёз, ему хочется немедленно придумать для двоих необычное приключение. Будто обычной прогулки и общего завтрака недостаточно, чтобы человек остался рядом.","Алиса не ответила готовым ободряющим выводом. Она вспомнила их день с потерянной перчаткой и сказала, что тот день оказался хорошим именно потому, что они искали чужую вещь и мёрзли на остановках. Ник засмеялся: он до сих пор носил возвращённую перчатку в куртке, хотя она ему не принадлежала. Он обещал отправить её Инге почтой, но так и не выбрал конверт.","Они нашли конверт в маленьком магазине. Ник подписал адрес и поставил дату, как будто закрывал сцену в монтаже. Алиса попросила показать ей штамп почты, когда отправит. Он заметил, что она уже придумала продолжение их скучного дня, и на этот раз не стал придумывать более интересное."]},{"level":4,"title":"Выбор S38-C1 — что Алиса предлагает Нику","paragraphs":[]},{"level":5,"title":"A. Провести вместе обычный уикенд дома после путешествия","paragraphs":["— Если хочешь меня увидеть снова, приезжай в мой город. Сходим на рынок, приготовим ужин и, может быть, никуда больше не пойдём.","Ник уточнил, может ли привезти хотя бы фотоаппарат для себя. Алиса сказала, что может, но не обязана быть в его кадрах. Он ответил: «Я могу вообще оставить его в номере». Они выбрали возможный выходной, не покупая билеты заранее."]},{"level":5,"title":"B. Оставить их историю прекрасной поездкой","paragraphs":["— Мне понравилось с тобой, — сказала Алиса. — Но я не хочу обещать уикенд, пока сама не знаю, чего хочу от нас.","Ник кивнул. Он не предложил «последний лучший кадр». Вместо этого спросил, хочет ли она пройти с ним до почты, чтобы отправить перчатку. Она согласилась; это не было продолжением романа, просто делом, которое они начали вместе."]},{"level":5,"title":"Общее продолжение","paragraphs":["Вечером Ник поставил перед Алисой конверт с почтовой квитанцией. Он действительно отправил перчатку. Для фильма это было ничем не примечательное событие. Алиса положила квитанцию в книгу, которую везла домой, и подумала, что однажды, возможно, покажет её ему снова."]},{"level":4,"title":"Выбор S38-C2 — Как Алиса предложит Нику запомнить этот обычный день?","paragraphs":[]},{"level":5,"title":"A. Пригласить его на свидание без шуток о съёмке","paragraphs":["— Можно просто сходить со мной на кофе? — спросила Алиса. Ник посмотрел на неё, убедился, что она действительно ждёт ответа, и сказал «да». Уже за столиком он попытался пошутить о погоде и сам рассмеялся раньше неё."]},{"level":5,"title":"B. Предложить выбрать друг другу книгу в магазине","paragraphs":["Они нашли две дешёвые книги и обменялись ими, не читая аннотаций. Алисе достался старый сборник рассказов, Нику — книга о садовых птицах. Он сказал, что теперь обязан выяснить, что именно ему понравилось в ней больше всего."]},{"level":4,"title":"Если `S53-C2=A`","paragraphs":["Во время прогулки Ник напомнил Алисе о кофейне, в которую они договорились зайти после возвращения. Она впервые представила их встречу в обычном городе — и захотела, чтобы день наступил."]},{"level":4,"title":"Если `S53-C2=B`","paragraphs":["Во время прогулки Ник процитировал строчку из книги Алисы и попросил не рассказывать финал. Она ответила, что ещё сама не дочитала его сборник и теперь спешить не станет."]}]},{"id":"S54","title":"День 19. Не шутить на припеве","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Хозяйка гостевого дома принесла старый микрофон и спросила, не хотят ли гости устроить караоке. Ник поднял руку первым. Алиса, уже знавшая о его привычке превращать всё в выступление, приготовилась услышать длинную шутку. Но он выбрал тихую песню, которую она однажды напевала в машине. На втором куплете Ник сбился; не пытался скрыть этого и просто попросил её помочь.","Они допели вдвоём, стоя рядом у окна. На последнем припеве Ник не смотрел в зал. Он смотрел на Алису, и она почувствовала, как у неё горят щёки. Это было смешно и трогательно одновременно: человек, который так легко разговаривал со всеми, вдруг не знал, куда деть руки без камеры и микрофона.","После песни они вышли на крыльцо. Ветер гнал по земле сухие листья. Ник хотел что-то сказать, но первым делом спросил, не замёрзла ли она. Алиса ответила, что немного, и сама взяла его за локоть. Он глубоко вдохнул.","— Я хочу увидеть тебя после поездки, — сказал он. — Даже если в тот день мы просто купим хлеб и вернёмся домой.","Алиса посмотрела на тёмное окно гостевого дома. Внутри кто-то уже выбирал следующую песню, и музыка была слишком громкой для идеального признания. Ей понравилось, что Ник не пытался дождаться идеального момента."]},{"level":4,"title":"Выбор S54-C1 — ответ Алисы","paragraphs":[]},{"level":5,"title":"A. Ответить словами","paragraphs":["— Я тоже хочу. Только обещай не снимать, как я выбираю хлеб.","— Не обещаю, — сказал Ник и тут же поправился: — Обещаю спросить. Но, кажется, тебе больше понравится, если в этот раз я вообще забуду о камере."]},{"level":5,"title":"B. Ответить короткой песенной строчкой","paragraphs":["Алиса напела последнюю строку их песни так тихо, что слышал только Ник. Он улыбнулся и шагнул ближе. Впервые за весь вечер ей не захотелось, чтобы кто-нибудь запомнил это на видео."]},{"level":5,"title":"Общее продолжение","paragraphs":["Они вернулись в зал, где Эрик пытался убедить Дамира выбрать самую плохую песню из поездки. Ник сел рядом с Алисой и взял её за руку под столом. Через минуту они оба отпустили руки, чтобы аплодировать остальным. Ничего в их мире от этого не изменилось резко. Но Алиса уже ждала завтрашнего дня."]},{"level":4,"title":"Если `S38-C2=A`","paragraphs":["Перед музыкальным вечером Ник напомнил Алисе о кофе, на который она пригласила его без всякой камеры. Он сказал, что хотел бы повторить это дома, даже если не найдётся повода для красивого кадра."]},{"level":4,"title":"Если `S38-C2=B`","paragraphs":["Перед музыкальным вечером Ник достал книгу о птицах, которую выбрала ему Алиса, и показал ей закладку. Она рассмеялась: он действительно читал её, а не держал как сувенир."]}]},{"id":"S39","title":"День 18. Не повторять старую пару","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":4,"title":"Если `routeStatus=paused`","paragraphs":["Алиса и Дамир встретились у стойки гостевого дома, когда остальные выбирали маршрут. Она сама предложила пройтись к кафе и поговорить. Дамир не сделал вид, что пауза закончилась автоматически. Они заказали напитки отдельно и сели за небольшой стол. Алиса сказала, что не хочет снова проверять на нём все свои старые страхи. Дамир ответил, что тоже не хочет получать за каждый новый день оценку по событиям двухлетней давности. Они говорили спокойно и иногда замолкали; впервые молчание не означало, что один из них ждёт извинений от другого."]},{"level":4,"title":"Если `routeStatus=active`","paragraphs":["Они вышли из гостевого дома без плана. Дамир предложил пройтись до пекарни, но Алиса выбрала сначала заглянуть в маленький магазин с музыкальными открытками. Дамир признался, что даже не знал о существовании таких вещей. Алиса нажала кнопку на одной карточке, и из неё вырвалась резкая праздничная мелодия. Дамир вздрогнул; Алиса засмеялась громче, чем собиралась. Продавщица подняла голову, но, увидев их лица, улыбнулась.","В кафе они заказали два разных десерта. Когда-то Дамир всегда знал, какой пирог Алиса выберет. Сейчас он лишь спросил, хочет ли она попробовать его. Она взяла кусочек, потом отдала ему часть своего. Разговор постепенно перешёл на вещи, которых не было в их прошлом: новый сериал, который Дамир смотрел после ночных смен; подруга Алисы, открывшая мастерскую; книга, которую она купила во время поездки и ещё не дочитала.","У Дамира зазвонил телефон. Это был коллега, который просил сменить его на одной из будущих дежурных дат. Дамир отошёл, коротко объяснил, что пока не знает своего рабочего графика на следующий месяц, и пообещал ответить позже. Вернувшись, он не стал подробно пересказывать разговор и не попросил Алису одобрить своё решение. Она почувствовала странное облегчение: его жизнь оставалась его жизнью, и это не означало, что он уже отдалился от неё."]},{"level":4,"title":"Выбор S39-C1 — что Алиса предлагает после поездки","paragraphs":[]},{"level":5,"title":"A. Назначить три новых свидания в разных местах","paragraphs":["— Если мы продолжим, я не хочу сразу возвращаться к тому, как мы жили два года назад, — сказала она. — Давай сначала встретимся три раза, и каждый раз кто-то один выберет место.","Дамир предложил начать с её города и признался, что уже забыл, где там теперь открылась хорошая пекарня. Алиса ответила, что это даже к лучшему: у них будет повод найти новую."]},{"level":5,"title":"B. Закончить попытку снова стать парой","paragraphs":["— Я рада, что мы увидели друг друга другими, — сказала Алиса. — Но я не хочу продолжать роман после возвращения.","Дамир посмотрел на неё, потом на пустую чашку. Сказал, что ему тоже важно сохранить нынешний день как хорошее воспоминание, а не повод снова спорить о будущем. Они допили кофе и вернулись к машине вместе."]},{"level":5,"title":"Общее продолжение","paragraphs":["На улице снова моросил дождь. Алиса подняла воротник; Дамир не бросился поправлять ей куртку. Он просто спросил, не хочет ли она зайти за горячим хлебом для группы. Она согласилась. У них оставалось общее дело, и оно не требовало заранее знать конец их истории."]},{"level":4,"title":"Выбор S39-C2 — Как Алиса покажет Дамиру, что хочет узнать его заново?","paragraphs":[]},{"level":5,"title":"A. Предложить ему рассказать о своём самом обычном дне","paragraphs":["Дамир сначала удивился вопросу. Потом рассказал о старой кружке в ординаторской и собаке соседки, которая встречает его у двери. Алиса ответила историей о любимой булочной возле редакции. В этих рассказах не было их прежней пары."]},{"level":5,"title":"B. Самой пригласить его на прогулку перед завтраком","paragraphs":["— Не по дороге к твоему собеседованию, — добавила Алиса. Дамир улыбнулся и предложил встретиться у лестницы утром. Она поставила будильник на десять минут раньше, чем обычно, и неожиданно обрадовалась этому."]},{"level":4,"title":"Если `S56-C2=A`","paragraphs":["Возле кафе Алиса увидела блюдо, которое они с Дамиром собирались попробовать после музыкального вечера. Она предложила зайти, и он согласился без привычки сначала сверяться с рабочим расписанием."]},{"level":4,"title":"Если `S56-C2=B`","paragraphs":["Во время прогулки Дамир тихо повторил тот незнакомый припев, который Алиса пыталась ему показать. Она подхватила вторую строку и впервые за день не вспомнила их старую общую музыку."]}]},{"id":"S57","title":"День 19. Рассвет без прежних слов","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Дамир разбудил Алису коротким сообщением: пекарня откроется через двадцать минут, и он собирается за хлебом. Она могла не отвечать. Вместо этого надела куртку и вышла к нему на лестницу. Оба были сонными. Дамир держал в руках две чашки кофе и признался, что купил их заранее, хотя не знал, придёт ли она. Алиса взяла одну; кофе оказался слишком крепким, но тёплым.","В пекарне пахло хлебом и корицей. Продавец спросил, сколько им нужно булочек. Дамир хотел заказать по привычке две одинаковые, затем посмотрел на Алису. Она выбрала солёную булочку, которую он никогда не видел у неё на тарелке прежде. Он взял себе сладкую. На улице они поменялись по кусочку и оба признали, что второй выбор тоже хорош.","По освещённой дорожке к гавани почти никто не ходил. Алиса вспомнила утро их первой совместной поездки много лет назад: тогда им казалось, что впереди достаточно времени, чтобы всё успеть. Теперь времени оставалось ровно два дня, и она не хотела тратить их на сравнение. Дамир рассказывал о том, что ему понравилось на ферме: лошадь, не желавшая идти, инструктор, который не торопился, и её смех, неожиданно громкий под шлемом. Алиса смеялась снова, но уже не от фотографии.","У скамьи Дамир остановился. Он не делал шаг первым — возможно, помнил их прежние ошибки слишком хорошо. Алиса сама поставила чашку на доску, подошла и поцеловала его. Поцелуй был новым. Не потому, что они забыли прошлое, а потому, что сейчас никто не пытался восстановить его по памяти."]},{"level":4,"title":"Выбор S57-C1 — после поцелуя","paragraphs":[]},{"level":5,"title":"A. Остаться рядом и договориться о следующей встрече","paragraphs":["Алиса обняла Дамира и сказала, что хочет увидеть его дома, когда у них обоих появится свободный вечер. Он кивнул и предложил прислать свой график, как только он будет готов. Она ответила, что пришлёт свой тоже."]},{"level":5,"title":"B. Остановиться и оставить себе время","paragraphs":["Алиса отстранилась первой. Она не пожалела о поцелуе, но сказала, что до конца поездки не хочет делать новых обещаний. Дамир ответил: «Хорошо». Они доели булочки и пошли обратно рядом, не пытаясь угадать друг за друга дальнейшие слова."]},{"level":5,"title":"Общее продолжение","paragraphs":["Вернувшись, они увидели Ника у лестницы: он искал зарядку и был уверен, что оставил её в машине. Алиса предложила проверить розетку в холле. Зарядка нашлась там через минуту. Весь остаток утра они готовили выезд и смеялись над тем, сколько вещей успели потерять за три недели."]},{"level":4,"title":"Если `S39-C2=A`","paragraphs":["На рассвете Алиса вспомнила рассказ Дамира о соседской собаке и спросила, всё ли та встречает его у двери. Он рассказал свежую историю, и они засмеялись, не возвращаясь мыслями к двум годам разлуки."]},{"level":4,"title":"Если `S39-C2=B`","paragraphs":["На рассвете Дамир встретил Алису у лестницы, как она сама предложила накануне. Она посмотрела на него и поняла, что ждала именно этого простого момента."]}]},{"id":"S40","title":"День 18. Абзац, который не надо согласовывать","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Алиса открыла ноутбук у окна и прочла свой первый абзац из Кефлавика. Тогда она писала о людях, которые меняют планы, будто сама стояла в стороне и наблюдала. Теперь в тексте были конкретные дни, когда она сама выбирала остаться, уйти, помочь, не вмешиваться или просто купить книгу. Марина прислала замечание к заголовку, но не к финалу: финала пока не было.","Она разложила на столе билеты, чеки, открытки и фотографию настила. На одном чеке стояла дата их встречи с Дамиром, на другом — день, когда она купила себе книгу. Важно было не то, какой чек оказался последним. Важно, что каждую вещь она могла убрать из статьи, если не хотела превращать жизнь в материал."]},{"level":4,"title":"Выбор S40-C1 — что Алиса оставляет личным","paragraphs":[]},{"level":5,"title":"A. Написать финальный абзац без подробностей о близких","paragraphs":["Она описала дорогу и работу людей, которые остаются после туристов. Имена друзей появились только в согласованных фрагментах. Остальное осталось в её блокноте, который она не отправляла редакции."]},{"level":5,"title":"B. Написать о собственном выборе как о главном изменении","paragraphs":["Алиса вспомнила, как впервые одна ушла на концерт, и написала о времени, которое не нужно никому доказывать. Марина ответила, что это сильное окончание; попросила убрать два слишком общих предложения. Алиса убрала их без сожаления."]},{"level":5,"title":"Общее продолжение","paragraphs":["За окном Ник спорил с Дамиром, кто последним пользовался зарядкой. Эрик стучал у двери соседнего номера, потому что перепутал ключи. Алиса улыбнулась и закрыла ноутбук. Она была частью этой группы даже тогда, когда не превращала каждый разговор в сцену своего романа."]},{"level":4,"title":"Выбор S40-C2 — Что Алиса выберет для своего последнего свободного вечера?","paragraphs":[]},{"level":5,"title":"A. Сходить на местный музыкальный вечер одной","paragraphs":["Алиса купила билет у входа и села у окна. Музыка была незнакомой, но она нашла в ней несколько знакомых ритмов. После концерта записала название группы в заметки — на этот раз только для себя."]},{"level":5,"title":"B. Написать подруге и договориться о встрече дома","paragraphs":["Алиса отправила сообщение подруге: «Когда вернусь, давай без разговоров о моей командировке. Просто погуляем». Ответ пришёл почти сразу: «Договорились. Я выбираю кофе». Алиса улыбнулась телефону."]},{"level":4,"title":"Если `S63-C2=A`","paragraphs":["Вернувшись к своим заметкам, Алиса нашла билет с концерта и перечитала собственную короткую запись. В ней было больше её нынешней жизни, чем в десятке рабочих заголовков."]},{"level":4,"title":"Если `S63-C2=B`","paragraphs":["Вернувшись к заметкам, Алиса проверила расписание площадки, о которой ей рассказала соседка по концерту. На следующую поездку у неё уже был один собственный план."]}]},{"id":"S64","title":"День 19. Своя короткая дорога","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Утром Алиса проверила погоду и сообщение о состоянии местной тропы. Маршрут был коротким, и хозяйка гостевого дома нарисовала ей на листке два ориентира, чтобы она не свернула на закрытый участок. Алиса оставила группе время возвращения и вышла одна. Это была не демонстрация независимости и не попытка избежать чьих-то вопросов. Ей просто хотелось пройти несколько километров, не подстраиваясь под чужую скорость.","Ветер шёл с океана. На первой площадке Алиса села на скамью и увидела, что забыла взять ручку. В телефоне было достаточно места для заметок, но она не стала открывать рабочую папку. Вместо этого записала короткое голосовое себе: что ей понравилось в путешествии, кого она хочет увидеть дома, какую книгу всё ещё не прочла и почему хочет однажды вернуться в Исландию уже не по заданию редакции.","На обратной дороге она встретила женщину с собакой. Та спросила, не видела ли Алиса потерянную детскую шапку. Алиса не видела, но помогла проверить ближайшую скамью; шапка лежала под ней. Женщина поблагодарила и пошла обратно. Алиса улыбнулась совпадению: всё путешествие было полно потерянных вещей, которые не всегда требовали большого сюжета."]},{"level":4,"title":"Выбор S64-C1 — что она решает на обратном пути","paragraphs":[]},{"level":5,"title":"A. Подать заявку на самостоятельный журналистский проект","paragraphs":["Алиса открыла черновик письма редакции и написала три предложения о новой серии. Она не отправила письмо на ходу; вернувшись в гостевой дом, перечитала его и только тогда нажала «Отправить»."]},{"level":5,"title":"B. Оставить себе свободный месяц после поездки","paragraphs":["Алиса открыла календарь и отметила неделю без командировок. Ей захотелось просто побыть дома, приготовить завтрак и увидеть друзей. Это был план не менее конкретный, чем новый проект."]},{"level":5,"title":"Общее продолжение","paragraphs":["Вечером она вернулась к группе до ужина. Ник передал ей записку от хозяйки — та спрашивала, не хочет ли Алиса оставить книгу на полке обмена. Алиса решила забрать её домой. Ей ещё хотелось дочитать истории, которые она выбрала сама."]},{"level":4,"title":"Если `S40-C2=A`","paragraphs":["На тропе Алиса вспомнила вчерашнюю музыку и заметила, что впервые за поездку захотела вернуться на концерт не ради статьи. Она сохранила эту мысль в голосовом сообщении себе."]},{"level":4,"title":"Если `S40-C2=B`","paragraphs":["На тропе Алиса получила от подруги фотографию кофейни, в которой они договорились встретиться после возвращения. Теперь её следующий месяц уже содержал одну приятную дату."]}]},{"id":"S60","title":"День 19. Нелепые сувениры","episode":9,"source":"content/season-1-literary-episode-09.md","chunks":[{"level":0,"title":"","paragraphs":["Свет на кухне погас ровно в тот момент, когда Ник открыл пакет с продуктами. Хозяйка заглянула с фонариком и сказала, что в здании временно отключили электричество; у неё есть переносные лампы, а плитой пользоваться пока нельзя. Они устроились за столом с хлебом, сыром и горячим чаем из термосов. Ник попытался рассказать страшную историю, но на втором предложении Дамир обнаружил, что в темноте положил на хлеб кусок лимона. История не состоялась.","Алиса достала из кармана купленную открытку. Эрик принёс смешную деревянную птицу на подставке, Ник — почтовую квитанцию от отправленной перчатки, Дамир — маленькую шоколадку с той самой начинкой, которую Алиса теперь любила. Они решили обменяться нелепыми сувенирами: не дорогими подарками, а вещами, после которых кто-нибудь сможет вспомнить дорогу."]},{"level":4,"title":"Выбор S60-C1 — что Алиса оставит себе","paragraphs":[]},{"level":5,"title":"A. Деревянную птицу","paragraphs":["Эрик поставил её перед Алисой, и у птицы отвалилась голова. Ник предложил назвать это современным искусством. Алиса нашла в сумке клейкую ленту; к концу вечера птица стояла ровно, хотя наклоняла голову немного в сторону."]},{"level":5,"title":"B. Почтовую квитанцию","paragraphs":["Ник вручил ей квитанцию с серьёзным видом, будто это был документ о завершении экспедиции. Алиса положила её в книгу. Через годы она, возможно, не вспомнит адрес отправителя, но точно вспомнит день, когда они искали чужую перчатку."]},{"level":5,"title":"C. Шоколадку, которую можно съесть сразу","paragraphs":["Дамир предложил поделиться со всеми. Алиса открыла обёртку и разломила плитку на четыре неровные части. На столе осталась только блестящая фольга; все решили, что такой сувенир тоже годится."]},{"level":5,"title":"Общее продолжение","paragraphs":["Свет вернулся, когда они уже собирались расходиться. Ник хотел включить музыку, но Эрик попросил оставить ещё минуту тишины. Алиса посмотрела на друзей: за последние недели они успели наговорить друг другу много лишнего и много нужного. Сейчас было достаточно просто сидеть рядом. Завтра им предстояло вернуться в Reykjavík."]}]},{"id":"S41","title":"День 20. Последний заголовок","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["До Рейкьявика они добрались после обеда. На обратной дороге море казалось ниже, чем в первый день, хотя Алиса знала: это только усталость от машины и долгого света в окнах. Эрик припарковался возле гостевого дома, Ник помог выгрузить чемоданы, Дамир отнёс на ресепшен забытый кем-то термос. Алиса поставила свой чемодан у стены и первым делом нашла розетку для ноутбука.","Марина согласилась поговорить по видеосвязи из редакции. На столике в кафе едва поместились чашка, ноутбук и блокнот Алисы. Она открыла финальную версию текста. В ней были дорога, которую пришлось объехать, починенная тропа, несостоявшееся интервью и люди, с которыми она провела три недели. Важнее всего было решить, какие из чужих слов принадлежали статье, а какие — вечерам, о которых герои говорили только между собой.","Марина выслушала начало и предложила заголовок: «Одна поездка, три истории любви». Алиса закрыла файл на секунду, чтобы не отвечать слишком быстро. Марина не читала её личные заметки, да и Алиса не соглашалась превращать отношения в обещание читателю. Она предложила вместо этого рабочее название: «Дорога, на которой пришлось остановиться».","— Не слишком спокойно? — спросила Марина.","— Может быть. Но тут есть люди, которые живут на этой дороге, и решения, которые мы принимали не для красивой концовки.","Марина попросила показать фактические согласования с собеседниками. Алиса открыла переписку с Ингой и хозяйкой коптильни, прикрепила подтверждённые цитаты и отдельный список того, что должно остаться вне публикации. О личных разговорах с попутчиками она сказала только, что они не давали интервью для такого материала."]},{"level":4,"title":"Если `careerThesis=people`","paragraphs":["В финальном абзаце осталась Ингина фотография настила. Алиса написала о человеке, который вернётся к этой тропе завтра, когда туристы уже уедут. Марина предложила добавить одну конкретную деталь о ремонте, и Алиса взяла её из согласованного интервью, не из чужого личного разговора."]},{"level":4,"title":"Если `careerThesis=place`","paragraphs":["Алиса выбрала для финала вид дороги после дождя: ту самую площадку, где они остановились из-за колеса. Марина попросила обозначить, кто принял решение. Алиса не превратила Эрика в героя-мученика: указала, что они вместе согласились отказаться от лишней остановки, потому что безопасность была важнее красивого кадра."]},{"level":4,"title":"Если `careerThesis=own-choice`","paragraphs":["Алиса закончила рассказ собственным решением: вернуться домой не потому, что путешествие закончилось по расписанию, а потому, что она уже выбрала, чем заняться дальше. Марина предложила убрать слова «я поняла самое важное»; Алиса убрала их. Достаточно было назвать конкретную работу и конкретный день."]},{"level":4,"title":"Выбор S41-C1 — какой заголовок Алиса отправит","paragraphs":[]},{"level":5,"title":"A. «Дорога, на которой пришлось остановиться»","paragraphs":["Марина прочла его вслух, затем сказала, что для сайта добавит подзаголовок с указанием Исландии. Алиса согласилась: путешествие оставалось на первом плане, а личные жизни героев — за его пределами."]},{"level":5,"title":"B. «Три недели, которые не уместились в карту»","paragraphs":["Марина улыбнулась и сказала, что этот заголовок лучше работает с фотографией дороги. Алиса выбрала кадр Ника, который он разрешил использовать в статье, без чужих лиц и тайных разговоров."]},{"level":5,"title":"Общее продолжение","paragraphs":["Когда звонок закончился, Алиса обнаружила на столе ещё одну чашку. Её принёс Дамир, пока она говорила; горячий чай уже успел остыть. Эрик отправил в общий чат адрес кафе, где они собирались поужинать вместе в последний вечер. Ник спросил, может ли снять их за общим столом. На этот раз он не включил камеру, пока все четверо не ответили. Алиса поставила ноутбук в сумку. До вечера у неё ещё было время для собственного решения."]},{"level":4,"title":"Выбор S41-C2 — Что Алиса решит сделать после сдачи последнего текста?","paragraphs":[]},{"level":5,"title":"A. Позвать всю группу на короткую общую прогулку","paragraphs":["— Без камеры и без статьи, — предложила Алиса. Ник в ответ поднял пустые ладони, Эрик показал рукой путь к воде, а Дамир первым напомнил взять шарфы. На прогулке они говорили о самом простом: кто какие вещи забыл в гостинице."]},{"level":5,"title":"B. Оставить себе час одиночества перед общим прощанием","paragraphs":["Алиса ушла в ближайшую кофейню и заказала горячий шоколад. Она открыла телефон, но не стала проверять редакторскую переписку. Через час вернулась к группе, уже готовая слушать чужие планы на вечер."]}]},{"id":"S42","title":"День 20. Последнее свидание — не последний ответ","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":3,"title":"Если `routeIntent=eric`","paragraphs":["Эрик ждал Алису возле небольшого кафе у гавани. В руках у него был блокнот, но не путевой: на обложке сестра нарисовала деревянную птицу, похожую на сувенир из Snæfellsnes. Эрик показал две возможные даты после возвращения Алисы домой. Одну ему ещё предстояло согласовать со школой проводников. Он хотел встретиться не на работе и не между экскурсиями — приехать к ней, провести обычный выходной, а затем вместе решить, захочется ли следующей встречи.","Алиса рассказала о редакционной серии. Она не могла обещать свободное расписание, зато знала, в какой день сдаёт первый материал. Эрик предложил созвониться на следующий вечер после сдачи: не для обсуждения маршрута, а просто узнать, как у неё прошёл день. Алиса посмотрела на него и вспомнила их неудачный ужин с картошкой. Для такой встречи ей не нужно было придумывать идеальную версию себя."]},{"level":3,"title":"Если `routeIntent=nick`","paragraphs":["Ник позвал Алису в маленькую пекарню без музыкального автомата и красивого вида. Он выбрал её потому, что там продавали булочки, похожие на те, которые они ели после бассейна, и потому, что рядом была почта. Он показал подтверждение: Инга получила свои перчатки. Алиса улыбнулась, но попросила убрать телефон со стола. Он убрал его сразу. Им предстояло обсудить не кадры, а следующий день, который они могут провести вместе.","Ник предложил приехать в её город на выходные после окончания своего монтажа. Он не обещал бросить работу, не просил Алису присутствовать на съёмках и не делал из будущего уикенда сюжет для фильма. Сказал, что хотел бы приготовить с ней ужин и посмотреть старый фильм, который она давно ему советовала. Алиса удивилась, что он запомнил название."]},{"level":3,"title":"Если `routeIntent=damir`","paragraphs":["Дамир встретил Алису в кафе возле гостевого дома. Он показал сообщение о видеособеседовании: дата была назначена на следующую неделю. Он ещё не знал, возьмёт ли предложенную должность, и не просил Алису решать за него. Она рассказала о своём редакционном проекте и о трёх свиданиях, которые они придумали на Snæfellsnes. Первое можно было провести в её городе, когда у обоих появится свободный вечер. Второе они решат позже, если первое состоится. Третье пока оставалось пустой строкой.","— Мне нравится, что ты не пытаешься заполнить её сейчас, — сказала Алиса.","— Я могу предложить музей, но ты опять скажешь, что я всё запланировал.","— Можешь предложить. Я могу отказаться.","Дамир засмеялся и заказал ей чай — с той начинкой печенья, которую она теперь любила. Алиса не стала объяснять, почему это её тронуло."]},{"level":3,"title":"Выбор S42-C1 — что Алиса решает после свидания","paragraphs":[]},{"level":4,"title":"A. Продолжить роман и назначить следующую конкретную встречу","paragraphs":["— Я хочу увидеть тебя после возвращения домой, — сказала Алиса. — Давай выберем день, когда сможем просто быть вдвоём, без группы и красивой дороги.","Они сверили ближайшие свободные даты и записали одну возможную встречу, которую ещё нужно было подтвердить по работе. Ни один из них не выдавал это за решение всей дальнейшей жизни."]},{"level":4,"title":"B. Попросить время и пока не продолжать роман","paragraphs":["— Мне было важно это путешествие, — сказала Алиса. — Но я не хочу назначать следующую встречу из страха, что потом не решусь.","Партнёр принял её ответ без попытки превратить паузу в скрытое обещание. Они договорились проститься с группой завтра как друзья, не требуя немедленно определять, что будет спустя месяц."]},{"level":4,"title":"C. Закончить отношения с уважением к общему прошлому","paragraphs":["— Я не хочу продолжать роман после возвращения, — сказала Алиса. — Мне было хорошо с тобой здесь. Я хочу оставить это хорошим воспоминанием, а не обещанием, которого не смогу выполнить.","Слова дались трудно. Но, когда они вышли из кафе, никто не пытался вернуть их обратно за счёт ещё одного поцелуя или нового плана. Дорога заканчивалась; человеческое уважение — нет."]},{"level":4,"title":"Общее продолжение","paragraphs":["Вечером группа собралась за общим столом. Ник рассказал историю про потерянную перчатку в последний раз; Дамир предложил ему больше никогда не брать вещи с чужими инициалами; Эрик спросил, кто завтра отвечает за вынос мусора из гостевого дома. Алиса смеялась вместе с ними. Её личное решение не отменяло того, что у них было три недели общей жизни."]}]},{"id":"S43","title":"День 20. Вечер без обещания пары","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["Алиса вышла из кафе с ноутбуком в сумке и поняла, что до общего ужина ещё три часа. Можно было пойти в гостевой дом, можно — на набережную. Она выбрала книжный, который заметила в первый день и так ни разу не посетила. На полке с рассказами обнаружилась книга, которую она когда-то читала с отцом. Алиса перелистала её, нашла знакомую строчку, но купила другую — небольшую, о современной жизни города, в который скоро возвращалась.","В соседнем кафе она раскрыла блокнот. На одной странице стояли даты интервью, на другой — список дел после поездки: отнести чемодан в ремонт, позвонить подруге, закончить статью, купить продукты для нормального завтрака. Это были простые дела, и ей впервые захотелось не прятать их за новым большим планом.","Марина прислала сообщение: материал принят в редакционную работу, но потребуется уточнить две цитаты и заменить одну фотографию. Алиса не расстроилась. Она знала, кому написать за подтверждением фактов, и сохранила свободный вечер для себя."]},{"level":4,"title":"Выбор S43-C1 — что Алиса предложит себе на следующий месяц","paragraphs":[]},{"level":5,"title":"A. Подготовить новый самостоятельный журналистский проект","paragraphs":["Алиса составила короткое письмо Марине с предложением серии о людях, которые остаются в месте после окончания туристического сезона. Она отправила письмо только после того, как перечитала его дома и убрала из него чужие личные истории."]},{"level":5,"title":"B. Сделать паузу между поездками и вернуться к обычной жизни","paragraphs":["Алиса отметила в календаре два выходных, когда никому ничего не обещала. Она написала подруге: «В следующую субботу буду дома. Хочу тебя увидеть». Ответ пришёл почти сразу — с фотографией нового чайника и вопросом, что приготовить к завтраку."]},{"level":5,"title":"Общее продолжение","paragraphs":["На общем ужине Алиса сидела рядом с друзьями, но не искала в каждом взгляде скрытого предложения. Ник показал им пустой кадр гавани, Эрик сообщил время завтрашнего выезда, Дамир спросил, кому ещё нужен чай. Алисе было хорошо рядом с ними и хорошо от мысли, что завтра она поедет домой."]}]},{"id":"S44","title":"День 21. Эрик. Дата в блокноте","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["Утром Эрик отвёз группу к месту общего прощания, но перед этим попросил у Алисы десять минут. Они вышли к гавани, где когда-то начали разговаривать о его сестре и неотправленной открытке. В этот раз у него был готовый конверт. На обратной стороне стоял адрес сестры; внутри лежала фотография их неудачного ужина на Snæfellsnes, где они оба смотрели не в камеру, а на упавшую салфетку.","— Ты отправишь это? — спросила Алиса.","— Да. Сестра всё равно узнает от меня, как всё было, даже если фотография ей не понравится.","Алиса обняла Эрика. Он показал ей записанную дату следующего звонка и уточнил, когда можно будет подтвердить билет. Она достала свой телефон и записала то же самое, чтобы ответственность за встречу не лежала на нём одном."]},{"level":4,"title":"Выбор S44-C1 — что Алиса оставляет на прощание","paragraphs":[]},{"level":5,"title":"A. Поцеловать Эрика и подтвердить их следующую встречу","paragraphs":["Эрик поцеловал её в ответ и на секунду задержался у её плеча. Потом они пошли обратно к остальным: у Алисы впереди был самолёт, а у Эрика — работа и встреча с сестрой. Им не нужно было притворяться, что одно отменяет другое."]},{"level":5,"title":"B. Обнять его и оставить свидание без красивого финального жеста","paragraphs":["Они стояли рядом, пока не стало холодно. Алиса сказала, что хочет увидеть его через месяц, и Эрик ответил, что тоже. На прощание он отдал ей бумажную закладку с деревянной птицей — та самая всё это время лежала в его книге."]},{"level":5,"title":"Общее продолжение","paragraphs":["Спустя месяц Алиса встретила Эрика у выхода из вокзала в своём городе. Они действительно подтвердили дату, пережили один перенос рейса и успели поссориться по телефону из-за того, кто забыл купить билеты в музей. Сейчас Эрик держал небольшой рюкзак и искал глазами Алису, а не следующую указательную табличку. Она помахала ему первой. Вечером они собирались готовить ужин у неё дома; рецепт Алиса выбрала простой, без двухчасового теста."]}]},{"id":"S45","title":"День 21. Ник. Фильм без чужого голоса","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["Ник пригласил Алису посмотреть финальную рабочую версию фильма, прежде чем отправить её заказчику. На экране были дорога, починенный настил, лица людей, которые согласились на съёмку, и общий стол в последний вечер. Её частной фразы после бассейна там не было. Ник не объяснял, какой путь исправления проделал; просто показал то, что собирался публиковать, и дождался её замечаний.","Алиса увидела кадр, который сама сняла на парковке у Mývatn. Ник оставил в титрах её имя рядом с камерой. Она попросила убрать подпись из публичной версии: это был их личный опыт, а для статьи она использовала другой кадр. Ник согласился и пересохранил файл. Они не превратили это в большую сцену — у них впереди был поезд, работа и договорённость о следующем обычном уикенде."]},{"level":4,"title":"Выбор S45-C1 — что они сделают перед прощанием","paragraphs":[]},{"level":5,"title":"A. Поцеловать Ника без камеры","paragraphs":["Ник убрал телефон в карман, хотя на нём не была включена камера. Алиса засмеялась, потянулась к нему и поцеловала первой. Он обнял её за талию и на секунду уткнулся лбом в её лоб, словно всё ещё удивлялся, что можно не искать лучший ракурс."]},{"level":5,"title":"B. Договориться посмотреть фильм вместе дома","paragraphs":["— Пришли мне финальную версию, когда сможешь, — сказала Алиса. — Но давай сначала просто поужинаем.","Ник предложил приготовить пасту по их неудачному рецепту из второго эпизода. Она согласилась только при условии, что он не будет рассказывать историю о том ужине всем подряд."]},{"level":5,"title":"Общее продолжение","paragraphs":["Спустя месяц Ник действительно приехал на выходные. Они купили хлеб, нашли неработающий фонарь в прихожей Алисы и полчаса искали отвёртку. Ник предложил снять маленький фильм о ремонте, потом увидел её лицо и первым засмеялся. Фильм так и не появился. Вечером они досмотрели старую комедию, до которой в Исландии ни разу не доходили руки. Алиса уснула у него на плече до титров."]}]},{"id":"S46","title":"День 21. Дамир. Первое из трёх свиданий","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["В автобусе к аэропорту Дамир держал билет в руке, словно боялся снова потерять его между страницами паспорта. Алиса сидела рядом и слушала, как он говорит о собеседовании на следующей неделе. Он не знал, захочет ли принять должность, даже если её предложат. Она не знала, насколько плотным будет её редакционный проект. Зато оба знали дату первого свидания дома: в субботу после его дежурства, в небольшой пекарне недалеко от Алисы.","У стойки регистрации Дамир остановился и спросил, не хочет ли она перед отъездом что-то изменить в их договорённости. Алиса подумала и ответила, что хочет договориться только об одном: если кто-нибудь не сможет прийти, он скажет об этом заранее, а не исчезнет из разговора. Дамир кивнул и уточнил, что она тоже может передумать. Алиса согласилась. Их первая новая история начиналась с простых слов, а не с переезда и не с обещания никогда больше не ошибаться."]},{"level":4,"title":"Выбор S46-C1 — что Алиса говорит Дамиру перед посадкой","paragraphs":[]},{"level":5,"title":"A. Назвать встречу дома их первым новым свиданием","paragraphs":["— В субботу. И это будет первое свидание, а не продолжение того, которое мы не успели закончить два года назад.","Дамир улыбнулся и поцеловал её. Потом проводил до контроля безопасности и ушёл к своему выходу, не оборачиваясь каждые десять шагов."]},{"level":5,"title":"B. Попросить ещё раз подтвердить дату после возвращения","paragraphs":["— Напиши мне, когда приедешь. Я тоже напишу. Подтвердим субботу после того, как оба разберём чемоданы.","Дамир сказал, что сделает так. Алиса обняла его и пошла к своему выходу. Она не испытала прежнего страха, когда он остался за спиной: их встреча больше не зависела от того, кто за кем поедет."]},{"level":5,"title":"Общее продолжение","paragraphs":["Спустя месяц Алиса и Дамир встретились уже во второй раз после возвращения. Первое свидание состоялось, хотя Дамир опоздал на десять минут из-за закрытого перехода у метро и предупредил её заранее. Во второй раз место выбрала Алиса: маленький музей, затем пекарня. Дамир рассказал, что прошёл собеседование, но пока не принял решение о новой должности. Они заказали разные булочки и снова обменялись по кусочку. Впереди оставалось ещё много вопросов. Но этот день принадлежал им обоим, и никто не собирался решать его в одиночку."]}]},{"id":"S47","title":"День 21. Алиса. Письмо себе","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["До выезда Алиса вернулась к гавани одна. На мокрых досках причала лежал клочок бумаги, и она подняла его, чтобы выбросить в урну. Ветер пах рыбой и кофе из открывшегося кафе. Алиса сделала снимок на телефон — для себя, без задания редакции. Потом открыла письмо, которое написала в первый день путешествия и так и не отправила. В нём она обещала вернуться домой с готовым ответом на вопрос, какой человек может сделать её счастливой.","Она удалила письмо и написала новое: «Я хочу продолжить работу, которую выбрала, и не считать обычные дни потерянными. Хочу видеть друзей. Хочу научиться не уезжать сразу, когда дома становится тихо». Затем поставила дату следующего проекта — не потому, что обязана немедленно начать новую поездку, а чтобы не забыть, о чём думала на берегу."]},{"level":4,"title":"Выбор S47-C1 — куда она отправит письмо","paragraphs":[]},{"level":5,"title":"A. Сохранить его только для себя","paragraphs":["Алиса поставила напоминание на месяц и закрыла заметки. Ник прислал ей групповую фотографию; она сохранила её рядом с письмом, но не стала публиковать ни то, ни другое."]},{"level":5,"title":"B. Написать подруге и договориться о встрече","paragraphs":["«В субботу я дома, — написала Алиса. — Давай готовить завтрак. У меня есть книга с рецептом, который мы пока не испортили». Подруга прислала фотографию чайника и ответила: «Приходи к десяти»."]},{"level":5,"title":"Общее продолжение","paragraphs":["Спустя месяц Алиса стояла на своей кухне в домашней одежде и проверяла, не подгорели ли тосты. На столе лежала принятая в редакции статья, а рядом — новый план проекта, к которому она ещё не приступила. В телефоне были сообщения от Эрика, Ника и Дамира: каждый прислал свою фотографию дороги после возвращения. Алиса ответила всем, потом отложила телефон и села завтракать. Ничего в её жизни не стало идеальным. Но теперь ей не хотелось ждать следующего путешествия, чтобы начать жить."]}]},{"id":"S48","title":"День 21. Общий прощальный кадр","episode":10,"source":"content/season-1-literary-episode-10.md","chunks":[{"level":0,"title":"","paragraphs":["Последний общий завтрак они провели в той же маленькой кухне, где в первый день не смогли найти ключ. Теперь Ник знал, в каком ящике лежат чашки, Дамир уже не пытался приготовить еду на всех, не спросив, а Эрик сел за стол до того, как проверил машину. Алиса достала из сумки книгу о старых исландских кухнях и положила её рядом с хлебом: рецепт они всё-таки приготовили, пусть и не с первого раза.","Ник попросил разрешения снять один общий кадр. Все четверо согласились. Он поставил камеру на таймер и встал рядом с остальными, не стараясь сделать так, чтобы именно он оказался в центре. На первом снимке Дамир моргнул, на втором Эрик смотрел в сторону, на третьем Алиса засмеялась, потому что Ник едва успел добежать до стола. Они выбрали третий."]},{"level":4,"title":"Если `routeIntent=eric`","paragraphs":["Эрик передал Алисе забытую бумажную закладку и сказал, что сестра уже ждёт фотографию их ужина. Ник предложил добавить к снимку подпись «Рецепт проверен полевыми условиями», но Алиса отказалась: об этом она собиралась рассказывать сама."]},{"level":4,"title":"Если `routeIntent=nick`","paragraphs":["Ник оставил Алисе квитанцию от отправленной перчатки и спросил, не забыла ли она название фильма, который они собирались посмотреть дома. Алиса назвала его с первой попытки. Дамир заметил, что это самый надёжный план за всю поездку."]},{"level":4,"title":"Если `routeIntent=damir`","paragraphs":["Дамир спросил, не лежит ли у Алисы его шарф из Кефлавика. Она ответила, что шарф всё ещё у него, а у неё — фотография коня по имени Шум. Ник потребовал показать снимок, и Дамир впервые за поездку не возражал."]},{"level":4,"title":"Если `routeIntent=alice`","paragraphs":["Алиса предложила всем встретиться когда-нибудь снова — без журнала, фильма и заранее выбранного свидания. Эрик ответил, что знает хорошую короткую прогулку для начала; Ник попросил на этот раз не терять чужие вещи, а Дамир сказал, что привезёт нормальный шоколад."]},{"level":4,"title":"Общее продолжение","paragraphs":["У дверей гостиницы каждый проверил, не забыл ли паспорт. Ник нашёл свою зарядку там, где её оставил: в розетке у стойки. Алиса подождала, пока он вернётся за ней, и все вместе вышли к машине. У них оставалось время для личного прощания и дороги в Кефлавик. Фотография, на которой никто не получился идеально, уже лежала у Алисы в телефоне; книга, которую она собиралась дочитать, — в сумке."]},{"level":4,"title":"Если `S41-C2=A`","paragraphs":["На последнем общем сборе Ник вспомнил короткую прогулку после сдачи статьи и спросил, кто первым предложил идти без камеры. Все посмотрели на Алису; она рассмеялась."]},{"level":4,"title":"Если `S41-C2=B`","paragraphs":["На последнем общем сборе Эрик спросил Алису, помог ли ей час в кофейне. Она ответила, что наконец-то допила шоколад до того, как он остыл."]}]}]};
